/// Finds a HID-host slot by Bluetooth address.
///
/// Scans the four [`SLOT_TABLE`] records for an in-use slot whose six-byte
/// `BD_ADDR` at `+8` matches `bd_addr`. When the BTM trace level is above `2`,
/// the six address bytes are also logged.
///
/// `// inferred:` the BTM layer calls this for `BTM_ReadClockOffset` (the log
/// string in the original is `BTM: BTM_ReadClockOffset. RemBdAddr: ...`) before
/// issuing the corresponding HCI command.
///
/// # Original
/// - Ghidra: `FUN_802010A4`, `0x802010A4`, 216 bytes
/// - Evidence: `work/ghidra/main-gb/export/802010a4_FUN_802010a4.c`
///
/// # Arguments
/// - `bd_addr`: address of a six-byte Bluetooth device address.
///
/// # Returns
/// `true` when an in-use slot matches, `false` otherwise.
///
/// # Side effects
/// May emit a six-argument diagnostic at level `0xD0002`.
///
/// # Safety
/// `bd_addr` must point to at least six readable bytes.
///
/// # Confidence
/// high - the scan and the six logged bytes are explicit.
pub unsafe fn fn_802010a4(bd_addr: usize) -> bool {
    if platform::read_u8(G_BTM_LOG_LEVEL) > 2 {
        // observed: FUN_801f9dd0(0xd0002, "BTM: BTM_ReadClockOffset. RemBdAddr:
        // ...", bd_addr[0..5]) - eight arguments, one on the stack.
        call8(
            LOG_4,
            0xD0002,
            0x8034_8420,
            platform::read_u8(bd_addr) as u32,
            platform::read_u8(bd_addr + 1) as u32,
            platform::read_u8(bd_addr + 2) as u32,
            platform::read_u8(bd_addr + 3) as u32,
            platform::read_u8(bd_addr + 4) as u32,
            platform::read_u8(bd_addr + 5) as u32,
        );
    }

    let mut index: u32 = 0;
    let mut slot = SLOT_TABLE;
    loop {
        if platform::read_u8(slot + SLOT_IN_USE) != 0
            && platform::call3(
                COMPARE_BYTES,
                (slot + SLOT_BDADDR) as u32,
                bd_addr as u32,
                6,
            ) == 0
        {
            return true;
        }
        index += 1;
        slot += SLOT_STRIDE;
        if index >= SLOT_COUNT {
            return false;
        }
    }
}

/// Builds and queues HCI command `0x080B`: reversed `BD_ADDR` plus one byte.
///
/// The seven parameter bytes are the six address bytes in reverse order
/// followed by `extra`.
///
/// `// unknown:` no string in this lane names opcode `0x080B`; the bytes are
/// observed in the exported C.
///
/// # Original
/// - Ghidra: `FUN_8020DF6C`, `0x8020DF6C`, 148 bytes
/// - Evidence: `work/ghidra/main-gb/export/8020df6c_FUN_8020df6c.c`
///
/// # Arguments
/// - `bd_addr`: address of the six-byte Bluetooth address.
/// - `extra`: seventh parameter byte.
///
/// # Returns
/// `true` when a packet was allocated and queued, `false` on allocation
/// failure.
///
/// # Side effects
/// Allocates a packet, writes it and calls [`fn_8020ac78`].
///
/// # Safety
/// `bd_addr` must point to six readable bytes.
///
/// # Confidence
/// high - the packet layout is explicit.
pub unsafe fn fn_8020df6c(bd_addr: usize, extra: u8) -> bool {
    let packet = platform::call1(HEAP_ALLOC, HCI_ALLOC_CLASS);
    if packet == 0 {
        return false;
    }
    let buf = packet as usize;

    // observed: tag 10, header word 0, opcode bytes 0x0B, 0x08 -> 0x080B.
    platform::write_u16(buf + HCI_PKT_TAG, 10);
    platform::write_u16(buf + HCI_PKT_ZERO, 0);
    platform::write_u8(buf + HCI_OPCODE, 0x0B);
    platform::write_u8(buf + HCI_OPCODE + 1, 0x08);
    platform::write_u8(buf + HCI_PARAM_LEN, 7);

    // observed: param_1[5], [4], [3], [2], [1], [0] then param_2.
    for i in 0..6 {
        platform::write_u8(
            buf + HCI_PARAMS + i,
            platform::read_u8(bd_addr + (5 - i)),
        );
    }
    platform::write_u8(buf + HCI_PARAMS + 6, extra);

    fn_8020ac78(packet);
    true
}

