/// Applies a configuration response: MTU, QoS option and remote MTU clamp.
///
/// - stores the MTU from `cfg+4` at `+0x38` and clamps both to `0x69B`;
/// - copies the 22-byte QoS option at `cfg+8` to `+0x58` when present;
/// - when the unknown option at `cfg+0x20` carries a non-zero `u16` at
///   `cfg+0x22`, stores it at `+0x3C`, lowers the owner's minimum MTU at
///   `owner+0x32`, and (below `0x500`) allocates a buffer and queues HCI
///   `0x0C28` with the scaled value `(mtu * 8 + 3) / 5`.
///
/// # Original
/// - Ghidra: `FUN_80218280`, `0x80218280`, 272 bytes
/// - Evidence: `work/ghidra/main-gb/export/80218280_FUN_80218280.c`
///
/// # Arguments
/// - `channel`: child channel block.
/// - `cfg`: configuration response block.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes channel fields, lowers the owner's minimum MTU, may allocate and
/// queue HCI `0x0C28`.
///
/// # Safety
/// `channel` must be live; `cfg` must be readable through `+0x2E`.
///
/// # Confidence
/// high - the clamp and the scaled value are explicit; the option's meaning is
/// unknown.
pub unsafe fn fn_80218280(channel: usize, cfg: usize) {
    if platform::read_u8(cfg + 2) != 0 {
        let mtu = platform::read_u16(cfg + 4);
        platform::write_u16(channel + L2CAP_CH_CONFIG_MTU, mtu);
        if mtu > 0x69B {
            platform::write_u16(cfg + 4, 0x69B);
            platform::write_u16(channel + L2CAP_CH_CONFIG_MTU, 0x69B);
        }
    }

    if platform::read_u8(cfg + 6) != 0 {
        for i in 0..6 {
            platform::write_u32(
                channel + L2CAP_CH_CONFIG_B + i * 4,
                platform::read_u32(cfg + 8 + i * 4),
            );
        }
    }

    // observed: `(*(char *)(param_2 + 0x20) != 0) && (*(short *)(param_2 + 0x22) != 0)`
    if platform::read_u8(cfg + 0x20) != 0 && platform::read_u16(cfg + 0x22) != 0 {
        let value = platform::read_u16(cfg + 0x22);
        platform::write_u16(channel + L2CAP_CH_CONFIG_FLUSH, value);

        let owner = platform::read_u32(channel + L2CAP_CH_OWNER) as usize;
        if value < platform::read_u16(owner + L2CAP_CONN_MIN_MTU) {
            platform::write_u16(owner + L2CAP_CONN_MIN_MTU, value);
            if value < 0x500 {
                let packet = platform::call1(HEAP_ALLOC, HCI_ALLOC_CLASS);
                if packet != 0 {
                    let scaled = (value as u32 * 8 + 3) / 5;
                    fn_8020e968(
                        packet as usize,
                        platform::read_u16(owner + L2CAP_CH_HANDLE) as u32,
                        scaled & 0xFFFF,
                    );
                }
            }
        }
    }
}

