///
/// # Side effects
/// None; only reads.
///
/// # Safety
/// `text` must be readable for up to `limit` bytes, or for the bytes up to and
/// including the first NUL when that comes sooner.
///
/// # Confidence
/// high - the two-part loop condition and the pointer difference are literal.
pub unsafe fn fn_80224390(text: usize, limit: i32) -> i32 {
    let mut offset = 0usize;
    let mut remaining = limit;
    // observed: `while ((*pcVar2 != '\0') && (param_2 = param_2 + -1, param_2 != -1))`
    while platform::read_u8(text + offset) != 0 && remaining != 0 {
        remaining -= 1;
        offset += 1;
    }
    offset as i32
}

