        // observed: `FUN_80229e20(param_1 + 5,0,0);`
        fn_80229e20(object + RANGE_OWNER_OFFSET, 0, 0);
        platform::write_u8(object + CLASS16C_VTABLE_ARMED, 1);
        platform::write_u8(object + CLASS16C_ARRAY_READY, 1);
