    // observed: DAT_803d4704 = 0; DAT_803d4706 = 0; DAT_803d4701 = 1.
    platform::write_u16(HID_CTRL_803D46F0 + 0x14, 0);
    platform::write_u16(HID_CTRL_803D46F0 + 0x16, 0);
