/// Finishes an allocated RFCOMM frame and submits it.
///
/// The buffer already exists: `packet + 4` holds the frame header word and
/// `packet + 2` the payload length. The routine:
///
/// 1. subtracts 3 from the header word (4 when the length at `+2` exceeds
///    `0x7F`, because the length field then needs two bytes),
/// 2. subtracts one more byte when `mode != 0` and the payload length at
///    `+6` is non-zero,
/// 3. writes the control byte `((flag != 0) << 1) | 1 | (mode << 2)` and the
///    `0xEF`/`0xFF` type byte at the resulting offset,
/// 4. appends the one- or two-byte length field, the optional extra byte and
///    the two-byte checksum over the control and type bytes,
/// 5. submits the frame either to the send queue ([`fn_8021ebc8`], `mode == 0`)
///    or to the L2CAP data-write entry (`0x80212F34`, `mode != 0`).
///
/// # Original
/// - Ghidra: `FUN_8021D0D8` at `0x8021D0D8` (408 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8021d0d8_FUN_8021d0d8.c`
///
/// # Arguments
/// - `channel`: DLC/channel pointer used for the submission and the `+0x6D`
///   flag (the only field read from it).
/// - `mode`: `0` = queue through RFCOMM, non-zero = hand to L2CAP.
/// - `packet`: address of the preallocated frame buffer.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Rewrites the header/length/type fields of `packet` and submits or frees it
/// through one of the two sinks.
///
/// # Safety
/// `packet` must be a writable frame buffer with at least 0x20 bytes, and
/// `channel` readable at `+0x6D` (plus `+0x68` when `mode != 0`).
///
/// # Confidence
/// high - every offset, mask and the final branch are literal in the export.
pub unsafe fn fn_8021d0d8(channel: u32, mode: u32, packet: u32) {
    let buf = packet as usize;
    let flag = platform::read_u8(channel as usize + RF_DLC_CHANNEL_FLAG);

    // observed: `sVar2 = *(short *)(param_3 + 4); ... = sVar2 + -3;`
    let header = platform::read_u16(buf + 4);
    let mut offset = header.wrapping_sub(3);

    // observed: `if (0x7f < *(ushort *)(param_3 + 2)) ... = sVar2 + -4;`
    let length_field = platform::read_u16(buf + 2);
    if length_field > 0x7F {
        offset = header.wrapping_sub(4);
    }

    // observed: `uVar4 = (param_2 == 0) ? 0 : (*(ushort *)(param_3 + 6) & 0xff);`
    let extra = if mode == 0 {
        0
    } else {
        platform::read_u16(buf + 6) as u8
    };

    if extra != 0 {
        offset = offset.wrapping_sub(1);
    }

    // observed: `iVar7 = param_3 + (uint)*(ushort *)(param_3 + 4);`
    let start = buf + offset as usize;

    // observed: `(cVar1 != '\0') << 1 | 1U | (byte)(param_2 << 2)`
    let control = (((flag != 0) as u8) << 1) | 1 | ((mode as u8) << 2);
    platform::write_u8(start + 8, control);

    // observed: `(byte)((int)-uVar4 >> 0x1f) & 0x10 | 0xef`
    platform::write_u8(start + 9, 0xEF | if extra != 0 { 0x10 } else { 0 });

    // observed: the one-byte length form is used while the field is < 0x80.
    let cursor;
    if length_field < 0x80 {
        platform::write_u8(start + 10, ((length_field as u8) << 1) | 1);
        cursor = start + 0x0B;
        platform::write_u16(buf + 2, length_field.wrapping_add(3));
    } else {
        platform::write_u8(start + 10, (length_field as u8) << 1);
        platform::write_u8(start + 0x0B, (length_field >> 7) as u8);
        cursor = start + 0x0C;
        platform::write_u16(buf + 2, length_field.wrapping_add(4));
    }

    if extra != 0 {
        platform::write_u8(cursor, extra);
        let len = platform::read_u16(buf + 2);
        platform::write_u16(buf + 2, len.wrapping_add(1));
    }

    // observed: `uVar3 = *(ushort *)(param_3 + 2); ... checksum over iVar7+8`.
    let len = platform::read_u16(buf + 2);
    let start = buf + platform::read_u16(buf + 4) as usize;
    platform::write_u16(buf + 2, len.wrapping_add(1));

    let checksum = fn_8021e44c(2, start + 8);
    platform::write_u8(start + len as usize + 8, checksum as u8);

    if mode == 0 {
        fn_8021ebc8(channel, packet);
    } else {
        let handle = platform::read_u16(channel as usize + 0x68);
        platform::call2(L2CAP_DATA_WRITE, handle as u32, packet);
    }
}

