/// Reads fixed globals only.
///
/// # Confidence
/// high - three literal comparisons.
pub unsafe fn fn_802075a4(handle: u32) -> u32 {
    let mut record = CONN_SLOT_TABLE;
    let mut index: u32 = 0;

    loop {
        if platform::read_u16(record + CONN_SLOT_IN_USE) == 4
            && platform::read_u16(record + 0x0A) == handle as u16
        {
            return 1;
        }
        index += 1;
        record += CONN_SLOT_STRIDE;
        if index >= CONN_SLOT_COUNT {
            return 0;
        }
    }
}

