// --- HID-host device records (`0x803D4838`) --------------------------------

/// Byte distance between two HID-host device records (52 bytes).
///
/// `// observed:` every per-device access in
/// `80210100_FUN_80210100.c`..`8021254c_FUN_8021254c.c` is a byte offset plus
/// `index * 0x34`.
const HID_REC_STRIDE: usize = 0x34;

/// Number of device records the host-mode init path clears.
///
/// `// observed:` `FUN_80210634` zeroes sixteen pairs of bytes at `+0` and
/// `+0x10`; `16 * 0x34 = 0x340` ends exactly at the owner callback
/// `0x803D4B78`, which is what makes the "pool" `0x404` bytes long.
const HID_REC_COUNT: u32 = 16;

/// Largest record index the per-record API accepts (`index < 0x11`).
const HID_REC_INDEX_LIMIT: u32 = 0x11;

/// `u8` "record occupied" flag at `+0`.
const HID_REC_IN_USE: usize = 0x00;

/// Six-byte `BD_ADDR` at `+1` (the address passed to the L2CAP originate).
const HID_REC_BDADDR: usize = 0x01;

/// `u8` peer state at `+0x0A`; `1` means a control channel is still open.
const HID_REC_PEER_STATE: usize = 0x0A;

/// `u8` "tearing down" flag at `+0x0C`; set before every teardown call.
const HID_REC_FLAG: usize = 0x0C;

/// `u8` channel state at `+0x10` (`0` idle, `1` originating, `5` disconnecting).
const HID_REC_STATE: usize = 0x10;

/// `u8` second state byte at `+0x11`; set to `1` when an originate starts.
const HID_REC_SUBSTATE: usize = 0x11;

/// `u16` HID-control L2CAP channel id (PSM `0x11`) at `+0x14`.
const HID_REC_CTRL_CID: usize = 0x14;

/// `u16` HID-interrupt L2CAP channel id (PSM `0x13`) at `+0x16`.
const HID_REC_INTR_CID: usize = 0x16;

/// `u16` minimum MTU (`0x100`) written before an originate, at `+0x1A`.
const HID_REC_MTU: usize = 0x1A;

/// Timer object at `+0x1C`; cancelled by [`fn_80210100`] and [`fn_8021036c`].
const HID_REC_TIMER: usize = 0x1C;

/// `0x803D4B78`: owner callback the pool enable path installs.
///
/// `// observed:` `fn_8020fe10` stores the caller's word here; the HID-host
/// handlers call it as `(index, event, param, 0)`.
const HID_OWNER_CALLBACK: usize = 0x803D_4B78;

/// HID control (`0x11`) and interrupt (`0x13`) L2CAP PSMs.
const HID_PSM_CONTROL: u32 = 0x11;
const HID_PSM_INTERRUPT: u32 = 0x13;

/// `0x802F7070`: ten-word L2CAP callback block used for both HID PSMs.
const HID_CALLBACK_TABLE: usize = 0x802F_7070;

/// `u16`/`u32` host defaults written before the PSM registration.
///
/// `// inferred:` the widths follow from the layout. `0x803D4B7E` and
/// `0x803D4B80` cannot both be 32-bit words because they would overlap, and
/// the `0xFFFF` written at `0x803D4B9E` only fits a 16-bit store.
const HID_CFG_4B7E: usize = 0x803D_4B7E;
const HID_CFG_4B80: usize = 0x803D_4B80;
const HID_CFG_4B9C: usize = 0x803D_4B9C;
const HID_CFG_4B9E: usize = 0x803D_4B9E;

/// Diagnostics emitted by the HID-host pool cluster.
const S_HID_CTRL_REG_FAILED: u32 = 0x8034_9DD8;
const S_HID_INTR_REG_FAILED: u32 = 0x8034_9DF8;
const S_HID_POOL_DISCONNECT: u32 = 0x8034_9E1C;
const S_HID_POOL_ORIGINATE_FAILED: u32 = 0x8034_9F3C;

/// Address of HID-host device record `index`.
fn hid_record(index: u32) -> usize {
    BTM_POOL + index as usize * HID_REC_STRIDE
}

