const EXI_HANDLER_80228310: u32 = 0x8022_8310;

/// `0x80228334`: EXI interrupt handler installed for IRQ `0x19`.
///
/// `// observed:` the same gap; Ghidra prints it as `LAB_80228334`.
const EXI_IRQ_80228334: u32 = 0x8022_8334;

/// `0x801AB2E0`: initialise a synchronisation object at the given address.
const SYNC_INIT_801AB2E0: usize = 0x801A_B2E0;

/// `0x803D9ED0`: synchronisation object initialised at the end of
/// [`fn_802247d0`].
const IPC_SYNC_OBJECT: u32 = 0x803D_9ED0;

/// `0x34000000`: first EXI/SEEPROM status byte read by [`fn_80228408`].
///
/// `// unknown:` the export only shows the address and a one-byte read; bit
/// `0x08` means "device busy/failed".
const EXI_STATUS_0: u32 = 0x3400_0000;

/// `0x34000200`: 32-bit identity word read by [`fn_80228408`].
const EXI_IDENTITY_200: u32 = 0x3400_0200;

/// `0xD11000`: base of the device block selected by bit 16 of
/// [`SDA_EXI_BLOCK_ID`], scaled by `0x40`.
///
/// `// unknown:` the export shows only the arithmetic; the second half is at
/// `+0x800 * 0x40`.
const EXI_BLOCK_BASE: u32 = 0x00D1_1000;

/// Compares a candidate record against a reference record.
///
/// Both records start with a `u16` kind. The reference carries a 12-bit kind
/// mask at `+6`; when the candidate's kind is not in that mask the records do
/// not match. Kinds `2` and `4` compare one `u16` or one 32-bit word at `+4`
/// against `+8`, and every other kind compares `0x10` bytes at those offsets.
///
/// # Original
/// - Ghidra: `FUN_802241b4` at `0x802241B4` (144 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802241b4_FUN_802241b4.c`
///
/// # Arguments
/// - `candidate`: record to test; kind `u16` at `+0`, value at `+4`.
/// - `reference`: record holding the mask at `+6` and the value at `+8`.
///
/// # Returns
/// `1` when the kind is accepted and the values are equal, `0` otherwise.
///
/// # Side effects
/// None: only reads. The comparison helper `0x802DF098` is `memcmp`.
///
/// # Safety
/// `candidate` must be readable for `0x14` bytes and `reference` for `0x18`.
///
/// # Confidence
/// high - the mask test, all three comparisons and the `countLeadingZeros`
/// equality idiom are literal in the export.
pub unsafe fn fn_802241b4(candidate: usize, reference: usize) -> u32 {
    let kind = platform::read_u16(candidate);

    // observed: `if (uVar1 == (*(ushort *)(param_2 + 6) & 0xfff))`
    if kind != (platform::read_u16(reference + 6) & 0x0FFF) {
        return 0;
    }

    let equal = match kind {
        // observed: `countLeadingZeros((uint)*(ushort *)(param_2 + 8) -
        // (uint)param_1[2]) >> 5 & 0xff`
        2 => platform::read_u16(candidate + 4) == platform::read_u16(reference + 8),
        // observed: 32-bit comparison of `*(int *)(param_1 + 2)` and
        // `*(int *)(param_2 + 8)`.
        4 => platform::read_i32(candidate + 4) == platform::read_i32(reference + 8),
        // observed: `FUN_802df098(param_1 + 2, param_2 + 8, 0x10)`, i.e.
        // `memcmp` over sixteen bytes. `param_1` is a `ushort *`, so `+2`
        // elements is `+4` bytes.
        _ => platform::call3(
            CMP_BYTES_802DF098,
            (candidate + 4) as u32,
            (reference + 8) as u32,
            0x10,
        ) == 0,
    };

    equal as u32
}

/// Runs one bubble pass over a `u16` array and restarts after every swap.
///
/// The array starts at `base + 0x4E`; adjacent entries are compared and
/// swapped when the second is smaller, after which the index is forced back to
/// zero (`uVar3 = 0xffff` then `++` makes the masked index `0`). The result is
/// a full ascending sort when the routine is called repeatedly.
///
/// # Original
/// - Ghidra: `FUN_80224244` at `0x80224244` (80 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80224244_FUN_80224244.c`
///
/// # Arguments
/// - `count`: number of `u16` entries.
/// - `base`: structure whose `u16` array begins at `+0x4E`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes the sorted array back in place.
///
/// # Safety
/// `base` must be writable for `0x50 + count * 2` bytes.
///
/// # Confidence
/// high - the pair compare, the two stores and the restart are literal.
/// `// observed:` the loop index is masked to 16 bits, so a `count` above
/// `0x10001` can never terminate; that is reproduced as written.
pub unsafe fn fn_80224244(count: u32, base: usize) {
    if count < 2 {
        return;
    }

    let limit = (count - 1) as i32;
    let mut index: u32 = 0;
    loop {
        if (index & 0xFFFF) as i32 >= limit {
            break;
        }

        let pair = base + (index & 0xFFFF) as usize * 2;
        let first = platform::read_u16(pair + 0x4E);
        if platform::read_u16(pair + 0x50) < first {
            platform::write_u16(pair + 0x4E, platform::read_u16(pair + 0x50));
            // observed: `uVar3 = 0xffff;` so the next masked index is zero.
            index = 0xFFFF;
            platform::write_u16(pair + 0x50, first);
        }

        index = index.wrapping_add(1);
    }
}

/// Caches the OS arena bounds into SDA1 on first use.
///
/// The two accessors `0x801B6600`/`0x801B6610` return the arena end and the
/// arena frontier; both are stored twice: once as the pristine mirror and once
/// as the live values that [`fn_80224380`] advances.
///
/// # Original
/// - Ghidra: `FUN_802242a0` at `0x802242A0` (76 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802242a0_FUN_802242a0.c`
///
/// # Arguments
/// None.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes five SDA1 words/bytes, but only when [`SDA_ARENA_READY`] is zero.
///
/// # Safety
/// Must be called before any other arena helper; no pointer arguments.
///
/// # Confidence
/// high - the guard and the four stores are literal; the only inference is
/// which accessor is the end and which is the frontier, and the guard in
/// [`fn_802247d0`] (`end < frontier + size`) proves the assignment.
pub unsafe fn fn_802242a0() {
    if platform::read_u8(SDA_ARENA_READY) != 0 {
        return;
    }

    let end = call0_ret(ARENA_END_801B6600);
    platform::write_u32(SDA_ARENA_END_CACHED, end);

    let frontier = call0_ret(ARENA_FRONTIER_801B6610);
    platform::write_u32(SDA_ARENA_FRONTIER_CACHED, frontier);

    // observed: the export stores `-0x4ad8 = -0x4ad0` (the cached end) and
    // `-0x4adc = uVar1` (the frontier).
    platform::write_u32(SDA_ARENA_END, end);
    platform::write_u32(SDA_ARENA_FRONTIER, frontier);
    platform::write_u8(SDA_ARENA_READY, 1);
}

/// Re-reads the OS arena bounds and re-arms the live values.
///
/// Identical to [`fn_802242a0`] except that it does not test the ready byte:
/// it clears it, recomputes both bounds from the OS accessors and sets it
/// again, so the live frontier is reset to the current arena frontier.
///
/// # Original
/// - Ghidra: `FUN_802242f0` at `0x802242F0` (72 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802242f0_FUN_802242f0.c`
///
/// # Arguments
/// None.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Overwrites the five arena words in SDA1; any heap carved since the last
/// refresh becomes invisible to the allocator again.
///
/// # Safety
/// Callers must not hold a live heap slot when this runs.
///
/// # Confidence
/// high - the body is the same store sequence as [`fn_802242a0`] without the
/// early-out.
pub unsafe fn fn_802242f0() {
    platform::write_u8(SDA_ARENA_READY, 0);

    let end = call0_ret(ARENA_END_801B6600);
    platform::write_u32(SDA_ARENA_END_CACHED, end);

    let frontier = call0_ret(ARENA_FRONTIER_801B6610);
    platform::write_u32(SDA_ARENA_FRONTIER_CACHED, frontier);

    platform::write_u32(SDA_ARENA_END, end);
    platform::write_u32(SDA_ARENA_FRONTIER, frontier);
    platform::write_u8(SDA_ARENA_READY, 1);
}

