/// # Confidence
/// high - the fill address, the `0x22` length and both stores are literal.
pub unsafe fn fn_80205fec(index: i32) {
    let record = SCO_POOL_803D2044 + index as usize * SCO_POOL_STRIDE;
    platform::call3(MEMSET_WRAPPER, record as u32, 0, SCO_POOL_STRIDE as u32);
    platform::write_u8(record + SCO_POOL_STATE, 0);
}

/// Loads the default link parameters from the ROM table.
///
/// Copies the four words at `0x802F7050..0x802F705C` into
/// [`BTM_LINK_PARAMS_803D3470`], marks the link interval invalid (`0xFFFF`) and
/// sets the mode byte at [`BTM_LINK_FLAG_803D3481`] to `2`.
///
/// # Original
/// - Ghidra: `FUN_802068C4` at `0x802068C4` (68 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802068c4_FUN_802068c4.c`
///
/// # Arguments
/// None.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes five words and one byte in the BTM block.
///
/// # Safety
/// No pointer arguments; fixed BSS and ROM only.
///
/// # Confidence
/// medium - all six stores are literal; the individual meanings of the four
/// copied words are `// inferred:` from their position next to
/// [`BTM_LINK_INTERVAL`].
pub unsafe fn fn_802068c4() {
    platform::write_u16(BTM_LINK_INTERVAL, 0xFFFF);

    let mut index = 0usize;
    while index < 4 {
        let value = platform::read_u32(0x802F_7050 + index * 4);
        platform::write_u32(BTM_LINK_PARAMS_803D3470 + index * 4, value);
        index += 1;
    }

    platform::write_u8(BTM_LINK_FLAG_803D3481, 2);
}

