/// Handles a connect/config request payload whose mode byte selects the path.
///
/// Reads the handle from payload `+0`, a twelve-bit length from `+1..+2`, and
/// the six-byte address stored in reverse order at `+3..+8`. Mode byte `+9`
/// equal to `1` runs the local fast path (`0x8020933C` then `0x80214870`);
/// otherwise a `0x0E`-byte configuration block is zeroed, the address is copied
/// to its `+4`, and `0x80206E50` is called with
/// `(handle, address, length, config)`.
///
/// # Original
/// - Ghidra: `FUN_8020AE04` at `0x8020AE04` (220 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8020ae04_FUN_8020ae04.c`
///
/// # Arguments
/// - `payload`: address of the received packet.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Calls into the L2CAP connection machinery; writes a stack block.
///
/// # Safety
/// `payload` must be readable for eleven bytes.
///
/// # Confidence
/// medium - the extraction and both call shapes are literal; the address
/// reversal and the `& 0xFFF` mask are copied verbatim, and the extra fourth
/// operand the export prints on the memset wrapper is dropped because the
/// wrapper is a `(dst, value, len)` routine (see [`MEMSET_WRAPPER`]).
pub unsafe fn fn_8020ae04(payload: u32) {
    let base = payload as usize;

    let handle = platform::read_u8(base) as u32;
    let len = (platform::read_u8(base + 1) as u32
        | (platform::read_u8(base + 2) as u32) << 8)
        & 0x0FFF;

    // observed: local_28..local_23 <- payload[8], payload[7] ... payload[3]
    let mut address = crate::platform::GuestLocal::new( [0u8; 6]);
    let mut index = 0usize;
    while index < 6 {
        address[index] = platform::read_u8(base + 8 - index);
        index += 1;
    }

    if platform::read_u8(base + 9) == 1 {
        platform::call3(
            EVENT_8020933C,
            address.as_mut_ptr() as u32,
            len,
            handle,
        );
        platform::call3(
            EVENT_80214870,
            handle,
            len,
            address.as_mut_ptr() as u32,
        );
    } else {
        let mut config = crate::platform::GuestLocal::new( [0u8; 0x0E]);
        platform::call3(MEMSET_WRAPPER, config.as_mut_ptr() as u32, 0, 0x0E);
        platform::call3(
            MEMCPY,
            config.as_mut_ptr() as u32 + 4,
            address.as_ptr() as u32,
            6,
        );
        platform::call4(
            EVENT_80206E50,
            handle,
            address.as_mut_ptr() as u32,
            len,
            config.as_mut_ptr() as u32,
        );
    }
}

/// Splits a three-byte tag and a six-byte address out of a short payload.
///
/// Copies payload `+8,+7,+6` into the low three bytes of a nine-byte block and
/// the address (`+5..+0`, reversed) into `+4..+9`, leaving `+3` untouched as in
/// the original frame. Mode byte `+9` equal to `1` selects `0x8020885C`,
/// otherwise `0x80206C70`; both receive `(address, tag)`.
///
/// # Original
/// - Ghidra: `FUN_8020AEE0` at `0x8020AEE0` (140 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8020aee0_FUN_8020aee0.c`
///
/// # Arguments
/// - `payload`: address of the received packet.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Builds a stack block and forwards it to one of the two handlers.
///
/// # Safety
/// `payload` must be readable for ten bytes.
///
/// # Confidence
/// medium - the byte moves and the mode test are literal; the meaning of the
/// three-byte tag is `// unknown:`.
pub unsafe fn fn_8020aee0(payload: u32) {
    let base = payload as usize;

    let mut block = crate::platform::GuestLocal::new( [0u8; 9]);
    block[0] = platform::read_u8(base + 8);
    block[1] = platform::read_u8(base + 7);
    block[2] = platform::read_u8(base + 6);

    let mut index = 0usize;
    while index < 6 {
        block[4 + index] = platform::read_u8(base + 5 - index);
        index += 1;
    }

    if platform::read_u8(base + 9) == 1 {
        platform::call2(
            EVENT_8020885C,
            block.as_mut_ptr() as u32 + 4,
            block.as_mut_ptr() as u32,
        );
    } else {
        platform::call2(
            EVENT_80206C70,
            block.as_mut_ptr() as u32 + 4,
            block.as_mut_ptr() as u32,
        );
    }
}

/// Repacks a QoS report into the block layout the completion handler reads.
///
/// The payload carries a handle at `+0`, a length at `+1..+2`, two bytes at
/// `+3..+4` and four little-endian words at `+5..+0x14`. The words are copied
/// to block offsets `+4`, `+0x0C`, `+0x10` and `+0x14`; `+0`/`+1` receive the
/// two bytes. The result is handed to `0x80201754` with
/// `(handle, length, block)`.
///
/// # Original
/// - Ghidra: `FUN_8020AF6C` at `0x8020AF6C` (256 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8020af6c_FUN_8020af6c.c`
///
/// # Arguments
/// - `payload`: address of the received packet.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes a `0x18`-byte stack block and calls the completion handler.
///
/// # Safety
/// `payload` must be readable for `0x15` bytes.
///
/// # Confidence
/// medium - the offsets are literal and corroborated by the field reads in
/// `80201754_FUN_80201754.c`; the word meanings stay `// unknown:`.
pub unsafe fn fn_8020af6c(payload: u32) {
    let base = payload as usize;

    let mut block = crate::platform::GuestLocal::new( [0u8; 0x18]);
    block[0] = platform::read_u8(base + 3);
    block[1] = platform::read_u8(base + 4);

    let targets = [4usize, 0x0C, 0x10, 0x14];
    let mut slot = 0usize;
    while slot < targets.len() {
        let offset = 5 + slot * 4;
        // observed: little-endian word - byte order in the export is
        // `+0, +1<<8, +2<<16, +3<<24`.
        let value = platform::read_u8(base + offset) as u32
            | (platform::read_u8(base + offset + 1) as u32) << 8
            | (platform::read_u8(base + offset + 2) as u32) << 16
            | (platform::read_u8(base + offset + 3) as u32) << 24;
        platform::write_u32(block.as_mut_ptr() as usize + targets[slot], value);
        slot += 1;
    }

    let handle = platform::read_u8(base) as u32;
    let length = platform::read_u8(base + 1) as u32
        | (platform::read_u8(base + 2) as u32) << 8;

    platform::call3(
        EVENT_80201754,
        handle,
        length,
        block.as_mut_ptr() as u32,
    );
}

/// Builds the configuration block for a connect/config request payload.
///
/// The `0x0E`-byte block is filled as: two little-endian halves from payload
/// `+0x0C..+0x0F` at `+0`/`+2`; the reversed address (`+8..+3`) at `+4`; and
/// the four option bytes payload `+9`, `+0x0A`, `+0x0B`, `+0x10` at
/// `+0x0A..+0x0D`. The address is copied into place with `0x80004364` exactly
/// as in the export, and `0x80206E50` is called with
/// `(handle, address, length, block)`.
///
/// # Original
/// - Ghidra: `FUN_8020B06C` at `0x8020B06C` (224 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8020b06c_FUN_8020b06c.c`
///
/// # Arguments
/// - `payload`: address of the received packet.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes a `0x0E`-byte stack block and calls the connection dispatcher.
///
/// # Safety
/// `payload` must be readable for `0x11` bytes.
///
/// # Confidence
/// medium - the extraction, the memcpy and the call are literal; the two
/// halves and the four option bytes have `// unknown:` meanings.
pub unsafe fn fn_8020b06c(payload: u32) {
    let base = payload as usize;

    let handle = platform::read_u8(base) as u32;
    let length = platform::read_u8(base + 1) as u32
        | (platform::read_u8(base + 2) as u32) << 8;

    let mut address = crate::platform::GuestLocal::new( [0u8; 6]);
    let mut index = 0usize;
    while index < 6 {
        address[index] = platform::read_u8(base + 8 - index);
        index += 1;
    }

    let mut config = crate::platform::GuestLocal::new( [0u8; 0x0E]);
    let first = platform::read_u8(base + 0x0C) as u16
        | (platform::read_u8(base + 0x0D) as u16) << 8;
    let second = platform::read_u8(base + 0x0E) as u16
        | (platform::read_u8(base + 0x0F) as u16) << 8;
    platform::write_u16(config.as_mut_ptr() as usize, first);
    platform::write_u16(config.as_mut_ptr() as usize + 2, second);

    platform::call3(
        MEMCPY,
        config.as_mut_ptr() as u32 + 4,
        address.as_ptr() as u32,
        6,
    );

    config[0x0A] = platform::read_u8(base + 9);
    config[0x0B] = platform::read_u8(base + 0x0A);
    config[0x0C] = platform::read_u8(base + 0x0B);
    config[0x0D] = platform::read_u8(base + 0x10);

    platform::call4(
        EVENT_80206E50,
        handle,
        address.as_mut_ptr() as u32,
        length,
        config.as_mut_ptr() as u32,
    );
}

/// `0x80349838`: format string `"Event mismatch opcode X, cmd opc..."`.
const MSG_HCI_EVENT_MISMATCH: usize = 0x8034_9838;

/// `0x80349860`: format string `"Cmd timeout: no cmd in queue"`.
const MSG_HCI_NO_CMD: usize = 0x8034_9860;

/// `0x80349880`: format string `"BTU HCI command timeout : cmd op..."`.
const MSG_HCI_CMD_TIMEOUT: usize = 0x8034_9880;

/// `0x80205350`: command-complete handler for opcode `0x0C05`.
const EVENT_80205350: usize = 0x8020_5350;

/// `0x802065EC`: handlers for the page/connection opcodes `0x0801..0x0806`.
const EVENT_802065EC: usize = 0x8020_65EC;

/// `0x80205A3C`: remote-name-request completion, four-argument form.
const EVENT_80205A3C: usize = 0x8020_5A3C;

/// `0x80208A98`: remote-name-request store, three-argument form.
const EVENT_80208A98: usize = 0x8020_8A98;

/// `0x80201320`: role-switch event handler (takes `(status, address, role)`).
const EVENT_80201320: usize = 0x8020_1320;

/// `0x8021571C`: role-switch follow-up with no arguments.
const EVENT_8021571C: usize = 0x8021_571C;

/// `0x802075A4`: predicate "the controller still knows this connection".
const EVENT_802075A4: usize = 0x8020_75A4;

/// `0x802074A0`: six-argument connection/authentication helper.
const EVENT_802074A0: usize = 0x8020_74A0;

/// `0x80203FE8`: invokes the device-ready callback when one is installed.
const EVENT_80203FE8: usize = 0x8020_3FE8;

/// `0x802099B4`: link-key notification store.
///
/// `// observed:` looks the address up in the device table, then stores the key
/// type at `+0x83` and the sixteen key bytes at `+0x25`; its own trace strings
/// name it `btm_sec_link_key_notification`.
const EVENT_802099B4: usize = 0x8020_99B4;

/// `0x8021078C`: per-index HID-host release used by [`fn_8020fe8c`].
const HID_RELEASE_8021078C: usize = 0x8021_078C;

/// Routes a command-complete/status event to its per-opcode handler.
///
/// This is the hub the HCI event path funnels into. It compares the opcode
/// against a small set of literals and forwards the caller's payload; anything
/// in the vendor range `0xFC00..0xFFFF` additionally goes through the
/// eight-argument vendor event handler at `0x802038C8`.
///
/// # Original
/// - Ghidra: `FUN_8020B14C` at `0x8020B14C` (340 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8020b14c_FUN_8020b14c.c`
///
/// # Arguments
/// - `opcode`: HCI opcode that completed (`0x0C03`, `0x1005`, `0x1403`, ...).
/// - `payload`: address of the command's return parameters.
/// - `len`: parameter byte count.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Calls exactly one handler (two for `0x0419`), or none.
///
/// # Safety
/// `payload` must be readable for at least `len` bytes.
///
/// # Confidence
/// high - the comparison tree, the per-branch argument counts and the
/// `& 0xFC00` vendor test are literal. Callees that only take one argument in
/// their own translation are still called with the full register set the
/// export shows, because the callee recovers the extra register itself.
pub unsafe fn fn_8020b14c(opcode: u32, payload: u32, len: u32) {
    if opcode == 0x0C14 {
        platform::call2(0x8020_35B4, payload, len);
        return;
    }

    if (opcode as i32) < 0x0C14 {
        if opcode == 0x0C05 {
            platform::call1(EVENT_80205350, payload);
            return;
        }
        if (opcode as i32) < 0x0C05 {
            if opcode == 0x080C {
                fn_80200cd8(payload as usize);
                return;
            }
            if (opcode as i32) < 0x080C {
                if opcode == 0x0402 {
                    fn_802057e8(0);
                    return;
                }
            } else if opcode == 0x0C03 {
                fn_80202cb8();
                return;
            }
        } else {
            if opcode == 0x0C11 {
                fn_80203d98(payload as usize);
                return;
            }
            if (opcode as i32) < 0x0C11 {
                if opcode == 0x0C0D {
                    fn_80203d1c(payload as usize);
                    return;
                }
            } else if (opcode as i32) < 0x0C13 {
                fn_80203df4(payload as usize);
                return;
            }
        }
    } else {
        if opcode == 0x1009 {
            platform::call2(0x8020_3680, payload, len);
            return;
        }
        if (opcode as i32) < 0x1009 {
            if opcode == 0x1003 {
                platform::call2(0x8020_3000, payload, len);
                return;
            }
            if (opcode as i32) < 0x1003 {
                if opcode == 0x1001 {
                    platform::call2(0x8020_2F44, payload, len);
                    return;
                }
            } else if opcode == 0x1005 {
                platform::call2(0x8020_2E7C, payload, len);
                return;
            }
        } else if opcode != 0x1404 {
            if (opcode as i32) < 0x1404 {
                if 0x1402 < opcode as i32 {
                    fn_80201bc0(payload);
                    return;
                }
            } else if (opcode as i32) < 0x1406 {
                fn_80201aa4(payload);
                return;
            }
        }
    }

    if opcode & 0xFC00 == 0xFC00 {
        platform::call3(0x8020_38C8, payload, opcode, 1);
    }
}

/// Handles a command-complete event: matches it against the queued command.
///
/// Records the event's completion count in [`HCI_DRAIN_COUNT`], then - unless
/// the opcode is the reset family (`0x0C03`, `0x0C35`, `0`) - pops the head of
/// the outgoing queue. A `0xFC4C` event whose queued command has a different
/// opcode is pushed back untouched; otherwise the queued command is freed. The
/// retry timer is armed when the queue is empty and cancelled when work
/// remains, after which the opcode is dispatched through [`fn_8020b14c`] with
/// the event's parameter area.
///
/// # Original
/// - Ghidra: `FUN_8020B2A4` at `0x8020B2A4` (280 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8020b2a4_FUN_8020b2a4.c`
///
/// # Arguments
/// - `event`: start of the event packet; `+0` is the completion count, `+1..+2`
///   the opcode little-endian, `+3..` the return parameters.
/// - `len`: event byte count (the export types it `short`).
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Pops from and frees into the HCI queue, arms/cancels the retry timer and
/// dispatches the opcode.
///
/// # Safety
/// `event` must be readable for `len` bytes and point at a large enough packet
/// for the dispatcher's handler.
///
/// # Confidence
/// medium - every queue/timer call and the payload arithmetic are literal; the
/// `0xFC4C` special case is copied verbatim without a proven reason, and the
/// queue-empty test is `// observed:` from `801f7a90_FUN_801f7a90.c`.
pub unsafe fn fn_8020b2a4(event: u32, len: u32) {
    let base = event as usize;

    platform::write_u16(HCI_DRAIN_COUNT, platform::read_u8(base) as u16);

    let opcode = platform::read_u8(base + 1) as u32
        | (platform::read_u8(base + 2) as u32) << 8;

    if opcode != 0x0C03 && opcode != 0x0C35 && opcode != 0 {
        let queued = platform::call1(QUEUE_POP, HCI_QUEUE_OUT as u32) as usize;
        if queued != 0 {
            let queued_opcode = platform::read_u8(queued + 8) as u32
                | (platform::read_u8(queued + 9) as u32) << 8;

            if opcode == 0xFC4C && queued_opcode != 0xFC4C {
                platform::call2(QUEUE_PUSH_HEAD, HCI_QUEUE_OUT as u32, queued as u32);
                return;
            }

            platform::call1(HEAP_FREE, queued as u32);
        }

        if platform::call1(QUEUE_IS_EMPTY, HCI_QUEUE_OUT as u32) == 0 {
            platform::call3(TIMER_ARM, HCI_RETRY_TIMER as u32, 0x3C, 8);
        } else {
            platform::call1(TIMER_CANCEL, HCI_RETRY_TIMER as u32);
        }
    }

    fn_8020b14c(opcode, event + 3, len.wrapping_sub(3));
    fn_8020ac78(0);
}

/// Handles a command-status event.
///
/// The twin of [`fn_8020b2a4`] for events that carry a status byte and a
/// variable-length parameter area. The queued command found in the outgoing
/// queue contributes its payload pointer: the buffer's data offset (`u16` at
/// `+4`) plus ten bytes. When the queued opcode does not match the event the
/// routine logs `"Event mismatch opcode X"` and passes a null payload. The
/// dispatch then goes through [`fn_8020b3bc`] with the event's status byte.
///
/// # Original
/// - Ghidra: `FUN_8020B5BC` at `0x8020B5BC` (296 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8020b5bc_FUN_8020b5bc.c`
///
/// # Arguments
/// - `packet`: start of the event packet; `+0` status, `+1` completion count,
///   `+2..+3` opcode little-endian.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Pops and frees one HCI buffer, arms/cancels the retry timer and dispatches.
///
/// # Safety
/// `packet` must be readable for four bytes.
///
/// # Confidence
/// medium - the routine is printed with no parameter list because it opens with
/// the `0x802DCD74` register-save prologue; the incoming `r3` is recovered as
/// the packet pointer (the callee never touches `r3`), and every use of it is a
/// byte load, which confirms the recovery.
pub unsafe fn fn_8020b5bc(packet: u32) {
    let base = packet as usize;

    let status = platform::read_u8(base) as u32;
    platform::write_u16(HCI_DRAIN_COUNT, platform::read_u8(base + 1) as u16);

    let opcode = platform::read_u8(base + 2) as u32
        | (platform::read_u8(base + 3) as u32) << 8;

    let mut queued = 0usize;
    let mut payload = 0u32;

    if opcode != 0x0C03 && opcode != 0x0C35 && opcode != 0 {
        queued = platform::call1(QUEUE_POP, HCI_QUEUE_OUT as u32) as usize;
        if queued != 0 {
            // observed: iVar4 = buffer + *(u16 *)(buffer + 4); payload = iVar4 + 10
            let entry = queued + platform::read_u16(queued + 4) as usize;
            payload = (entry + 10) as u32;

            let queued_opcode = platform::read_u8(entry + 8) as u32
                | (platform::read_u8(entry + 9) as u32) << 8;
            if queued_opcode != opcode {
                payload = 0;
                platform::call3(
                    LOG_3,
                    0x0007_0001,
                    MSG_HCI_EVENT_MISMATCH as u32,
                    opcode,
                );
            }
        }

        if platform::call1(QUEUE_IS_EMPTY, HCI_QUEUE_OUT as u32) == 0 {
            platform::call3(TIMER_ARM, HCI_RETRY_TIMER as u32, 0x3C, 8);
        } else {
            platform::call1(TIMER_CANCEL, HCI_RETRY_TIMER as u32);
        }
    }

    fn_8020b3bc(opcode, status, payload);

    if queued != 0 {
        platform::call1(HEAP_FREE, queued as u32);
    }
    fn_8020ac78(0);
}

/// Dispatches a command-complete payload by opcode.
///
/// Link-control opcodes `0x0801` and `0x0803..0x0806` go to a single shared
/// handler. With a non-zero status the remaining branches are skipped except
/// for that link-control case. Otherwise the routine handles the remote-name
/// pair (`0x0419`, which calls two helpers), disconnects (`0x0401`),
/// role-switch (`0x080B`), a `0x0405` address hand-over, the `0x0428`
/// connection setup / unknown-channel pair, and finally the `0xFC00` vendor
/// range.
///
/// # Original
/// - Ghidra: `FUN_8020B3BC` at `0x8020B3BC` (512 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8020b3bc_FUN_8020b3bc.c`
///
/// # Arguments
/// - `opcode`: HCI opcode that completed.
/// - `status`: event status byte; `0` means success.
/// - `payload`: address of the return parameters (`0` when the queued command
///   did not match).
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Calls the per-opcode handlers; may queue further HCI commands.
///
/// # Safety
/// `payload` must be readable for the parameter count of the selected opcode;
/// the `0x0428` path hands an uninitialised `0x18`-byte stack block to the
/// connection dispatcher, exactly as the original does.
///
/// # Confidence
/// medium - every comparison and all call shapes are literal; the `0x0801`
/// family is `// inferred:` to be the page/connection command set, and the
/// meanings of `0x0405`/`0x0428` stay `// unknown:`.
pub unsafe fn fn_8020b3bc(opcode: u32, status: u32, payload: u32) {
    // observed: the export writes this as a nested test that excludes 0x0802
    // and accepts 0x0801 plus 0x0803..=0x0806.
    if opcode != 0x0802 && opcode > 0x0800 && opcode < 0x0807 {
        platform::call1(EVENT_802065EC, status);
        return;
    }

    if status == 0 {
        return;
    }

    if opcode == 0x0419 {
        platform::call4(EVENT_80205A3C, 0, 0, 0, status);
        platform::call3(EVENT_80208A98, 0, 0, status);
    } else if (opcode as i32) < 0x0419 {
        if opcode == 0x0401 {
            fn_802057e8(status as i32);
            return;
        }
        if (opcode as i32) < 0x0401 {
            if opcode == 0x000D {
                platform::call3(EVENT_80201754, status, 0, 0);
                return;
            }
        } else if opcode == 0x0405 {
            if payload == 0 {
                return;
            }

            // observed: local_28..local_23 <- payload[6] .. payload[1]
            let mut address = crate::platform::GuestLocal::new( [0u8; 6]);
            let mut index = 0usize;
            while index < 6 {
                address[index] = platform::read_u8(payload as usize + 6 - index);
                index += 1;
            }

            platform::call4(
                EVENT_8020933C,
                address.as_mut_ptr() as u32,
                0xFFFF,
                status,
                0,
            );
            platform::call3(
                EVENT_80214870,
                status,
                0xFFFF,
                address.as_mut_ptr() as u32,
            );
            return;
        }
    } else {
        if opcode == 0x080B {
            platform::call3(EVENT_80201320, status, 0, 0xFF);
            platform::call0(EVENT_8021571C);
            return;
        }

        if opcode < 0x080B && opcode == 0x0428 {
            if payload == 0 {
                return;
            }

            let handle = platform::read_u8(payload as usize + 1) as u32
                | (platform::read_u8(payload as usize + 2) as u32) << 8;

            if platform::call1(EVENT_802075A4, handle) != 0 {
                platform::call6(EVENT_802074A0, status, handle, 0, 0, 0, 0);
                return;
            }

            // observed: the export passes an unwritten 0x18-byte stack block.
            let mut config = crate::platform::GuestLocal::new( [0u8; 24]);
            platform::call4(
                EVENT_80206E50,
                status,
                0,
                handle,
                config.as_mut_ptr() as u32,
            );
            return;
        }
    }

    if opcode & 0xFC00 == 0xFC00 {
        platform::call3(0x8020_38C8, payload, opcode, 1);
    }
}

/// Times out the queued HCI command.
///
/// Sets the drain count to `1`, pops the head command (logging
/// `"Cmd timeout: no cmd in queue"` and returning when the queue is empty),
/// re-arms the retry timer if work remains, logs the timed-out opcode, and
/// redispatches it with status `0x1F`. Commands that carry a payload
/// (`0x0419`, `0x0401`, `0x0D`, `0x0405` and the `0x0801`/`0x0803..0x0806`
/// family) are redispatched through [`fn_8020b3bc`]; everything else is
/// redispatched through [`fn_8020b14c`] with a one-byte `0x1F` buffer, because
/// those handlers only read the status.
///
/// # Original
/// - Ghidra: `FUN_8020B6E4` at `0x8020B6E4` (344 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8020b6e4_FUN_8020b6e4.c`
///
/// # Arguments
/// None.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Pops and frees one HCI buffer, re-arms the retry timer, logs, and calls the
/// device-ready hook `0x80203FE8` with `2` before draining the queue.
///
/// # Safety
/// The queued buffer, if present, must contain the `+4` data offset and the
/// `+8` opcode fields the export reads.
///
/// # Confidence
/// medium - the pop, the log arguments, the redispatch split and the
/// `0x80203FE8(2)` call are literal; the two "payload" opcode sets are read
/// straight out of the decompiled branch tree.
pub unsafe fn fn_8020b6e4() {
    platform::write_u16(HCI_DRAIN_COUNT, 1);

    let queued = platform::call1(QUEUE_POP, HCI_QUEUE_OUT as u32) as usize;
    if queued == 0 {
        platform::call2(LOG_2, 0x0007_0001, MSG_HCI_NO_CMD as u32);
        return;
    }

    if platform::call1(QUEUE_IS_EMPTY, HCI_QUEUE_OUT as u32) == 0 {
        platform::call3(TIMER_ARM, HCI_RETRY_TIMER as u32, 0x3C, 8);
    }

    let entry = queued + platform::read_u16(queued + 4) as usize;
    let opcode = platform::read_u8(entry + 8) as u32
        | (platform::read_u8(entry + 9) as u32) << 8;

    platform::call3(LOG_2, 0x0007_0001, MSG_HCI_CMD_TIMEOUT as u32, opcode);

    let carries_payload = opcode == 0x0419
        || opcode == 0x0401
        || opcode == 0x000D
        || opcode == 0x0405
        || (opcode > 0x0800 && opcode < 0x0807 && opcode != 0x0802);

    if carries_payload {
        fn_8020b3bc(opcode, 0x1F, (entry + 10) as u32);
    } else {
        let mut status = crate::platform::GuestLocal::new( [0x1Fu8; 1]);
        fn_8020b14c(opcode, status.as_mut_ptr() as u32, 1);
    }

    platform::call1(HEAP_FREE, queued as u32);
    platform::call1(EVENT_80203FE8, 2);
    fn_8020ac78(0);
}

/// Splits a link-key notification into its address, key and type.
///
/// The payload holds the six-byte address at `+0..+5`, the sixteen key bytes at
/// `+6..+0x15` and the key type at `+0x16`, all stored most-significant byte
/// first. The routine reverses both into a 24-byte stack block (address at
/// `+0`, key at `+8`, with `+6`/`+7` left untouched as in the original) and
/// forwards `(address, key, type)` to `0x802099B4`.
///
/// # Original
/// - Ghidra: `FUN_8020B83C` at `0x8020B83C` (224 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8020b83c_FUN_8020b83c.c`
///
/// # Arguments
/// - `payload`: address of the 0x17-byte notification.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes a 24-byte stack block and stores the key in the device table.
///
/// # Safety
/// `payload` must be readable for `0x17` bytes.
///
/// # Confidence
/// medium - the reversal and the call are literal; the two untouched bytes and
/// the roles of address/key/type are `// inferred:` from
/// `802099b4_FUN_802099b4.c`, whose trace strings name the notification.
pub unsafe fn fn_8020b83c(payload: u32) {
    let base = payload as usize;

    let mut block = crate::platform::GuestLocal::new( [0u8; 24]);

    // observed: local_18..local_13 <- payload[5] .. payload[0]
    let mut index = 0usize;
    while index < 6 {
        block[index] = platform::read_u8(base + 5 - index);
        index += 1;
    }

    // observed: local_10..local_1 <- payload[0x15] .. payload[6]
    let mut key = 0usize;
    while key < 16 {
        block[8 + key] = platform::read_u8(base + 0x15 - key);
        key += 1;
    }

    platform::call3(
        EVENT_802099B4,
        block.as_mut_ptr() as u32,
        block.as_mut_ptr() as u32 + 8,
        platform::read_u8(base + 0x16) as u32,
    );
}

/// Builds and queues HCI `0x040C`, a six-byte-address command.
///
/// Allocates a class-2 buffer, writes the `9`-byte tag, opcode bytes `0x0C`/
/// `0x04`, parameter length `6` and the address in reverse byte order, then
/// queues the packet. The opcode is the only literal; the command mnemonic is
/// not proven.
///
/// # Original
/// - Ghidra: `FUN_8020D244` at `0x8020D244` (160 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8020d244_FUN_8020d244.c`
///
/// # Arguments
/// - `bd_addr`: address of the six-byte remote address.
///
/// # Returns
/// `true` when the packet was allocated and queued.
///
/// # Side effects
/// Allocates one HCI buffer and queues it through [`fn_8020ac78`].
///
/// # Safety
/// `bd_addr` must point to six readable bytes.
///
/// # Confidence
/// high - the header stores, the six reversed byte writes and the queue call
/// are literal.
pub unsafe fn fn_8020d244(bd_addr: u32) -> bool {
    let packet = platform::call1(HEAP_ALLOC, HCI_ALLOC_CLASS);
    if packet == 0 {
        return false;
    }

    let buf = packet as usize;
    platform::write_u16(buf + HCI_PKT_TAG, 9);
    platform::write_u16(buf + HCI_PKT_ZERO, 0);
    platform::write_u8(buf + HCI_OPCODE, 0x0C);
    platform::write_u8(buf + HCI_OPCODE + 1, 0x04);
    platform::write_u8(buf + HCI_PARAM_LEN, 6);

    let mut index = 0usize;
    while index < 6 {
        platform::write_u8(
            buf + HCI_PARAMS + index,
            platform::read_u8(bd_addr as usize + 5 - index),
        );
        index += 1;
    }

    fn_8020ac78(packet);
    true
}

/// Tears down every in-use HID-host record.
///
/// Returns `1` without touching anything when the pool's enable byte is already
/// clear. Otherwise it walks all sixteen `0x34`-byte records: for each in-use
/// record it sets the busy flag, cancels the record timer, and - when the peer
/// state is `1` - frees the record through `0x8021078C` and sets the busy flag
/// again. Then it clears the in-use byte, the state byte and both channel ids.
/// The pool is marked disabled at the end.
///
/// # Original
/// - Ghidra: `FUN_8020FE8C` at `0x8020FE8C` (228 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8020fe8c_FUN_8020fe8c.c`
///
/// # Arguments
/// None.
///
/// # Returns
/// `1` when the pool was already disabled, `0` after a teardown.
///
/// # Side effects
/// Cancels up to sixteen timers, clears the records and deregisters the L2CAP
/// PSM pair through `0x80212648`.
///
/// # Safety
/// No pointer arguments; fixed BSS only.
///
/// # Confidence
/// high - the loop, the `+0x0A` peer-state test, the timer cancel, both channel
/// id clears and the deregistration call are literal. The export's extra
/// `index < 0x11` guard is unreachable because the loop stops at `0x10`.
pub unsafe fn fn_8020fe8c() -> u32 {
    if platform::read_u8(BTM_POOL_ENABLED) == 0 {
        return 1;
    }

    let mut index = 0u32;
    while index < 0x10 {
        let record = BTM_POOL + index as usize * HID_REC_STRIDE;

        if platform::read_u8(record + HID_REC_IN_USE) != 0 {
            platform::write_u8(record + HID_REC_FLAG, 1);
            platform::call1(TIMER_CANCEL, (record + HID_REC_TIMER) as u32);

            if platform::read_u8(record + HID_REC_PEER_STATE) == 1 {
                platform::write_u8(record + HID_REC_FLAG, 1);
                platform::call1(HID_RELEASE_8021078C, index);
            }

            platform::write_u8(record + HID_REC_IN_USE, 0);
            platform::write_u8(record + HID_REC_STATE, 0);
            platform::write_u16(record + HID_REC_INTR_CID, 0);
            platform::write_u16(record + HID_REC_CTRL_CID, 0);
        }

        index += 1;
    }

    platform::call0(L2CAP_DEREGISTER);
    platform::write_u8(BTM_POOL_ENABLED, 0);

    0
}

// ===========================================================================
// Wave 82: L2CAP API entry points, control blocks and connection timers.
//
// This pass works two contiguous holes in the `0x80210000` bucket:
//
// - `0x80212C64..0x8021323C`, the four L2CAP "send this primitive" calls plus
//   the idle-timeout setter and an empty callback slot,
// - `0x80214C18..0x80216BC4`, the connection-block layer: channel allocation
//   and lookup by `BD_ADDR`, the reassembly/segment-complete path, the window
//   accounting and the initialisers for the four connection blocks and the ten
//   CCB records,
// plus four further helpers in the same bucket (`0x80217F88..0x80219594`,
// `0x8021D74C`, `0x8021E628`, `0x8021F08C`).
//
// The block layout was already documented by waves 5, 6 and 68 in the constant
// table above; this section only adds the offsets it introduces itself.
// ===========================================================================

/// Start of the L2CAP context block (`0x803D4C40`, `0x7E8` bytes).
///
/// `// observed:` [`fn_802158a8`] clears this range with `FUN_800046B4`, and the
/// first four bytes are the trace/config word plus the counters below.
const L2CAP_CONTEXT: usize = 0x803D_4C40;

/// Size cleared by [`fn_802158a8`] (`// observed:` `memset(..., 0, 0x7e8)`).
const L2CAP_CONTEXT_SIZE: u32 = 0x7E8;

/// `u8` configuration byte at `0x803D4C41`, returned by [`fn_80216bc4`].
///
/// `// unknown:` reset by [`fn_802158a8`] and only ever read back by the getter;
/// no export in this bucket writes it to a non-zero value.
const L2CAP_CONFIG_803D4C41: usize = 0x803D_4C41;

/// `u16` "pending load" at `0x803D4C42`, written together with [`G_L2CAP_LOAD`]
/// by [`fn_8021544c`].
const L2CAP_LOAD_PENDING: usize = 0x803D_4C42;

/// `u16` default L2CAP timeout seed at `0x803D53FA` (initialised to `2`).
const L2CAP_TIMEOUT_DEFAULT: usize = 0x803D_53FA;

/// Connection block that owns the packet currently being reassembled
/// (`0x803D53FC`); its `+0x50` field is the retained packet.
const L2CAP_REASSEMBLY: usize = 0x803D_53FC;

/// Base of the ten connection control blocks (CCBs) at `0x803D4DB8`.
///
/// `// observed:` [`fn_80217f88`] indexes `0x7C`-byte records by `cid - 0x40`;
/// [`fn_802158a8`] links the ten records and puts them on the free list.
const L2CAP_CCB_TABLE: usize = 0x803D_4DB8;

/// Byte distance between two CCB records.
const L2CAP_CCB_STRIDE: usize = 0x7C;

/// Lowest CCB local channel id (`0x40`); the index is `cid - 0x40`.
const L2CAP_CCB_BASE_CID: u32 = 0x40;

/// Free-list link at `+8` of a CCB record.
const L2CAP_CCB_NEXT: usize = 0x08;

/// Owning connection block at `+0x10` of a CCB record.
const L2CAP_CCB_OWNER: usize = 0x10;

/// Number of PSM slots (eight `0x2C`-byte records at [`L2CAP_PSM_TABLE`]).
const L2CAP_PSM_SLOT_COUNT: u32 = 8;

/// `u16` at `+0x36` of a connection block: transmit window still available.
///
/// `// observed:` [`fn_80214dfc`] decrements it per queued packet and
/// `0x80215368` restores it; the neighbouring `+0x34` is the ceiling.
const L2CAP_CH_WINDOW: usize = 0x36;

/// Flag byte at `+0x40`, set when the window was clipped for a packet.
const L2CAP_CH_WINDOW_FLAG: usize = 0x40;

/// `+0x20` of a connection block: self pointer written by [`fn_802168d8`].
const L2CAP_CONN_SELF: usize = 0x20;

/// `+0x30` byte of a connection block written by [`fn_8021569c`].
///
/// `// unknown:` the only writer stores a caller-supplied byte there before
/// closing the channels in state `2`; no other export reads it.
const L2CAP_CONN_MODE: usize = 0x30;

/// `0x80218554`: closes one L2CAP channel block (role inferred from its callers).
const L2CAP_CLOSE_CHANNEL: usize = 0x8021_8554;

/// `0x80219A54`: disconnect one RFCOMM DLC with a reason code.
const RF_DLC_DISCONNECT: usize = 0x8021_9A54;

/// `0x802167AC`: connection hold/continue poll (skipped by wave 79, called by
