const L2CAP_HOLD_POLL: usize = 0x8021_67AC;

/// `0x803D5428`: RFCOMM context block cleared by [`fn_8021879c`].
const RFCOMM_CONTEXT: usize = 0x803D_5428;

/// Size of the RFCOMM context block (`// observed:` `memset(..., 0, 0x418)`).
