    if all == 0 {
        let ccb = fn_80217f88(0, cid);
        if ccb == 0 {
            if platform::read_u8(G_L2CAP_TRACE_LEVEL) > 1 {
                platform::call3(LOG_2, 0x80001, S_NO_CCB_SET_IDLE, cid);
            }
            return 0;
        }

        let owner = platform::read_u32(ccb + L2CAP_CCB_OWNER) as usize;
        if owner == 0
            || platform::read_u8(owner + L2CAP_CH_IN_USE) == 0
            || platform::read_u32(owner + L2CAP_CH_STATE) != 4
        {
            return 0;
        }

        platform::write_u16(owner + L2CAP_CONN_TIMEOUT, timeout);
        value = platform::read_u16(L2CAP_TIMEOUT_DEFAULT);
    }

    platform::write_u16(L2CAP_TIMEOUT_DEFAULT, value);
    1
