/// Closes the in-use L2CAP channel blocks whose state is `2`.
///
/// # Safety
/// The channel table must be readable for four `0x5C`-byte records.
unsafe fn close_channels_in_state_two() {
    let mut channel = L2CAP_CHANNEL_TABLE;
    let mut index = 0u32;
    while index < L2CAP_CHANNEL_COUNT {
        if platform::read_u8(channel + L2CAP_CH_IN_USE) != 0
            && platform::read_u32(channel + L2CAP_CH_STATE) == 2
        {
            platform::call1(L2CAP_CLOSE_CHANNEL, channel as u32);
        }
        channel += L2CAP_CHANNEL_STRIDE;
        index += 1;
    }
}

