/// Attaches a `(base, size)` memory range as one of the eight IPC heaps.
///
/// The base must be 32-byte aligned and a free slot must exist. The slot is
/// filled with the base, the size and the free-list head, and the whole range
/// becomes a single free block (`0xBABE0000`) whose payload is `size - 0x10`
/// bytes.
///
/// # Original
/// - Ghidra: `FUN_80225d80` at `0x80225D80` (304 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80225d80_FUN_80225d80.c`
///
/// # Arguments
/// - `base`: 32-byte aligned start of the range.
/// - `size`: range length in bytes (must cover the `0x10`-byte header).
///
/// # Returns
/// The heap index `0..7`, `-4` when `base` is not 32-byte aligned, `-5` when
/// all eight slots are taken.
///
/// # Side effects
/// Writes one heap record and the first block header; runs inside the OS debug
/// critical section.
///
/// # Safety
/// `base` must be a writable range of `size` bytes in MEM1/MEM2.
///
/// # Confidence
/// high - the alignment test, the slot scan, the three record words and the
/// four header words are literal.
pub unsafe fn fn_80225d80(base: u32, size: u32) -> i32 {
    // observed: `FUN_801b1140();` with no visible argument or result.
    platform::call0(OS_DEBUG_ENTER);

    let index: i32;
    if base & 0x1F == 0 {
        let mut slot = 0u32;
        while slot < IPC_HEAP_SLOTS {
            if platform::read_u32(IPC_HEAP_TABLE + slot as usize * IPC_HEAP_STRIDE) == 0 {
                break;
            }
            slot += 1;
        }
        if slot == IPC_HEAP_SLOTS {
            // observed: the export's unrolled scan ends with `iVar2 = 8`.
            index = -5;
        } else {
            index = slot as i32;
            let record = IPC_HEAP_TABLE + slot as usize * IPC_HEAP_STRIDE;
            platform::write_u32(record, base);
            platform::write_u32(record + IPC_HEAP_SIZE, size);
            platform::write_u32(record + IPC_HEAP_FREE, base);

            let block = base as usize;
            platform::write_u32(block, IPC_BLOCK_FREE);
            platform::write_u32(block + 4, size.wrapping_sub(IPC_BLOCK_HEADER as u32));
            platform::write_u32(block + 8, 0);
            platform::write_u32(block + 12, 0);
        }
    } else {
        index = -4;
    }

    platform::call0(OS_DEBUG_RESTORE);
    index
}

/// Allocates an aligned block from one of the eight IPC heaps.
///
/// The first-fit walk prefers an exact size match and otherwise the smallest
/// block that fits including the padding needed to align the payload. A block
/// large enough to leave at least one byte is split; the alignment pad is
/// marked with its own `0xBABE0002` header that points back at the block so
/// [`fn_802260c0`] can find it.
///
/// # Original
/// - Ghidra: `FUN_80225eb0` at `0x80225EB0` (508 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80225eb0_FUN_80225eb0.c`
///
/// # Arguments
/// - `pool`: heap index `0..7`.
/// - `size`: requested payload size, rounded up to 32 bytes.
/// - `align`: power-of-two alignment, at least `0x20`.
///
/// # Returns
/// The payload address, or `0` when the arguments are invalid, the heap is not
/// attached or no block fits.
///
/// # Side effects
/// Splits free blocks, rewrites the free list and the block magics.
///
/// # Safety
/// The heap table and the selected heap's free list must be in the state left
/// by [`fn_80225d80`] and [`fn_802260c0`].
///
/// # Confidence
/// medium - every store is literal, but the exported loop keeps a shadow copy
/// of the selected block in its condition (`puVar3 = puVar2`) and the split
/// path leaves the new block's `prev` word untouched; both are reproduced as
/// the export prints them and flagged here.
pub unsafe fn fn_80225eb0(pool: u32, size: u32, align: u32) -> usize {
    let mut result: usize = 0;

    platform::call0(OS_DEBUG_ENTER);

    if size != 0 && align != 0 && (align & align.wrapping_sub(1)) == 0 {
        let align = if align < 0x20 { 0x20 } else { align };
        let wanted = size.wrapping_add(0x1F) & !0x1F;

        if pool < IPC_HEAP_SLOTS
            && platform::read_u32(IPC_HEAP_TABLE + pool as usize * IPC_HEAP_STRIDE) != 0
        {
            let mut best: usize = 0;
            let mut node = platform::read_u32(
                IPC_HEAP_TABLE + pool as usize * IPC_HEAP_STRIDE + IPC_HEAP_FREE,
            ) as usize;

            while node != 0 {
                let node_size = platform::read_u32(node + 4);
                // observed: padding to align `node + 0x10` to `align`.
                let pad = (align - 1)
                    & (align
                        - ((node as u32 + IPC_BLOCK_HEADER as u32) & (align - 1)));

                if node_size == wanted && pad == 0 {
                    best = node;
                    break;
                }
                if wanted + pad <= node_size
                    && (best == 0 || node_size < platform::read_u32(best + 4))
                {
                    best = node;
                }

                node = platform::read_u32(node + 12) as usize;
            }

            if best != 0 {
                let pad = (align - 1)
                    & (align
                        - ((best as u32 + IPC_BLOCK_HEADER as u32) & (align - 1)));

                if (wanted + pad + IPC_BLOCK_HEADER as u32)
                    < platform::read_u32(best + 4)
                {
                    let offset = (pad + wanted) as usize;
                    let new_block = best + offset + IPC_BLOCK_HEADER;
                    let next = platform::read_u32(best + 12) as usize;

                    platform::write_u32(new_block, IPC_BLOCK_FREE);
                    platform::write_u32(
                        new_block + 4,
                        platform::read_u32(best + 4)
                            .wrapping_sub(wanted)
                            .wrapping_sub(pad)
                            .wrapping_sub(IPC_BLOCK_HEADER as u32),
                    );
                    // observed: the new block's `next` is written, its `prev`
                    // is not; the following two stores link it into the list.
                    platform::write_u32(new_block + 12, next as u32);
                    if next != 0 {
                        platform::write_u32(next + 8, new_block as u32);
                    }
                    platform::write_u32(best + 12, new_block as u32);
                    platform::write_u32(best + 4, wanted + pad);
                }

                platform::write_u32(best, IPC_BLOCK_USED);

                let prev = platform::read_u32(best + 8) as usize;
                let next = platform::read_u32(best + 12) as usize;
                if prev == 0 {
                    platform::write_u32(
                        IPC_HEAP_TABLE + pool as usize * IPC_HEAP_STRIDE + IPC_HEAP_FREE,
                        next as u32,
                    );
                } else {
                    platform::write_u32(prev + 12, next as u32);
                }
                if next != 0 {
                    platform::write_u32(next + 8, prev as u32);
                }
                platform::write_u32(best + 12, 0);
                platform::write_u32(best + 8, 0);

                let pad_base = best + pad as usize;
                result = pad_base + IPC_BLOCK_HEADER;
                if pad != 0 {
                    platform::write_u32(pad_base, IPC_BLOCK_PAD);
                    // observed: `puVar2[2] = puVar3` - the pad points back at
                    // the block it belongs to.
                    platform::write_u32(pad_base + 8, best as u32);
                }
            }
        }
    }

    platform::call0(OS_DEBUG_RESTORE);
    result
}

/// Returns a payload to the IPC heap it came from.
///
/// The payload may belong to a plain block or to an alignment pad; a pad header
/// (`0xBABE0002`) redirects to the real block through its `+8` word. The block
/// must still carry the allocated magic. It is inserted into the address-sorted
/// free list, then coalesced with the following and the preceding block when
/// they are physically adjacent.
///
/// # Original
/// - Ghidra: `FUN_802260c0` at `0x802260C0` (484 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802260c0_FUN_802260c0.c`
///
/// # Arguments
/// - `pool`: heap index `0..7`.
/// - `payload`: address returned by [`fn_80225eb0`].
///
/// # Returns
/// `0` on success, `-4` for a null pointer, an unknown heap, a payload outside
/// the heap range or a block that is not allocated.
///
/// # Side effects
/// Rewrites the free list, both magics and the merged sizes.
///
/// # Safety
/// `payload` must be a live allocation from the same IPC heap implementation.
///
/// # Confidence
/// high - the pad redirect, the sorted insertion and the two merge tests are
/// literal.
pub unsafe fn fn_802260c0(pool: u32, payload: u32) -> u32 {
    let mut status: u32 = 0xFFFF_FFFC;

    platform::call0(OS_DEBUG_ENTER);

    if payload != 0 && pool < IPC_HEAP_SLOTS {
        let record = IPC_HEAP_TABLE + pool as usize * IPC_HEAP_STRIDE;
        let heap = platform::read_u32(record) as usize;
        let end = heap + platform::read_u32(record + IPC_HEAP_SIZE) as usize;

        if heap != 0
            && heap + IPC_BLOCK_HEADER <= payload as usize
            && payload as usize <= end
        {
            let mut block = payload as usize - IPC_BLOCK_HEADER;
            if platform::read_u32(block) == IPC_BLOCK_PAD {
                block = platform::read_u32(block + 8) as usize;
            }

            if platform::read_u32(block) == IPC_BLOCK_USED {
                platform::write_u32(block, IPC_BLOCK_FREE);

                // observed: walk the address-sorted free list and remember the
                // node after which the block belongs.
                let mut previous: usize;
                let mut cursor = platform::read_u32(record + IPC_HEAP_FREE) as usize;
                loop {
                    previous = cursor;
                    if previous == 0 {
                        break;
                    }
                    cursor = platform::read_u32(previous + 12) as usize;
                    if cursor == 0 || cursor > block {
                        break;
                    }
                }

                if previous == 0 || block <= previous {
                    platform::write_u32(block + 12, platform::read_u32(record + IPC_HEAP_FREE));
                    platform::write_u32(record + IPC_HEAP_FREE, block as u32);
                    platform::write_u32(block + 8, 0);
                    let next = platform::read_u32(block + 12) as usize;
                    if next != 0 {
                        platform::write_u32(next + 8, block as u32);
                    }
                } else {
                    platform::write_u32(block + 8, previous as u32);
                    let next = platform::read_u32(previous + 12) as usize;
                    platform::write_u32(block + 12, next as u32);
                    platform::write_u32(previous + 12, block as u32);
                    if next != 0 {
                        platform::write_u32(next + 8, block as u32);
                    }
                }

                // observed: merge with the following block.
                let next = platform::read_u32(block + 12) as usize;
                if next != 0
                    && next
                        == block
                            + platform::read_u32(block + 4) as usize
                            + IPC_BLOCK_HEADER
                {
                    let after = platform::read_u32(next + 12) as usize;
                    platform::write_u32(block + 12, after as u32);
                    if after != 0 {
                        platform::write_u32(after + 8, block as u32);
                    }
                    platform::write_u32(
                        block + 4,
                        platform::read_u32(next + 4)
                            .wrapping_add(platform::read_u32(block + 4))
                            .wrapping_add(IPC_BLOCK_HEADER as u32),
                    );
                }

                // observed: merge with the preceding block.
                let prev = platform::read_u32(block + 8) as usize;
                if prev != 0 {
                    let after_prev = platform::read_u32(prev + 12) as usize;
                    if after_prev
                        == prev
                            + platform::read_u32(prev + 4) as usize
                            + IPC_BLOCK_HEADER
                    {
                        let after = platform::read_u32(after_prev + 12) as usize;
                        platform::write_u32(prev + 12, after as u32);
                        if after != 0 {
                            platform::write_u32(after + 8, prev as u32);
                        }
                        platform::write_u32(
                            prev + 4,
                            platform::read_u32(after_prev + 4)
                                .wrapping_add(platform::read_u32(prev + 4))
                                .wrapping_add(IPC_BLOCK_HEADER as u32),
                        );
                    }
                }

                status = 0;
            }
        }
    }

    platform::call0(OS_DEBUG_RESTORE);
    status
}

/// Clears both 32-slot IPC tables and the two counters that track them.
///
/// The request table is zeroed, the context table is filled with `0xFFFFFFFF`
/// and the in-flight / outstanding-completion counters are reset.
///
/// # Original
/// - Ghidra: `FUN_802262b0` at `0x802262B0` (184 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802262b0_FUN_802262b0.c`
///
/// # Arguments
/// None.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes [`SDA_IPC_INFLIGHT`], [`SDA_IPC_COMPLETIONS`] and all 64 table words.
///
/// # Safety
/// None; both tables are private to this layer.
///
/// # Confidence
/// high - the two counters and the two sixteen-word clear loops are literal.
pub unsafe fn fn_802262b0() {
    platform::write_u32(SDA_IPC_INFLIGHT, 0);
    platform::write_u32(SDA_IPC_COMPLETIONS, 0);

    let mut i = 0usize;
    while i < IPC_TABLE_SLOTS as usize {
        platform::write_u32(IPC_REQUEST_TABLE + i * 4, 0);
        platform::write_u32(IPC_CONTEXT_TABLE + i * 4, 0xFFFF_FFFF);
        i += 1;
    }
}

/// Records one request and its context in the first free wait-table slot.
///
/// Both counters are incremented, then the slot scan looks for the pair
/// "request word zero" and "context word `0xFFFFFFFF`". A full table is
/// silently ignored.
///
/// # Original
/// - Ghidra: `FUN_80226370` at `0x80226370` (132 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80226370_FUN_80226370.c`
///
/// # Arguments
/// - `request`: block pointer stored in [`IPC_REQUEST_TABLE`].
/// - `context`: context word stored in [`IPC_CONTEXT_TABLE`].
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Increments [`SDA_IPC_INFLIGHT`] and [`SDA_IPC_COMPLETIONS`]; may write one
/// slot of each table.
///
/// # Safety
/// None; both tables are private to this layer.
///
/// # Confidence
/// high - both increments, the free-slot test and the two stores are literal.
pub unsafe fn fn_80226370(request: u32, context: u32) {
    let inflight = platform::read_u32(SDA_IPC_INFLIGHT);
    platform::write_u32(SDA_IPC_INFLIGHT, inflight.wrapping_add(1));
    let completions = platform::read_u32(SDA_IPC_COMPLETIONS);
    platform::write_u32(SDA_IPC_COMPLETIONS, completions.wrapping_add(1));

    let mut slot = 0usize;
    while slot < IPC_TABLE_SLOTS as usize {
        if platform::read_u32(IPC_REQUEST_TABLE + slot * 4) == 0
            && platform::read_u32(IPC_CONTEXT_TABLE + slot * 4) == 0xFFFF_FFFF
        {
            platform::write_u32(IPC_REQUEST_TABLE + slot * 4, request);
            platform::write_u32(IPC_CONTEXT_TABLE + slot * 4, context);
            return;
        }
        slot += 1;
    }
}

/// Brings up the second IPC arena.
///
/// On the first call the arena bounds are snapshotted from
/// [`fn_80224370`]/[`fn_80224360`]. The base is rounded up to 32 bytes and
/// recorded; the call then checks room for a `0x40`-byte header, initialises
/// the object at [`SDA_IPC_ARENA_OBJECT`], opens the IPC device through the
/// kind-1 string request, reserves `0x1540` bytes of arena and carves a heap of
/// that size for the `0x140`-byte completion blocks.
///
/// # Original
/// - Ghidra: `FUN_80226490` at `0x80226490` (296 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80226490_FUN_80226490.c`
///
/// # Arguments
/// None.
///
/// # Returns
/// `0` on success, `-22` (`0xFFFFFFEA`) when the arena is too small or the heap
/// cannot be created, or the negative status from the kind-1 request.
///
/// # Side effects
/// Writes five SDA1 words, advances the arena frontier, creates a heap and
/// submits one IPC request.
///
/// # Safety
/// Must run after the arena bootstrap of [`fn_802247d0`].
///
/// # Confidence
/// low - every store and call is literal, but `0x802E1938` is unnamed and the
/// kind-1 request is handed the raw arena base as its "string". The inferred
/// reading is that `0x802E1938` leaves the device name there; the export does
/// not prove it.
pub unsafe fn fn_80226490() -> i32 {
    if platform::read_u32(SDA_IPC_ARENA_ACTIVE) == 0 {
        platform::write_u32(SDA_IPC_ARENA_BASE, fn_80224370());
        platform::write_u32(SDA_IPC_ARENA_END, fn_80224360());
    }

    let mut base = (platform::read_u32(SDA_IPC_ARENA_BASE) + 0x1F) & !0x1F;
    platform::write_u32(SDA_IPC_ARENA_CURSOR, base);

    if platform::read_u32(SDA_IPC_ARENA_ACTIVE) == 0
        && platform::read_u32(SDA_IPC_ARENA_END) < base + 0x40
    {
        platform::call1(LOG_1, S_APP_ERROR_NOT_ENOUGH_ARENA);
        return -0x16;
    }

    // observed: `FUN_802e1938(uVar1, r13 - 0x5d08);`
    platform::call2(ARENA_CALL_802E1938, base, SDA_IPC_ARENA_OBJECT as u32);

    let status = fn_80224c70(base as usize, 0);
    platform::write_u32(SDA_IPC_RESOURCE, status as u32);
    if status < 0 {
        return status;
    }

    base = platform::read_u32(SDA_IPC_ARENA_CURSOR);
    if platform::read_u32(SDA_IPC_ARENA_ACTIVE) == 0
        && platform::read_u32(SDA_IPC_ARENA_END) < base + 0x1540
    {
        platform::call1(LOG_1, S_APP_ERROR_NOT_ENOUGH_ARENA);
        return -0x16;
    }

    if platform::read_u32(SDA_IPC_ARENA_ACTIVE) == 0 {
        fn_80224380(base + 0x1540);
        platform::write_u32(SDA_IPC_ARENA_ACTIVE, 1);
    }

    let heap = fn_80225d80(base, 0x1540);
    platform::write_u32(SDA_IPC_BLOCK_HEAP, heap as u32);
    if heap < 0 {
        return -0x16;
    }

    0
}

/// Shared completion callback for the `0x140`-byte request blocks.
///
/// A non-negative status copies the block's results into the pointers the
/// caller registered at `+0x10C..`. The mode word at `+0x108` selects the
/// layout:
///
/// - `1`: `0x1C` bytes of the block,
/// - `2`: the `u32` at `block + 0x40`,
/// - `3`: the `u16` at `+0x44` and the bytes at `+0x49`, `+0x46`, `+0x47`,
///   `+0x48`,
/// - `4`: the two `u32` values at `+0x40` and `+0x60`,
/// - `5`: the first eight bytes of the block.
///
/// # Original
/// - Ghidra: `FUN_802265c0` at `0x802265C0` (384 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802265c0_FUN_802265c0.c`
///
/// # Arguments
/// - `status`: completion status; only `0` triggers the copy-out.
/// - `block`: the `0x140`-byte completion block.
///
/// # Returns
/// The status, unchanged.
///
/// # Side effects
/// Copies into the caller's pointers, clears [`SDA_IPC_UNKNOWN_ABD8`], calls the
/// block's own callback at `+0x100` and frees the block.
///
/// # Safety
/// `block` must be a live completion block; the output pointers it holds must
/// be writable for the size the selected mode copies.
///
/// # Confidence
/// high - all five modes, the two extra fields and the callback/free tail are
/// literal.
pub unsafe fn fn_802265c0(status: i32, block: usize) -> i32 {
    let succeeded = status == 0;

    if status >= 0 {
        let mode = platform::read_i32(block + 0x108);
        if mode == 1 {
            if succeeded {
                let destination = platform::read_u32(block + 0x10C);
                platform::call3(MEMCPY, destination, block as u32, 0x1C);
            }
        } else if mode == 2 {
            if succeeded {
                let destination = platform::read_u32(block + 0x10C) as usize;
                // observed: `*(undefined4 *)((param_2 + 0x3f & 0xfffffffe0) + 0x40)`
                let source = (block + 0x3F) & !0x1F;
                platform::write_u32(destination, platform::read_u32(source + 0x40));
            }
        } else if mode == 3 {
            if succeeded {
                let source = (block + 0x5F) & !0x1F;
                let out0 = platform::read_u32(block + 0x10C) as usize;
                let out1 = platform::read_u32(block + 0x110) as usize;
                let out2 = platform::read_u32(block + 0x114) as usize;
                let out3 = platform::read_u32(block + 0x118) as usize;
                let out4 = platform::read_u32(block + 0x11C) as usize;
                let out5 = platform::read_u32(block + 0x120) as usize;
                platform::write_u32(out0, platform::read_u32(source));
                platform::write_u16(out1, platform::read_u16(source + 4));
                platform::write_u32(out2, platform::read_u8(source + 0x49) as u32);
                platform::write_u32(out3, platform::read_u8(source + 0x46) as u32);
                platform::write_u32(out4, platform::read_u8(source + 0x47) as u32);
                platform::write_u32(out5, platform::read_u8(source + 0x48) as u32);
            }
        } else if mode == 4 {
            if succeeded {
                let source = (block + 0x3F) & !0x1F;
                let out0 = platform::read_u32(block + 0x10C) as usize;
                let out1 = platform::read_u32(block + 0x110) as usize;
                platform::write_u32(out0, platform::read_u32(source + 0x40));
                platform::write_u32(out1, platform::read_u32(source + 0x60));
            }
        } else if mode == 5 && succeeded {
            let destination = platform::read_u32(block + 0x10C);
            platform::call3(MEMCPY, destination, block as u32, 8);
        }
    }

    platform::write_u32(SDA_IPC_UNKNOWN_ABD8, 0);

    let callback = platform::read_u32(block + 0x100);
    if callback != 0 {
        let completion = crate::platform::guest_fn!(callback as usize, fn(i32, u32));
        completion(status, platform::read_u32(block + 0x104));
    }

    // observed: `if (param_2 != 0) FUN_802260c0(...)`.
    if block != 0 {
        fn_802260c0(platform::read_u32(SDA_IPC_POOL), block as u32);
    }

    status
}

