const GAP_CONN_STATE: usize = 0x00;
const GAP_CONN_FLAGS: usize = 0x01;
const GAP_CONN_HANDLE: usize = 0x04;
const GAP_CONN_CID: usize = 0x06;
const GAP_CONN_ANY_ADDR: usize = 0x08;
