const GAP_CONN_QUEUE: usize = 0x14;
const GAP_CONN_CALLBACK: usize = 0x20;
const GAP_CONN_SPARE: usize = 0x24;

/// `0x803D4368`: GAP trace level byte.
const GAP_LOG_LEVEL: usize = 0x803D_4368;

/// GAP discovery table: two `0x10`-byte records at `0x803D4344`.
