const GAP_DISC_TABLE: usize = 0x803D_4344;
const GAP_DISC_STRIDE: usize = 0x10;
const GAP_DISC_CALLBACK: usize = 0x00;
const GAP_DISC_STATE: usize = 0x08;
const GAP_DISC_IN_USE: usize = 0x0B;

/// GAP remote-name lookup state block.
