const GAP_NAME_RECORD: usize = 0x803D_4370;
const GAP_NAME_RESULT: usize = 0x803D_4374;
const GAP_NAME_BDADDR: usize = 0x803D_4376;
const GAP_NAME_QUERY: usize = 0x803D_437C;
const GAP_NAME_CALLBACK: usize = 0x803D_436C;
const GAP_NAME_PENDING: usize = 0x803D_43BE;

/// `0x802E1BD0`: bounded string comparison used by [`fn_8020c800`].
const STRING_COMPARE_802E1BD0: usize = 0x802E_1BD0;

/// `0x8020D9EC`: extended eSCO link-parameter builder (seven arguments).
