const MSG_GAP_INQ_COMPLETE: u32 = 0x8034_9980;
const MSG_GAP_NAME_COMPLETE: u32 = 0x8034_9A18;
const MSG_GAP_FIND_NAME_OK: u32 = 0x8034_9AF8;
