    let mut cursor = GAP_CONN_TABLE;
    let mut index = 0u32;
    while index < GAP_CONN_COUNT {
        if platform::read_u8(cursor + GAP_CONN_STATE) != 0
            && platform::read_u16(cursor + GAP_CONN_CID) as u32 == cid
        {
            slot = cursor;
            break;
        }
        index += 1;
        cursor += GAP_CONN_STRIDE;
    }
    if slot == 0 {
        return;
    }

    let block = params as usize;
    if platform::read_u8(block + 2) == 0 || platform::read_u16(block + 4) > 0x69B {
        platform::write_u16(slot + GAP_CONN_RESULT, 0x069B);
    } else {
        platform::write_u16(slot + GAP_CONN_RESULT, platform::read_u16(block + 4));
    }

    platform::write_u8(block + 0x20, 0);
    platform::write_u8(block + 2, 0);
    platform::write_u16(block, 0);

