/// Starts the HID control channel for the record that owns `state` word.
///
/// If the record is idle the routine clears both channel ids, writes the
/// `0x100` MTU and the originate sub-state, asks L2CAP to connect PSM `0x11`
/// and stores the returned id. A failed originate is reported to the owner
/// callback as `(index, 1, 0x0E, 0)`. In every case the record's byte at
/// `+0x0C` is incremented and forwarded as event `2`.
///
/// # Original
/// - Ghidra: `FUN_80210BB8` at `0x80210BB8` (332 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80210bb8_FUN_80210bb8.c`
///
/// # Arguments
/// - `record`: address of a HID device record; its `+0x10` word starts with the
///   index byte.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes five record fields, may start an L2CAP connection, and always calls
/// [`HID_OWNER_CALLBACK`] with event `2`.
///
/// # Safety
/// `record` must point inside the sixteen-record pool and the owner callback
/// must be installed.
///
/// # Confidence
/// high - every store and both callback calls are literal; the `uVar2 / 0xa90`
/// index expression in the export is a compiler artifact of `index * 0x34`.
pub unsafe fn fn_80210bb8(record: usize) {
    // observed: `*(uint *)(param_1 + 0x10) & 0xff` - the state byte is the
    // record index the owner callback expects.
    let index = platform::read_u32(record + HID_REC_STATE) & 0xFF;

    if platform::read_u8(record + HID_REC_STATE) == 0 {
        platform::write_u16(record + HID_REC_CTRL_CID, 0);
        platform::write_u16(record + HID_REC_INTR_CID, 0);
        platform::write_u16(record + HID_REC_MTU, 0x100);
        platform::write_u8(record + HID_REC_SUBSTATE, 1);

        // observed: `FUN_802128a0(0x11, &DAT_803d4839 + iVar3)`.
        let cid = platform::call2(
            L2CAP_CONNECT_START_SDP,
            HID_PSM_CONTROL,
            (record + HID_REC_BDADDR) as u32,
        ) as u16;
        platform::write_u16(record + HID_REC_CTRL_CID, cid);

        if cid == 0 {
            if platform::read_u8(BTM_POOL_FLAG) > 1 {
                platform::call2(LOG_1, 0x001E_0001, S_HID_POOL_ORIGINATE_FAILED);
            }
            let owner = platform::read_u32(HID_OWNER_CALLBACK) as usize;
            platform::call4(owner, index, 1, 0x0E, 0);
        } else {
            platform::write_u8(record + HID_REC_STATE, 1);
        }
    }

    let bump = platform::read_u8(record + HID_REC_FLAG).wrapping_add(1);
    platform::write_u8(record + HID_REC_FLAG, bump);
    let owner = platform::read_u32(HID_OWNER_CALLBACK) as usize;
    platform::call4(
        owner,
        platform::read_u32(record + HID_REC_STATE) & 0xFF,
        2,
        bump as u32,
        0,
    );
}

/// Handles the security outcome of the HID interrupt channel.
///
/// On a successful control-channel security pass the record moves to state `2`
/// and the interrupt originate is issued on PSM `0x13`. A failed originate
/// tears the record down exactly like [`fn_80210830`] and reports
/// `(index, 1, 0x200, 0)`. A non-zero `status` on the control channel uses the
/// same teardown path without touching the state-2 transition.
///
/// # Original
/// - Ghidra: `FUN_80210D04` at `0x80210D04` (532 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80210d04_FUN_80210d04.c`
///
/// # Arguments
/// - `_tag`: first argument; never read.
/// - `record`: HID device record reported by the security manager (the
///   `extraout_r4` register the export prints).
/// - `status`: security result; `0` means accepted.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes the record state and interrupt channel id, may start an L2CAP
/// connection and may issue up to two disconnect requests.
///
/// # Safety
/// `record` must point inside the sixteen-record pool.
///
/// # Confidence
/// medium - the body is literal; the record pointer is the register value the
/// decompiler printed as `extraout_r4`, recovered as the second argument.
pub unsafe fn fn_80210d04(_tag: u32, record: usize, status: u32) {
    let index = ((record as i32 - BTM_POOL as i32) / HID_REC_STRIDE as i32) as u32 & 0xFF;

    if status == 0 && platform::read_u8(record + HID_REC_STATE) == 6 {
        if platform::read_u8(BTM_POOL_FLAG) > 3 {
            platform::call2(LOG_1, 0x001E_0003, S_HID_SEC_PASS);
        }
        platform::write_u16(record + HID_REC_MTU, 0);

        // observed: `FUN_802128a0(0x13, &DAT_803d4839 + iVar2)`.
        let cid = platform::call2(
            L2CAP_CONNECT_START_SDP,
            HID_PSM_INTERRUPT,
            (record + HID_REC_BDADDR) as u32,
        ) as u16;
        platform::write_u16(record + HID_REC_INTR_CID, cid);

        if cid == 0 {
            if platform::read_u8(BTM_POOL_FLAG) > 1 {
                platform::call2(LOG_1, 0x001E_0001, S_HID_INTR_ORIGINATE_FAILED);
            }
            if platform::read_u8(BTM_POOL_FLAG) > 3 {
                platform::call2(LOG_1, 0x001E_0003, S_HID_POOL_DISCONNECT);
            }
            let ctrl = platform::read_u16(record + HID_REC_CTRL_CID);
            let intr = platform::read_u16(record + HID_REC_INTR_CID);
            if ctrl == 0 && intr == 0 {
                platform::write_u8(record + HID_REC_STATE, 0);
            } else {
                platform::write_u8(record + HID_REC_STATE, 5);
                if intr != 0 {
                    fn_80212dec(intr as u32);
                }
                if ctrl != 0 {
                    fn_80212dec(ctrl as u32);
                }
            }
            let owner = platform::read_u32(HID_OWNER_CALLBACK) as usize;
            platform::call4(owner, index, 1, 0x200, 0);
            return;
        }
        platform::write_u8(record + HID_REC_STATE, 2);
    }

    if status != 0 && platform::read_u8(record + HID_REC_STATE) == 6 {
        platform::write_u16(record + HID_REC_MTU, 0x0F);
        if platform::read_u8(BTM_POOL_FLAG) > 3 {
            platform::call2(LOG_1, 0x001E_0003, S_HID_POOL_DISCONNECT);
        }
        let ctrl = platform::read_u16(record + HID_REC_CTRL_CID);
        let intr = platform::read_u16(record + HID_REC_INTR_CID);
        if ctrl == 0 && intr == 0 {
            platform::write_u8(record + HID_REC_STATE, 0);
        } else {
            platform::write_u8(record + HID_REC_STATE, 5);
            if intr != 0 {
                fn_80212dec(intr as u32);
            }
            if ctrl != 0 {
                fn_80212dec(ctrl as u32);
            }
        }
    }
}

/// Handles the completion of an outgoing HID channel connection.
///
/// The record is selected by either its control or interrupt channel id. A
/// missing channel, a record whose flag bit `1` is clear, or a state that does
/// not match the channel kind is logged as "unexpected conn cnf". On success
/// (`status == 0`) the control channel moves the record to state `6` and
/// registers the interrupt security callback; the interrupt channel moves it to
/// state `3`. Both queue a configuration request. On failure the matching id is
/// cleared and the record is either freed or moved to state `5` with both
/// channels disconnected; the owner callback then gets `status | 0x100`.
///
/// # Original
/// - Ghidra: `FUN_80210F18` at `0x80210F18` (840 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80210f18_FUN_80210f18.c`
///
/// # Arguments
/// - `cid`: local channel id reported by L2CAP.
/// - `status`: connection result; `0` means connected.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes the matched record, may queue a configuration request, may issue two
/// disconnect requests and always reports through [`HID_OWNER_CALLBACK`] on the
/// failure path.
///
/// # Safety
/// The owner callback must be installed when the failure path runs.
///
/// # Confidence
/// high - the four-way scan and every branch are literal; only the record index
/// is recomputed from the matched slot.
pub unsafe fn fn_80210f18(cid: u32, status: u32) {
    // observed: the compiler unrolls four probes per iteration, sixteen total.
    let mut record: usize = 0;
    let mut index = 0u32;
    let mut cursor = BTM_POOL;
    while index < HID_REC_COUNT {
        if platform::read_u8(cursor + HID_REC_IN_USE) != 0
            && platform::read_u8(cursor + HID_REC_STATE) != 0
            && (platform::read_u16(cursor + HID_REC_CTRL_CID) as u32 == cid
                || platform::read_u16(cursor + HID_REC_INTR_CID) as u32 == cid)
        {
            record = cursor;
            break;
        }
        index += 1;
        cursor += HID_REC_STRIDE;
    }

    if record == 0
        || platform::read_u8(record + HID_REC_SUBSTATE) & 1 == 0
        || (platform::read_u16(record + HID_REC_CTRL_CID) as u32 == cid
            && platform::read_u8(record + HID_REC_STATE) != 1)
        || (platform::read_u16(record + HID_REC_INTR_CID) as u32 == cid
            && platform::read_u8(record + HID_REC_STATE) != 2)
    {
        if platform::read_u8(BTM_POOL_FLAG) > 1 {
            platform::call3(LOG_2, 0x001E_0001, S_HID_CONN_CNF_BAD, cid);
        }
        return;
    }

    if status == 0 {
        if platform::read_u16(record + HID_REC_CTRL_CID) as u32 == cid {
            platform::write_u8(record + HID_REC_STATE, 6);
            // observed: bytes +0x1A/+0x1B become 0x01/0x00, i.e. MTU 0x0100.
            platform::write_u8(record + HID_REC_MTU, 1);
            platform::write_u8(record + HID_REC_MTU + 1, 0);
            platform::call7(
                HID_SECURITY_REGISTER,
                (record + HID_REC_BDADDR) as u32,
                HID_PSM_CONTROL,
                1,
                6,
                2 - (platform::read_u16(record + 0x08) >> 15) as u32,
                0x8021_0D04, // fn_80210d04
                record as u32,
            );
        } else {
            platform::write_u8(record + HID_REC_STATE, 3);
        }
        platform::call2(L2CAP_CONFIG_REQUEST, cid, HID_L2CAP_CONFIG_BLOCK as u32);
        if platform::read_u8(BTM_POOL_FLAG) > 3 {
            platform::call3(LOG_2, 0x001E_0003, S_HID_CTRL_CNF, cid);
        }
    } else {
        if platform::read_u16(record + HID_REC_CTRL_CID) as u32 == cid {
            platform::write_u16(record + HID_REC_CTRL_CID, 0);
        } else {
            platform::write_u16(record + HID_REC_INTR_CID, 0);
        }
        if platform::read_u8(BTM_POOL_FLAG) > 3 {
            platform::call2(LOG_1, 0x001E_0003, S_HID_POOL_DISCONNECT);
        }
        let ctrl = platform::read_u16(record + HID_REC_CTRL_CID);
        let intr = platform::read_u16(record + HID_REC_INTR_CID);
        if ctrl == 0 && intr == 0 {
            platform::write_u8(record + HID_REC_STATE, 0);
        } else {
            platform::write_u8(record + HID_REC_STATE, 5);
            if intr != 0 {
                fn_80212dec(intr as u32);
            }
            if ctrl != 0 {
                fn_80212dec(ctrl as u32);
            }
        }
        // observed: `(*DAT_803d4b78)(bVar5, 1, param_2 | 0x100, 0)`.
        let owner = platform::read_u32(HID_OWNER_CALLBACK) as usize;
        platform::call4(owner, index, 1, status | 0x100, 0);
    }
}

