/// Updates the RFCOMM receive-window and flow-control state after a data event.
///
/// Two peer modes are handled. In credit mode (`+0x72 == 2`) the routine marks
/// the window full for an empty queue, or releases credit for a consumed frame
/// and reopens the window when it falls below the low-water mark. In the strict
/// mode it marks the window full when more than `8000` bytes or `0x10` frames
/// are queued and resumes when both drop below `5000` bytes and `8` frames.
///
/// # Original
/// - Ghidra: `FUN_80219FF4` at `0x80219FF4` (460 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80219ff4_FUN_80219ff4.c`
///
/// # Arguments
/// - `port`: RFCOMM port block.
/// - `mode`: `0` for "queue changed", non-zero for "frames consumed".
/// - `frames`: number of consumed frames.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes the window/credit fields, may send a credit frame and a flow event.
///
/// # Safety
/// `port` must be a valid port block; its DLC pointer may be zero.
///
/// # Confidence
/// high - both mode branches, every threshold and the two callback calls are
/// literal.
pub unsafe fn fn_80219ff4(port: usize, mode: u32, frames: u32) {
    let dlc = platform::read_u32(port + RF_PORT_DLC);
    if dlc == 0 {
        return;
    }

    if platform::read_u8(port + RF_DLC_PEER_MODE) == 2 {
        if mode == 0 {
            if platform::read_u32(port + RF_PORT_DATA_CB) == 0 {
                if platform::read_u16(port + RF_PORT_CREDIT_MAX_RX) <= platform::read_u16(port + RF_PORT_WINDOW_COUNT)
                {
                    platform::write_u8(port + RF_PORT_FLOW_STOP, 1);
                }
            } else {
                platform::write_u8(port + RF_PORT_FLOW_STOP, 1);
            }
        } else {
            let credit = platform::read_u16(port + RF_PORT_TX_CREDIT);
            if credit < frames as u16 {
                platform::write_u16(port + RF_PORT_TX_CREDIT, 0);
            } else {
                platform::write_u16(port + RF_PORT_TX_CREDIT, credit - frames as u16);
            }

            let credit = platform::read_u16(port + RF_PORT_TX_CREDIT);
            if credit <= platform::read_u16(port + RF_PORT_CREDIT_MAX_TX)
                && platform::read_u8(port + RF_PORT_FLOW_PAUSE) == 0
                && credit < platform::read_u16(port + RF_PORT_CREDIT_MAX_RX)
            {
                platform::call3(
                    RFCOMM_CREDIT_FRAME,
                    dlc,
                    platform::read_u8(port + RF_PORT_LCID) as u32,
                    (platform::read_u16(port + RF_PORT_CREDIT_MAX_RX) - credit) as u32 & 0xFF,
                );
                platform::write_u8(port + RF_PORT_FLOW_STOP, 0);
                platform::write_u16(
                    port + RF_PORT_TX_CREDIT,
                    platform::read_u16(port + RF_PORT_CREDIT_MAX_RX),
                );
            }
        }
        return;
    }

    if mode == 0 {
        if platform::read_u32(port + RF_PORT_DATA_CB) == 0 {
            if (platform::read_u32(port + RF_PORT_BUFFERED) > 8000
                || platform::read_u16(port + RF_PORT_WINDOW_COUNT) > 0x10)
                && platform::read_u8(port + RF_PORT_FLOW_STOP) == 0
            {
                if platform::read_u8(G_RFCOMM_TRACE_LEVEL) > 3 {
                    platform::call2(LOG_1, 0x0009_0003, S_RFC_DATA_REACHED_HW);
                }
                platform::write_u8(port + RF_PORT_FLOW_STOP, 1);
                platform::call3(
                    RFCOMM_FLOW_EVENT,
                    dlc,
                    platform::read_u8(port + RF_PORT_LCID) as u32,
                    0,
                );
            }
        } else {
            platform::write_u8(port + RF_PORT_FLOW_STOP, 1);
            platform::call3(
                RFCOMM_FLOW_EVENT,
                dlc,
                platform::read_u8(port + RF_PORT_LCID) as u32,
                0,
            );
        }
    } else if platform::read_u8(port + RF_PORT_FLOW_STOP) != 0
        && platform::read_u32(port + RF_PORT_BUFFERED) < 5000
        && platform::read_u16(port + RF_PORT_WINDOW_COUNT) < 8
    {
        platform::write_u8(port + RF_PORT_FLOW_STOP, 0);
        if platform::read_u8(port + RF_PORT_FLOW_PAUSE) == 0 {
            platform::call3(
                RFCOMM_FLOW_EVENT,
                dlc,
                platform::read_u8(port + RF_PORT_LCID) as u32,
                1,
            );
        }
    }
}

