/// Probes the EXI device and publishes the bring-up state words.
///
/// Called once: while [`SDA_EXI_READY`] is zero the routine checks the console
/// status bit `0x10000000`, then sends the two immediate commands `0xF2` and
/// `0xF3` to device `0x0` at address `0xB0000000`. A command that fails marks
/// the state `5`; when both succeed the device is marked ready and `1` is
/// returned.
///
/// # Original
/// - Ghidra: `FUN_80227b70` at `0x80227B70` (252 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80227b70_FUN_80227b70.c`
///
/// # Arguments
/// None.
///
/// # Returns
/// `1` when the device was already probed or the probe succeeded, `0` when the
/// device is absent or a command failed.
///
/// # Side effects
/// Writes [`SDA_EXI_READY`], [`SDA_EXI_STATE`] and [`SDA_EXI_UNKNOWN_ABF0`],
/// masks and restores interrupts and performs two EXI transfers.
///
/// # Safety
/// The two command bytes are passed by address to `0x801BA670`, which reads
/// exactly one byte.
///
/// # Confidence
/// medium - every branch and store is literal; the two command bytes and the
/// device address are literal values whose protocol meaning is not proven.
pub unsafe fn fn_80227b70() -> u32 {
    if platform::read_u32(SDA_EXI_READY) != 0 {
        return 1;
    }

    let status = call0_ret(EXI_STATUS_801A9EE0);
    if status & 0x1000_0000 == 0 {
        platform::write_u32(SDA_EXI_STATE, 2);
        return 0;
    }

    let saved = call0_ret(OS_DEBUG_ENTER);

    let mut command = crate::platform::GuestLocal::<u8>::new( 0xF2);
    let mut rc = platform::call5(
        EXI_IMMEDIATE_801BA670,
        0,
        1,
        0xB000_0000,
        (command.as_mut_ptr() as *mut u8) as u32,
        1,
    );
    if rc == 0 {
        platform::write_u32(SDA_EXI_STATE, 5);
        platform::call1(OS_DEBUG_RESTORE, saved);
        return 0;
    }

    *command = 0xF3;
    rc = platform::call5(
        EXI_IMMEDIATE_801BA670,
        0,
        1,
        0xB000_0000,
        (command.as_mut_ptr() as *mut u8) as u32,
        1,
    );
    if rc == 0 {
        platform::write_u32(SDA_EXI_STATE, 5);
        platform::call1(OS_DEBUG_RESTORE, saved);
        return 0;
    }

    platform::call1(OS_DEBUG_RESTORE, saved);
    platform::write_u32(SDA_EXI_READY, 1);
    platform::write_u32(SDA_EXI_STATE, 0);
    platform::write_u32(SDA_EXI_UNKNOWN_ABF0, 0);
    1
}

