/// - `src`: source buffer.
/// - `size`: `1` takes one byte, `2` one halfword, anything else one
///   byte-swapped word.
///
/// # Returns
/// `1` when both transfers reported success, `0` otherwise.
///
/// # Side effects
/// Programs the EXI control/status registers; reads `src`.
///
/// # Safety
/// `src` must be readable for `size` bytes.
///
/// # Confidence
/// medium - every mask and the three size cases are literal; `0x80228644` is
/// called by address for the reason given on [`fn_802289e8`].
pub unsafe fn fn_80228b0c(address: u32, src: usize, size: i32) -> u32 {
    let payload;

    if size == 2 {
        let half = platform::read_u16(src) as u32;
        payload = (half << 0x18) | ((half & 0xFF00) << 8);
    } else if size < 2 && size > 0 {
        payload = (platform::read_u8(src) as u32) << 0x18;
    } else {
        payload = platform::read_u32(src).swap_bytes();
    }

    platform::write_u32(
        EXI_CONTROL_CD006828,
        (platform::read_u32(EXI_CONTROL_CD006828) & 0x405) | 0xC0,
    );

    let mut command = crate::platform::GuestLocal::new( address);
    let mut data = crate::platform::GuestLocal::new( payload);
    let addressed = platform::call3(
        EXI_BLOCK_80228644,
        (command.as_mut_ptr() as *mut u32) as u32,
        4,
        1,
    );
    let addressed_ok = addressed.leading_zeros();
    while platform::read_u32(EXI_STATUS_CD006834) & 1 != 0 {}

    let written = platform::call3(EXI_BLOCK_80228644, (data.as_mut_ptr() as *mut u32) as u32, 4, 1);
    let written_ok = written.leading_zeros();
    while platform::read_u32(EXI_STATUS_CD006834) & 1 != 0 {}

    let combined = (addressed_ok | written_ok) >> 5;
    platform::write_u32(
        EXI_CONTROL_CD006828,
        platform::read_u32(EXI_CONTROL_CD006828) & 0x405,
    );
    combined.leading_zeros() >> 5
}

/// Reads `length` bytes from an EXI address into a caller buffer, one word at a
/// time.
///
/// # Original
/// - Ghidra: `FUN_80228c10` at `0x80228C10` (224 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80228c10_FUN_80228c10.c`
///
/// # Arguments
/// - `address`: EXI address to read.
/// - `dst`: destination buffer, written one `u32` per iteration.
/// - `length`: byte count; the loop runs while it is positive and subtracts
///   four per word.
///
/// # Returns
/// `1` when every transfer succeeded, `0` otherwise.
///
/// # Side effects
/// Programs the EXI control/status registers and writes `length` bytes.
///
/// # Safety
/// `dst` must be writable for `length` bytes, and `length` should be a multiple
/// of four.
///
/// # Confidence
/// medium - the loop, both status joins and the four-byte step are literal;
/// `0x80228644` is called by address.
pub unsafe fn fn_80228c10(address: u32, dst: usize, length: i32) -> u32 {
    platform::write_u32(
        EXI_CONTROL_CD006828,
        (platform::read_u32(EXI_CONTROL_CD006828) & 0x405) | 0xC0,
    );

    let mut command = crate::platform::GuestLocal::new( address);
    let addressed = platform::call3(
        EXI_BLOCK_80228644,
        (command.as_mut_ptr() as *mut u32) as u32,
        4,
        1,
    );
    let mut result = addressed.leading_zeros() >> 5;
    while platform::read_u32(EXI_STATUS_CD006834) & 1 != 0 {}

    let mut remaining = length;
    let mut cursor = dst;
    while remaining > 0 {
        let mut word = crate::platform::GuestLocal::<u32>::new( 0);
        let read = platform::call3(EXI_BLOCK_80228644, (word.as_mut_ptr() as *mut u32) as u32, 4, 0);
        result |= read.leading_zeros() >> 5;
        while platform::read_u32(EXI_STATUS_CD006834) & 1 != 0 {}
        platform::write_u32(cursor, *word);
        cursor += 4;
        remaining -= 4;
    }

    let ok = result.leading_zeros() >> 5;
    platform::write_u32(
        EXI_CONTROL_CD006828,
        platform::read_u32(EXI_CONTROL_CD006828) & 0x405,
    );
    ok
}

/// Writes `length` bytes from a caller buffer to an EXI address, one word at a
/// time.
///
/// # Original
/// - Ghidra: `FUN_80228cf0` at `0x80228CF0` (224 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80228cf0_FUN_80228cf0.c`
///
/// # Arguments
/// - `address`: EXI address to write.
/// - `src`: source buffer, read one `u32` per iteration.
/// - `length`: byte count; the loop runs while it is positive and subtracts
///   four per word.
///
/// # Returns
/// `1` when every transfer succeeded, `0` otherwise.
///
/// # Safety
/// `src` must be readable for `length` bytes.
///
/// # Confidence
/// medium - the loop and the status join are literal; `0x80228644` is called by
/// address.
pub unsafe fn fn_80228cf0(address: u32, src: usize, length: i32) -> u32 {
    platform::write_u32(
        EXI_CONTROL_CD006828,
        (platform::read_u32(EXI_CONTROL_CD006828) & 0x405) | 0xC0,
    );

    let mut command = crate::platform::GuestLocal::new( address);
    let addressed = platform::call3(
        EXI_BLOCK_80228644,
        (command.as_mut_ptr() as *mut u32) as u32,
        4,
        1,
    );
    let mut result = addressed.leading_zeros() >> 5;
    while platform::read_u32(EXI_STATUS_CD006834) & 1 != 0 {}

    let mut remaining = length;
    let mut cursor = src;
    while remaining > 0 {
        let mut word = crate::platform::GuestLocal::new( platform::read_u32(cursor));
        cursor += 4;
        let written = platform::call3(EXI_BLOCK_80228644, (word.as_mut_ptr() as *mut u32) as u32, 4, 1);
        result |= written.leading_zeros() >> 5;
        while platform::read_u32(EXI_STATUS_CD006834) & 1 != 0 {}
        remaining -= 4;
    }

    let ok = result.leading_zeros() >> 5;
    platform::write_u32(
        EXI_CONTROL_CD006828,
        platform::read_u32(EXI_CONTROL_CD006828) & 0x405,
    );
    ok
}

/// Resolves an index through one of three packed lookup-table encodings.
///
/// The table starts with a `u16` base value at `+0` and a `u16` format at `+4`:
///
/// - format `0`: the answer is the `u16` at `+0xC` plus the index delta,
/// - format `1`: the answer is the `u16` at `+0xC + 2 * delta`,
/// - format `2`: the table holds `count` (`u16` at `+0xC`) sorted `{limit,
///   value}` `u16` pairs from `+0xE`; a binary search over the pairs returns the
///   value of the pair whose limit covers the index.
///
/// # Original
/// - Ghidra: `FUN_8022c120` at `0x8022C120` (204 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8022c120_FUN_8022c120.c`
///
/// # Arguments
/// - `table`: packed lookup table.
/// - `index`: value to resolve.
///
/// # Returns
/// The resolved `u16`, or `0xFFFF` when the index is outside the table or the
/// format is unknown.
///
/// # Safety
/// `table` must be readable for the format's table size.
///
/// # Confidence
/// medium - all three formats and the midpoint arithmetic are literal; the
/// meaning of the resolved value is not proven.
pub unsafe fn fn_8022c120(table: usize, index: u32) -> u32 {
    let format = platform::read_u16(table + 4);

    if format == 0 {
        let base = platform::read_u16(table) as u32;
        let value = platform::read_u16(table + 0x0C) as u32;
        return value.wrapping_add(index.wrapping_sub(base)) & 0xFFFF;
    }

    if format != 2 {
        if format != 1 {
            return 0xFFFF;
        }
        let base = platform::read_u16(table) as u32;
        let delta = index.wrapping_sub(base) as usize;
        return platform::read_u16(table + 0x0C + delta * 2) as u32;
    }

    let count = platform::read_u16(table + 0x0C) as i32;
    let mut low = table + 0x0E;
    let mut high = (table + 0x0E) as isize + ((count - 1) * 4) as isize;

    loop {
        let probe = loop {
            if high < low as isize {
                return 0xFFFF;
            }
            let span = (high - low as isize) as i32;
            let mut elements = span >> 2;
            if span < 0 && span & 3 != 0 {
                elements += 1;
            }
            let step = elements.wrapping_mul(2) & !3i32;
            let candidate = (low as isize + step as isize) as usize;
            if index <= platform::read_u16(candidate) as u32 {
                break candidate;
            }
            low = candidate + 4;
        };
        if platform::read_u16(probe) as u32 <= index {
            return platform::read_u16(probe + 2) as u32;
        }
        high = probe as isize - 4;
    }
}

/// Locates one cell of a tiled image and fills the caller's descriptor.
///
/// The index is split into a cell number and an in-cell offset using the sheet
/// width/height at `+0xC`/`+0xE`. The descriptor receives:
///
/// | Offset | Value |
/// ---:|---|
/// | `+0` | `+0x14` base plus `cell * (+4)` stride |
/// | `+4..+7` | three tile bytes from the range table (or `image + 4`) |
/// | `+7` | sheet byte `+1` |
/// | `+8` | `u16` sheet field `+0xA` |
/// | `+0xC` | `u16` sheet field `+0x10` |
/// | `+0xE` | `u16` sheet field `+0x12` |
/// | `+0x10` | in-cell x, `(x * (sheet[0] + 1)) + 1` |
/// | `+0x12` | in-cell y, `(y * (sheet[1] + 1)) + 1` |
///
/// # Original
/// - Ghidra: `FUN_8022c1f0` at `0x8022C1F0` (264 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8022c1f0_FUN_8022c1f0.c`
///
/// # Arguments
/// - `model`: object holding the image at `+0x14`.
/// - `cell`: descriptor to fill (18 bytes).
/// - `index`: tile index.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes the whole descriptor.
///
/// # Safety
/// `model + 0x14` must lead to the image block, and `cell` must be writable for
/// `0x14` bytes.
///
/// # Confidence
/// medium - every offset and the range-table walk are literal; the field roles
/// are named from their use only.
pub unsafe fn fn_8022c1f0(model: usize, cell: usize, index: u32) {
    let image = platform::read_u32(model + 0x14) as usize;
    let sheet = platform::read_u32(image + 8) as usize;

    let sheet_width = platform::read_u16(sheet + 0x0C) as u32;
    let sheet_height = platform::read_u16(sheet + 0x0E) as u32;
    let per_cell = sheet_width.wrapping_mul(sheet_height);

    let cell_index = index / per_cell;
    let within = index - cell_index * per_cell;
    let row = (within / sheet_width) as u16 as i16 as i32;

    let base = platform::read_u32(sheet + 0x14);
    let stride = platform::read_u32(sheet + 4);
    platform::write_u32(
        cell,
        base.wrapping_add(cell_index.wrapping_mul(stride)),
    );

    let mut node = platform::read_u32(image + 0x0C) as usize;
    loop {
        if node == 0 {
            let source = image + 4;
            platform::write_u8(cell + 4, platform::read_u8(source));
            platform::write_u8(cell + 5, platform::read_u8(source + 1));
            platform::write_u8(cell + 6, platform::read_u8(source + 2));
            break;
        }
        let low = platform::read_u16(node) as u32;
        let high = platform::read_u16(node + 2) as u32;
        if low <= index && index <= high {
            let source = node + ((index - low) * 3) as usize + 8;
            platform::write_u8(cell + 4, platform::read_u8(source));
            platform::write_u8(cell + 5, platform::read_u8(source + 1));
            platform::write_u8(cell + 6, platform::read_u8(source + 2));
            break;
        }
        node = platform::read_u32(node + 4) as usize;
    }

    platform::write_u8(cell + 7, platform::read_u8(sheet + 1));
    platform::write_u32(cell + 8, platform::read_u16(sheet + 0x0A) as u32);
    platform::write_u16(cell + 0x0C, platform::read_u16(sheet + 0x10));
    platform::write_u16(cell + 0x0E, platform::read_u16(sheet + 0x12));

    let x = within as i32 - row * sheet_width as i32;
    let x_step = platform::read_u8(sheet) as i32 + 1;
    let y_step = platform::read_u8(sheet + 1) as i32 + 1;
    platform::write_u16(cell + 0x10, (x * x_step + 1) as u16);
    platform::write_u16(cell + 0x12, (row * y_step + 1) as u16);
}

// ===========================================================================
// Wave 92 - IOS IPC completion-block wrappers and four small helper clusters,
// 0x80226740..0x8022C1F0
//
// The `0x80220000` bucket is mostly the platform layer that the game talks to
// the Hollywood IOS co-processor through. Waves 84 and 89 translated the
// request core (`0x802243C0..0x802265C0`); this pass lands the wrappers that sit
// directly on top of it plus four self-contained helper groups further down the
// bucket:
//
// - `0x80226740..0x80227730` (16 bodies): the completion-block wrappers. Every
//   one of them allocates a `0x140`-byte block from [`SDA_IPC_BLOCK_HEAP`],
//   fills the name/buffer part at `+0`, the completion fields at `+0x100`
//   (callback), `+0x104` (callback context) and `+0x108` (copy-out mode), then
//   submits kind `3`, `6`, `7`, `8`, `9` or `0xB` through [`fn_80225640`],
//   [`fn_80225500`], [`fn_802258b0`], [`fn_802259a0`] or [`fn_80224b50`].
//   Their `+0x108` mode values line up with the five copy-out layouts of
//   [`fn_802265c0`].
// - `0x80227B70..0x80227C70`: the two EXI bring-up probes that publish the
//   `0x8042ABE8`/`0x8042ABEC`/`0x8042ABF4` state words.
// - `0x80228DF0..0x80228F80`: an intrusive doubly linked list with a
//   caller-supplied node offset (`u16` at `+0xA`, count at `+8`): append,
//   insert-before and unlink.
// - `0x802289E8..0x80228CF0`: the register-level EXI transfer helpers (one
//   word in, one word out, block read, block write) that drive
//   `0xCD006828`/`0xCD006834` through `0x80228644`.
// - `0x8022C120..0x8022C1F0`: a tile-table index lookup and the atlas cell
//   locator built on it.
// - `0x8022C980`: the deleting-destructor twin of [`fn_80229370`].
//
// `0x802DCD5C..0x802DCD74` are again the register-save prologues, not calls.
// The wrappers below take their first two inputs from the folded prologue pair;
// the pair's high half is the incoming `r3`, the low half the incoming `r4`
// (verified against [`fn_80225640`], which stores them at `+8`/`+0xC` in that
// order).
// ===========================================================================

// --- SDA1 words used by this pass ------------------------------------------

/// `r13 - 0x4A98` -> `0x8042ABE8`: non-zero once the EXI device probe ran.
const SDA_EXI_READY: usize = 0x8042_ABE8;

/// `r13 - 0x4A94` -> `0x8042ABEC`: probe state written by [`fn_80227b70`]
/// (`0` idle, `1` running, `2` absent, `5` failed).
const SDA_EXI_STATE: usize = 0x8042_ABEC;

/// `r13 - 0x4A90` -> `0x8042ABF0`: word cleared when the probe succeeds.
///
/// `// unknown:` no reader in this lane.
const SDA_EXI_UNKNOWN_ABF0: usize = 0x8042_ABF0;

/// `r13 - 0x4A8C` -> `0x8042ABF4`: probe result word; `0xA5FF005A` means the
/// device answered, `0` means it is absent.
///
/// `// inferred:` the magic is byte-reversed `0x5A00FFA5`, which reads like a
/// little-endian device id; no string in the image names it.
const SDA_EXI_PROBE_RESULT: usize = 0x8042_ABF4;

// --- Callees ---------------------------------------------------------------

/// `0x801A9EE0`: returns the console/EXI device status word.
///
/// `// inferred:` bit `0x10000000` is the "device present" bit; every caller
/// in this bucket tests it before touching `0xCD006828`.
const EXI_STATUS_801A9EE0: usize = 0x801A_9EE0;

/// `0x801BA670`: EXI immediate transfer (`channel`, `device`, `address`,
/// `buffer`, `length`).
///
/// `// inferred:` the five arguments are literal at every call site; the
/// routine name is not in the image.
const EXI_IMMEDIATE_801BA670: usize = 0x801B_A670;

/// `0x80228644`: EXI block transfer (`buffer`, `length`, `write`).
///
/// `// inferred:` the third argument is `1` for the address phase and the data
/// write, `0` for the data read. Its own Ghidra export is a dead `while(1)`
/// loop (all blocks below the loop were removed as unreachable); wave 116
/// reconstructed the body from the raw instruction stream in
/// `work/dol/main.elf` as [`fn_80228644`]. The four EXI helpers still call the
/// address, which is behaviourally identical.
const EXI_BLOCK_80228644: usize = 0x8022_8644;

/// `0xCD006828`: EXI control register. The low byte is set to `0xC0` (start)
/// and cleared back to the `0x405` mask bits after each transfer.
const EXI_CONTROL_CD006828: usize = 0xCD00_6828;

/// `0xCD006834`: EXI status register; bit `0` is `busy`.
const EXI_STATUS_CD006834: usize = 0xCD00_6834;

/// Size of one completion block (`// observed:` every `0x80226xxx` wrapper
/// allocates `0x140` bytes).
const IPC_COMPLETION_BLOCK: u32 = 0x140;

/// Allocates, fills and submits a kind-3 completion block carrying a bounded
/// name and four trailing bytes.
///
/// The name is copied to `block + 6` with its NUL, and the four result bytes go
/// to `+0x49`, `+0x46`, `+0x47` and `+0x48` - the order [`fn_802265c0`]'s mode
/// `3` copy-out reads them back in.
///
/// # Original
/// - Ghidra: `FUN_80226740` at `0x80226740` (244 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80226740_FUN_80226740.c`
/// - Removed: the modelled `_restgpr_25` epilogue call (`0x802DCDB8`).
///   it only restores registers.
///
/// # Arguments
/// - `name`: NUL-terminated name, at most `0x40` bytes inspected.
/// - `tag`: byte stored at `+0x49`; the export reaches it through
///   `extraout_r4`, so its source register is inferred.
/// - `at_46`, `at_47`, `at_48`: bytes stored at those offsets.
///
/// # Returns
/// `0` when the request was accepted, `-101` (`0xFFFFFF9B`) for a bad name or a
/// closed resource, `-22` (`0xFFFFFFEA`) when the block cannot be allocated.
///
/// # Side effects
/// Allocates and releases one `0x140`-byte block and queues an IPC request.
///
/// # Safety
/// `name` must be readable up to its NUL or `0x40` bytes; the IPC pool must
/// exist.
///
/// # Confidence
/// medium - every store and both calls are literal; the name pointer is the low
/// half of the `FUN_802dcd6c()` pair and `tag` arrives as `extraout_r4`, so the
/// two cannot both be `r4` and the register order is inferred.
pub unsafe fn fn_80226740(name: usize, tag: u8, at_46: u8, at_47: u8, at_48: u8) -> i32 {
    let mut block = 0usize;
    let status;

    if name == 0 || platform::read_i32(SDA_IPC_RESOURCE) < 0 {
        status = -0x65;
    } else {
        let len = fn_80224390(name, 0x40);
        if len == 0x40 {
            status = -0x65;
        } else {
            block = fn_80225eb0(
                platform::read_u32(SDA_IPC_BLOCK_HEAP),
                IPC_COMPLETION_BLOCK,
                IPC_REQUEST_ALIGN,
            );
            if block == 0 {
                status = -0x16;
            } else {
                platform::call3(MEMCPY, (block + 6) as u32, name as u32, (len + 1) as u32);
                platform::write_u8(block + 0x49, tag);
                platform::write_u8(block + 0x46, at_46);
                platform::write_u8(block + 0x47, at_47);
                platform::write_u8(block + 0x48, at_48);
                status = fn_80225640(
                    platform::read_u32(SDA_IPC_RESOURCE),
                    3,
                    block as u32,
                    0x4C,
                    0,
                    0,
                );
            }
        }
    }

    if block != 0 {
        fn_802260c0(platform::read_u32(SDA_IPC_BLOCK_HEAP), block as u32);
    }
    status
}

/// Asynchronous twin of [`fn_80226740`]: same kind-3 name block, but the
/// completion callback and its context are stored at `+0x100`/`+0x104` and the
/// submission goes through [`fn_80225500`], so the block outlives the call.
///
/// # Original
/// - Ghidra: `FUN_80226840` at `0x80226840` (244 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80226840_FUN_80226840.c`
/// - Removed: the modelled `_restgpr_23` epilogue call (`0x802DCDB0`).
///   it only restores registers.
///
/// # Arguments
/// - `name`: NUL-terminated name, at most `0x40` bytes inspected.
/// - `tag`: byte stored at `+0x49` (the `extraout_r4` register).
/// - `at_46`, `at_47`, `at_48`: bytes stored at those offsets.
/// - `callback`: completion callback stored at `+0x100`.
/// - `context`: callback context stored at `+0x104`.
///
/// # Returns
/// The submission status, `-101` for a bad name, or `-22` on allocation
/// failure.
///
/// # Side effects
/// Allocates one `0x140`-byte block and queues a kind-3 request with callback.
///
/// # Safety
/// `name` must be readable up to its NUL or `0x40` bytes; the callback receives
/// `(status, block)`.
///
/// # Confidence
/// medium - all eleven stores and both calls are literal; the name/tag register
/// split is inferred exactly as for [`fn_80226740`].
pub unsafe fn fn_80226840(
    name: usize,
    tag: u8,
    at_46: u8,
    at_47: u8,
    at_48: u8,
    callback: u32,
    context: u32,
) -> i32 {
    let status;

    if name == 0 || platform::read_i32(SDA_IPC_RESOURCE) < 0 {
        status = -0x65;
    } else {
        let len = fn_80224390(name, 0x40);
        if len == 0x40 {
            status = -0x65;
        } else {
            let block = fn_80225eb0(
                platform::read_u32(SDA_IPC_BLOCK_HEAP),
                IPC_COMPLETION_BLOCK,
                IPC_REQUEST_ALIGN,
            );
            if block == 0 {
                status = -0x76;
            } else {
                platform::write_u32(block + 0x100, callback);
                platform::write_u32(block + 0x104, context);
                platform::write_u32(block + 0x108, 0);
                platform::call3(MEMCPY, (block + 6) as u32, name as u32, (len + 1) as u32);
                platform::write_u8(block + 0x49, tag);
                platform::write_u8(block + 0x46, at_46);
                platform::write_u8(block + 0x47, at_47);
                platform::write_u8(block + 0x48, at_48);
                status = fn_80225500(
                    platform::read_u32(SDA_IPC_RESOURCE),
                    3,
                    block as u32,
                    0x4C,
                    0,
                    0,
                    IPC_DONE_802265C0,
                    block as u32,
                );
            }
        }
    }

    status
}

/// Copies a name into a completion block and submits a kind-4 request with one
/// optional extra buffer, then reads the answer back.
///
/// The block is a kind-7 vector table: entry 1 is `(block + 0x40, 4)` and, when
/// the caller passed a buffer, entry 2 is `(buffer, count * 13)`.
