/// `countLeadingZeros(mode - 3) >> 5` idiom, which is true exactly when
/// `mode == 3`, and the two folded arguments are recovered from their uses.
pub unsafe fn fn_80208d80(handle: u32, status: u32) {
    let record = fn_802023a8(handle) as usize;
    let mut result = status;

    if platform::read_u8(BTM_SEC_LOG_LEVEL) > 3 {
        let state = if record == 0 {
            0
        } else {
            platform::read_u8(record + BTM_SEC_STATE) as u32
        };
        platform::call4(
            LOG_3,
            0x000D_0003,
            S_BTM_SEC_AUTH_COMPLETE,
            result,
            state,
        );
    }

    if platform::read_u8(BTM_SEC_RESTORE_AUTH) != 0 {
        platform::write_u8(BTM_SEC_RESTORE_AUTH, 0);
        // observed: `countLeadingZeros(mode - 3) >> 5` is 1 only when mode == 3.
        let enable = if platform::read_u32(BTM_SEC_MODE_803D34F0) == 3 {
            1u8
        } else {
            0u8
        };
        if platform::read_u8(BTM_SEC_LOG_LEVEL) > 4 {
            platform::call3(LOG_2, 0x000D_0004, S_BTM_SEC_RESTORE_AUTH, enable as u32);
        }
        fn_8020e83c(enable);
    }

    if platform::read_u8(BTM_SEC_RESTORE_SNIFF) != 0 {
        platform::write_u8(BTM_SEC_RESTORE_SNIFF, 0);
        fn_8020e2c8(platform::read_u8(BTM_SEC_UNIT_MODE));
    }

    let mut queued = platform::read_u8(BTM_SEC_QUEUED_HANDLE);
    if record != 0
        && platform::read_u8(record + BTM_DEV_SEC_FLAGS) & 0x40 != 0
        && platform::read_u8(BTM_SEC_QUEUE_BLOCKED) == 0
    {
        platform::write_u8(
            record + BTM_DEV_SEC_FLAGS,
            platform::read_u8(record + BTM_DEV_SEC_FLAGS) & 0xAF,
        );
        if queued != 0 {
            // observed: the lookup repeats on the *current* handle, not the
            // queued byte.
            let other = fn_802023a8(handle) as usize;
            if other != 0 && platform::read_u8(other + BTM_DEV_SEC_FLAGS) & 0x40 == 0 {
                let previous = platform::read_u8(other + BTM_SEC_STATE);
                if previous != 5 {
                    platform::write_u8(other + BTM_SEC_STATE, 5);
                    if !fn_8020ced4(handle as u16, queued) {
                        platform::write_u8(other + BTM_SEC_STATE, previous);
                    }
                }
            }
        }
    }
    platform::write_u8(BTM_SEC_QUEUED_HANDLE, queued);

    if record == 0 {
        return;
    }

    if platform::read_u8(record + BTM_SEC_STATE) == 1 {
        if result == 0x0C && platform::read_u8(record + BTM_DEV_FLAGS) & 6 == 6 {
            result = 0;
        }
        let callback = platform::read_u32(BTM_SEC_COMPLETE_CB);
        if callback != 0 {
            platform::call4(
                callback as usize,
                (record + BTM_DEV_BDADDR) as u32,
                (record + BTM_DEV_COD) as u32,
                (record + BTM_DEV_NAME) as u32,
                result,
            );
        }
        platform::write_u8(record + BTM_SEC_STATE, 0);

        if platform::read_u8(record + BTM_DEV_SEC_FLAGS) & 0x40 == 0 {
            if result == 0 {
                // observed: the "key known" bit is set before the procedure runs.
                platform::write_u8(
                    record + BTM_DEV_FLAGS,
                    platform::read_u8(record + BTM_DEV_FLAGS) | 2,
                );
                let next = platform::call1(BTM_SEC_EXECUTE_8020A0B0, record as u32) as u32;
                let pending = platform::read_u32(record + 4);
                if next != 1 && pending != 0 {
                    clear_owner(record);
                    platform::call3(
                        pending as usize,
                        (record + BTM_DEV_BDADDR) as u32,
                        platform::read_u32(record + 8),
                        next,
                    );
                    platform::write_u32(record + 4, 0);
                }
            } else {
                let pending = platform::read_u32(record + 4);
                if pending != 0 {
                    clear_owner(record);
                    platform::call3(
                        pending as usize,
                        (record + BTM_DEV_BDADDR) as u32,
                        platform::read_u32(record + 8),
                        10,
                    );
                    platform::write_u32(record + 4, 0);
                }
                fn_8020ced4(platform::read_u16(record + BTM_DEV_HANDLE), 5);
            }
        } else {
            platform::write_u8(
                record + BTM_DEV_SEC_FLAGS,
                platform::read_u8(record + BTM_DEV_SEC_FLAGS) & 0xAF,
            );
            fn_8020ced4(platform::read_u16(record + BTM_DEV_HANDLE), 0x13);
        }
    } else {
        let callback = platform::read_u32(BTM_SEC_COMPLETE_CB);
        if callback != 0 && result != 0 {
            platform::call4(
                callback as usize,
                (record + BTM_DEV_BDADDR) as u32,
                (record + BTM_DEV_COD) as u32,
                (record + BTM_DEV_NAME) as u32,
                result,
            );
        }
    }
}

/// Handles an encryption-change event.
///
/// `0x23` is the "key refresh collision" code: the security timer is re-armed
/// with [`fn_8020a5ac`] after 22 ticks. Success marks both link-key bits and
/// completes an encryption procedure in state `2`; any other result fails the
/// pending callback with reason `10`.
///
/// # Original
/// - Ghidra: `FUN_802091C0` at `0x802091C0` (316 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802091c0_FUN_802091c0.c`
///
/// # Arguments
/// - `handle`: connection handle.
/// - `status`: HCI encryption-change result.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// May write [`BTM_SEC_TIMER_CALLBACK`]/[`BTM_SEC_TIMER_RECORD`] and arm
/// [`BTM_SEC_TIMER`]; writes record flags and runs the `+4` callback.
///
/// # Safety
/// The record comes from [`fn_802023a8`]; fixed BSS is read and written.
///
/// # Confidence
/// medium - all three branches, the `| 6` flag write and the timer arm are
/// literal; the two folded arguments are recovered from their uses.
pub unsafe fn fn_802091c0(handle: u32, status: u32) {
    let record = fn_802023a8(handle) as usize;

    if platform::read_u8(BTM_SEC_LOG_LEVEL) > 3 {
        let state = if record == 0 {
            0
        } else {
            platform::read_u8(record + BTM_SEC_STATE) as u32
        };
        platform::call4(LOG_3, 0x000D_0003, S_BTM_SEC_ENCRYPT_CHANGE, status, state);
    }
    if record == 0 {
        return;
    }

    if status == 0x23 {
        // observed: the collision timeout callback and the watched record.
        platform::write_u32(
            BTM_SEC_TIMER_CALLBACK,
            fn_8020a5ac as unsafe fn() as usize as u32,
        );
        platform::write_u32(BTM_SEC_TIMER_RECORD, record as u32);
        platform::call3(TIMER_ARM, BTM_SEC_TIMER as u32, 0x16, 1);
    } else if status == 0 {
        platform::write_u8(
            record + BTM_DEV_FLAGS,
            platform::read_u8(record + BTM_DEV_FLAGS) | 6,
        );
        if platform::read_u8(record + BTM_SEC_STATE) == 2 {
            platform::write_u8(record + BTM_SEC_STATE, 0);
            let next = platform::call1(BTM_SEC_EXECUTE_8020A0B0, record as u32) as u32;
            let pending = platform::read_u32(record + 4);
            if next != 1 && pending != 0 {
                platform::call2(
                    pending as usize,
                    (record + BTM_DEV_BDADDR) as u32,
                    platform::read_u32(record + 8),
                );
                platform::write_u32(record + 4, 0);
            }
        }
    } else {
        let pending = platform::read_u32(record + 4);
        if pending != 0 {
            platform::call3(
                pending as usize,
                (record + BTM_DEV_BDADDR) as u32,
                platform::read_u32(record + 8),
                10,
            );
            platform::write_u32(record + 4, 0);
        }
    }
}

