/// Cancels a security procedure and resets the record.
///
/// When the link is authenticated the completion callback receives the reason
/// (`0x17` preserved, anything else folded to `5`). A matching temporary key
/// slot is cancelled, cleared and reported as `0x0E`. The record is then
/// returned to idle: handle `0xFFFF`, state `0`, key-type bits and the
/// procedure flags cleared.
///
/// # Original
/// - Ghidra: `FUN_80209878` at `0x80209878` (316 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80209878_FUN_80209878.c`
///
/// # Arguments
/// - `handle`: connection handle.
/// - `status`: reason code being reported.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Cancels [`BTM_SEC_TIMER`] and clears [`BTM_SEC_KEY_803D34CC`]; runs
/// [`BTM_SEC_COMPLETE_CB`] up to twice.
///
/// # Safety
/// Reads and writes fixed BSS only.
///
/// # Confidence
/// medium - the callback arguments, the compare/cancel pair and the five
/// clears are literal; the handle comes from the folded `FUN_802023a8()` call.
pub unsafe fn fn_80209878(handle: u32, status: u32) {
    let record = fn_802023a8(handle) as usize;
    if record == 0 {
        return;
    }

    if platform::read_u8(record + BTM_DEV_SEC_FLAGS) & 0x40 != 0 {
        let callback = platform::read_u32(BTM_SEC_COMPLETE_CB);
        if callback != 0 {
            let reason = if status == 0x17 { 0x17 } else { 5 };
            platform::call4(
                callback as usize,
                (record + BTM_DEV_BDADDR) as u32,
                (record + BTM_DEV_COD) as u32,
                (record + BTM_DEV_NAME) as u32,
                reason,
            );
        }
    }

    if platform::read_u32(BTM_SEC_TIMER_ACTIVE) != 0
        && platform::call3(
            COMPARE_BYTES,
            BTM_SEC_KEY_803D34CC as u32,
            (record + BTM_DEV_BDADDR) as u32,
            6,
        ) == 0
    {
        platform::call1(TIMER_CANCEL, BTM_SEC_TIMER as u32);
        platform::write_u32(BTM_SEC_TIMER_ACTIVE, 0);
        platform::call3(MEMSET_WRAPPER, BTM_SEC_KEY_803D34CC as u32, 0xFF, 6);
        let callback = platform::read_u32(BTM_SEC_COMPLETE_CB);
        if callback != 0 {
            platform::call4(
                callback as usize,
                (record + BTM_DEV_BDADDR) as u32,
                (record + BTM_DEV_COD) as u32,
                (record + BTM_DEV_NAME) as u32,
                0x0E,
            );
        }
    }

    platform::write_u16(record + BTM_DEV_HANDLE, 0xFFFF);
    platform::write_u8(record + BTM_SEC_STATE, 0);
    platform::write_u8(
        record + BTM_DEV_FLAGS,
        platform::read_u8(record + BTM_DEV_FLAGS) & 0xF8,
    );
    platform::write_u8(
        record + BTM_DEV_SEC_FLAGS,
        platform::read_u8(record + BTM_DEV_SEC_FLAGS) & 0x80,
    );
    platform::write_u32(record + 4, 0);
}

/// Handles a link-key notification from the controller.
///
/// Stores the 16-byte key and its type on the device record. When the record
/// is not yet authenticated (or was authenticated but has no key) the
/// completion is deferred by setting `+0x82`; otherwise the link-key callbacks
/// fire immediately.
