    platform::write_u16(packet + HCI_PKT_TAG, 0x0C);
    platform::write_u16(packet + HCI_PKT_ZERO, 0);
    platform::write_u8(packet + HCI_OPCODE, 0x03);
    platform::write_u8(packet + HCI_OPCODE + 1, 0x04);
    platform::write_u8(packet + HCI_PARAM_LEN, 9);
    platform::write_u8(packet + HCI_PARAMS, max_period as u8);
    platform::write_u8(packet + HCI_PARAMS + 1, (max_period >> 8) as u8);
    platform::write_u8(packet + HCI_PARAMS + 2, min_period as u8);
    platform::write_u8(packet + HCI_PARAMS + 3, (min_period >> 8) as u8);
    platform::write_u8(packet + HCI_PARAMS + 4, platform::read_u8(lap + 2));
    platform::write_u8(packet + HCI_PARAMS + 5, platform::read_u8(lap + 1));
    platform::write_u8(packet + HCI_PARAMS + 6, platform::read_u8(lap));
    platform::write_u8(packet + HCI_PARAMS + 7, inquiry_length);
    platform::write_u8(packet + HCI_PARAMS + 8, num_responses);

    fn_8020ac78(packet as u32);
    true
