    platform::write_u16(packet + HCI_PKT_TAG, 0x1A);
    platform::write_u16(packet + HCI_PKT_ZERO, 0);
    platform::write_u8(packet + HCI_OPCODE, 0x0D);
    platform::write_u8(packet + HCI_OPCODE + 1, 0x04);
    platform::write_u8(packet + HCI_PARAM_LEN, 0x17);

    let mut index = 0;
    while index < 6 {
        platform::write_u8(
            packet + HCI_PARAMS + index,
            platform::read_u8(bd_addr + 5 - index),
        );
        index += 1;
    }
    platform::write_u8(packet + HCI_PARAMS + 6, pin_len as u8);

    let mut copied = 0u32;
