/// Initialises one 0x16C-byte render object from a source object.
///
/// Two contiguous word blocks are copied: `source +0x00..+0x20` into
/// `object +0xD8..+0x158` (34 words) and the four trailing bytes into
/// `+0x160..+0x162`. The `flags` bit `0` selects the vertex-format bind path,
/// which stores the bind result at `+0x14` or aborts through
/// `0x801D9850` when `mode` is set; bit `1` is stored at `+0x169`. The call
/// ends by resetting the range at `+0x14`, clearing the armed byte at `+0x16B`
/// and raising the ready bytes.
///
/// # Original
/// - Ghidra: `FUN_8022AC40` at `0x8022AC40` (600 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8022ac40_FUN_8022ac40.c`
///
/// # Arguments
/// - `object`: writable 0x16C-byte object.
/// - `source`: 0x90-byte source record.
/// - `flags`: bit `0` = bind the vertex format, bit `1` = store at `+0x169`.
/// - `mode`: non-zero lets the failure path release the format block.
///
/// # Returns
/// `1` on success, `0` when the format bind failed.
///
/// # Side effects
/// Writes the object header, may call the virtual slot at `+0x10`, binds or
/// releases a vertex-format block and stores `mode` at `+0x16C`.
///
/// # Safety
/// `object` must be writable for `0x16C` bytes and `source` readable for
/// `0x90` bytes; the vtable slot at `+0x10` must be callable when `+0x16B` is
/// set.
///
/// # Confidence
/// medium - the copy ranges, the flag bytes and the failure path are literal;
/// the two vertex-format callees are named from their call site only.
pub unsafe fn fn_8022ac40(object: usize, source: usize, flags: u32, mode: i32) -> u32 {
    if platform::read_u8(object + 0x16B) != 0 {
        let vtable = platform::read_u32(object) as usize;
        platform::call1(platform::read_u32(vtable + 0x10) as usize, object as u32);
    }

    // observed: `piVar4[0x36]..piVar4[0x57]` are loaded from `piVar7[0..0x21]`.
    let mut index = 0usize;
    while index < 0x22 {
        platform::write_u32(
            object + 0xD8 + index * 4,
            platform::read_u32(source + index * 4),
        );
        index += 1;
    }

    platform::write_u8(object + 0x160, platform::read_u8(source + 0x88));
    platform::write_u8(object + 0x161, platform::read_u8(source + 0x89));
    platform::write_u8(object + 0x162, platform::read_u8(source + 0x8A));
    platform::write_u8(object + 0x168, (flags & 1) as u8);
    platform::write_u8(object + 0x169, ((flags >> 1) & 1) as u8);

    if flags & 1 != 0 {
        let mut bound = crate::platform::GuestLocal::<u32>::new( 0);
        if platform::call2(
            FORMAT_BIND_801D9040,
            (object + 0xD8) as u32,
            (bound.as_mut_ptr() as *mut u32) as u32,
        ) != 0
        {
            if mode != 0 {
                platform::call1(FORMAT_RELEASE_801D9850, (object + 0xD8) as u32);
            }
            return 0;
        }
        platform::write_u32(object + RANGE_OWNER_OFFSET, *bound);
    }

    fn_80229e20(object + RANGE_OWNER_OFFSET, 0, 0);
    platform::write_u8(object + 0x16B, 0);
    platform::write_u8(object + 0x16C, mode as u8);
    platform::write_u8(object + 4, 1);
    1
}

/// Opens the source of a render object through the device layer.
///
/// When the object has no source yet (`+0x10 == 0`), the id is opened with
/// `0x801B0D60`; on success the device's `u16` id is cached at
/// [`SDA_DEVICE_ID`], the three virtual slots at `+0x24`, `+0x28` and `+0x58`
/// are queried, and the last one is applied through [`fn_8022b410`].
///
/// # Original
/// - Ghidra: `FUN_8022B5A0` at `0x8022B5A0` (212 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8022b5a0_FUN_8022b5a0.c`
///
/// # Arguments
/// - `object`: render object; its vtable must provide the three slots.
/// - `id`: device id to open.
///
/// # Returns
/// `1` when the open succeeded, `0` when the object already had a source or
/// the open failed.
///
/// # Side effects
/// Stores the source id at `+0x10`, clears the byte at `+0x14`, writes two
/// virtual results at `+0x15`/`+0x16` and updates [`SDA_DEVICE_ID`].
///
/// # Safety
/// `object` must be a live object of its class; the three vtable slots must be
/// callable with `object` as the receiver.
///
/// # Confidence
/// medium - the guard, the three virtual calls and the two byte stores are
/// literal; the device routines are named from their return use.
pub unsafe fn fn_8022b5a0(object: usize, id: u32) -> u32 {
    if platform::read_u32(object + 0x10) != 0 {
        return 0;
    }

    let opened = platform::call1(DEVICE_OPEN_801B0D60, id);
    if opened == 0 {
        return 0;
    }

    let device = call0_ret(DEVICE_ID_801B00A0) as u16;
    platform::write_u16(SDA_DEVICE_ID, device);
    platform::write_u32(object + 0x10, id);
    platform::write_u8(object + 0x14, 0);

    let vtable = platform::read_u32(object) as usize;
    let first = platform::call1(platform::read_u32(vtable + 0x24) as usize, object as u32) as u8;
    platform::write_u8(object + 0x15, first);
    let second = platform::call1(platform::read_u32(vtable + 0x28) as usize, object as u32) as u8;
    platform::write_u8(object + 0x16, second);
    let selector = platform::call1(platform::read_u32(vtable + 0x58) as usize, object as u32);
    fn_8022b410(object, selector as i32);

    1
}

// ===========================================================================
// Wave 99: the BTM inquiry tail and the SCO/eSCO link table,
// 0x8020013C..0x8020BB44
//
// The `0x80200000` bucket still had 47 untranslated records when this pass
// started. 27 of them form two call-graph clusters plus three isolated
// helpers:
//
// - the inquiry machinery, `0x80204750..0x80205350`: the twelve-record
//   database at [`BTM_INQ_DB`], the request block it is driven from, the
//   event filter and the 0x0401/0x0403 packet builders of wave 93;
// - the SCO/eSCO link layer, `0x80205EBC..0x80207AF0`: the three
//   `0x34`-byte connection slots at [`CONN_SLOT_TABLE`], the parallel
//   `0x22`-byte packet-type records at [`SCO_POOL_803D2044`] and the two
//   8-byte service slots that receive their state changes;
// - `0x80207BB4` (security authorization), `0x8020BB44` (GAP connection
//   indication), `0x8020013C` (payload-size lookup) and `0x80201754` (QoS
//   completion).
//
// `r13`/`r2` are still [`crate::boot::entry::SDA1_BASE`] /
// [`crate::boot::entry::SDA2_BASE`]; every address below states the offset it
// was recovered from when Ghidra printed `unaff_r13`/`unaff_r2`.
// ===========================================================================

// --- Inquiry request block, 0x803D33AC..0x803D33BF -------------------------

/// `0x803D33AC`: first byte of the ten-byte inquiry request block.
///
/// `// observed:` [`fn_80204858`] copies `request[0..0x0A]` here; `+0` selects
/// mode `0`/`1` and the six-byte `BD_ADDR` sits at `+4`.
const BTM_INQ_REQUEST: usize = 0x803D_33AC;

/// `0x803D33AD`: request byte passed to the `0x0401`/`0x0403` builders.
const BTM_INQ_REQUEST_ID: usize = 0x803D_33AD;

/// `0x803D33AE`: inquiry length, clamped to `0xC` by [`fn_80205350`].
const BTM_INQ_REQUEST_LIMIT: usize = 0x803D_33AE;

/// `0x803D33AF`: event-filter selector (`0` none, `1` split, `2` raw).
const BTM_INQ_FILTER: usize = 0x803D_33AF;

/// `0x803D33B0`: six-byte address of the inquiry request.
const BTM_INQ_ADDR: usize = 0x803D_33B0;

/// `0x803D33B7`: number of results accepted in the current run.
///
/// `// observed:` the byte directly after [`BTM_INQ_EVENT_33B6`], bumped by the
/// result handler and compared with [`BTM_INQ_REQUEST_LIMIT`].
const BTM_INQ_EVENT_COUNT: usize = 0x803D_33B7;

/// `0x803D33B8` / `0x803D33BA`: two more words of the inquiry event block.
///
/// `// unknown:` the roles; [`fn_80205350`] forwards them as the `0x0403`
/// period pair and stores them nowhere else.
const BTM_INQ_EVENT_33B8: usize = 0x803D_33B8;
const BTM_INQ_EVENT_33BA: usize = 0x803D_33BA;

/// `0x803D33BC`: set while an event-filter command is outstanding.
const BTM_INQ_FILTER_DONE: usize = 0x803D_33BC;

/// `0x803D33BD`: cancel requests deferred until the filter command completes.
const BTM_INQ_DEFERRED_CANCEL: usize = 0x803D_33BD;

/// `0x803D33C4`: optional result filter `(address, data) -> bool`.
const BTM_INQ_FILTER_CB: usize = 0x803D_33C4;

/// `0x803D33C8`: optional "SCO connection accepted" callback.
const BTM_INQ_SCO_CB: usize = 0x803D_33C8;

/// `0x803D3230`: event-filter completion callback.
const BTM_INQ_FILTER_CALLBACK_3230: usize = 0x803D_3230;

/// `0x803D323C`: timer object cancelled by the inquiry teardown.
const BTM_INQ_TIMER_323C: usize = 0x803D_323C;

/// `r2 - 0x4C88` -> `0x8042E3F8` and `r2 - 0x4C84` -> `0x8042E3FC`: the two
/// three-byte inquiry access codes.
