/// at two entries. Each slot holds a callback word at `+0` and a flags byte at
/// `+4`; bit 0 marks "packet-type service", bit 1 "state-change service".
const SCO_SERVICE_TABLE: usize = 0x803D_20CC;
const SCO_SERVICE_STRIDE: usize = 0x0008;
const SCO_SERVICE_CALLBACK: usize = 0x0000;
const SCO_SERVICE_FLAGS: usize = 0x0004;
const SCO_SERVICE_COUNT: u32 = 2;

/// `0x803D20DC` / `0x803D20DD`: the slot and device indexes of the SCO
/// command currently being built; `4` means "none" (`0x80` for the device).
const SCO_ACTIVE_INDEX: usize = 0x803D_20DC;
const SCO_ACTIVE_SLOT: usize = 0x803D_20DD;

/// `0x803D20D8`: word cleared together with the first service slot.
