const CONN_SLOT_PENDING_CB: usize = 0x10;

/// `+0x1C`: first of the three `u16` link parameters (`+0x1C`, `+0x1E`,
/// `+0x22` as a byte).
const CONN_SLOT_PARAM_1C: usize = 0x1C;
const CONN_SLOT_DATA_22: usize = 0x22;

/// `+0x24..+0x30`: the seven-`u16` extended eSCO parameter block installed by
