    platform::write_u16(BTM_INQ_USED, 0);
    platform::write_u16(BTM_INQ_CAP, 0);
    platform::write_u16(BTM_MODE_STATE_A, 0);
    platform::write_u16(BTM_MODE_STATE_B, 0);
    platform::write_u16(BTM_MODE_CACHE_1, 0);
    platform::write_u16(BTM_MODE_CACHE_2, 0);
