/// Classifies one received RFCOMM frame and reports its type.
///
/// Decodes the address and control fields (including the optional second
/// address byte and second length byte), adjusts the packet's two length words,
/// checks the frame checksum and then decides which frame type the control byte
/// denotes. Each type has its own combination of role, length and DLCI tests;
/// a failed test logs the matching "Bad ..." line.
///
/// # Original
/// - Ghidra: `FUN_8021D8B4` at `0x8021D8B4` (1396 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8021d8b4_FUN_8021d8b4.c`
///
/// # Arguments
/// - `mcb`: multiplexer control block whose `+0x6D` role byte and `+0x72`
///   peer mode drive the tests.
/// - `out`: ten-byte decoded-frame record (`+0` DLCI, `+1` control, `+2`
///   command/response bit, `+4` P/F bit, `+5` optional payload byte).
/// - `packet`: received frame buffer.
///
/// # Returns
/// `0` SABME, `1` UI, `2` UA, `3` DISC, `4` UIH, `0x32` (50) for a malformed or
/// unknown frame.
///
/// # Safety
/// `packet` must hold a valid frame header, `out` must be ten writable bytes and
/// `mcb` a valid MCB.
///
/// # Confidence
/// medium - the decode, the length fix-up and every test are literal; the two
/// `r13` strings are known only by address.
pub unsafe fn fn_8021d8b4(mcb: usize, out: usize, packet: usize) -> u32 {
    let body = packet + platform::read_u16(packet + 4) as usize;
    let start = body + 8;

    if platform::read_u16(packet + 2) < 3 {
        if platform::read_u8(G_RFCOMM_TRACE_LEVEL) != 0 {
            platform::call3(
                LOG_2,
                0x0009_0000,
                S_RFC_BAD_LENGTH1,
                platform::read_u16(packet + 2) as u32,
            );
        }
        return 0x32;
    }

    let address = platform::read_u8(start);
    platform::write_u8(out + 2, (address & 2) >> 1);

    let mut cursor = start + 1;
    let mut dlci = address >> 2;
    platform::write_u8(out, dlci);
    if address & 1 == 0 {
        let low = platform::read_u8(cursor);
        cursor += 1;
        dlci = dlci.wrapping_add(low.wrapping_mul(0x40));
        platform::write_u8(out, dlci);
    }

    let control = platform::read_u8(cursor);
    platform::write_u8(out + 1, control & 0xEF);
    platform::write_u8(out + 4, (control & 0x10) >> 4);

    let length_lo = platform::read_u8(cursor + 1);
    let mut next = cursor + 2;
    let mut length = (length_lo >> 1) as u32;
    if length_lo & 1 == 0 {
        length += platform::read_u8(next) as u32 * 0x80;
        next += 1;
    }

    // observed: `countLeadingZeros(x) >> 5` is 1 when the extension bit is 0.
    let extra_bytes = (if address & 1 == 0 { 1u16 } else { 0 })
        + (if length_lo & 1 == 0 { 1u16 } else { 0 });
    platform::write_u16(
        packet + 2,
        platform::read_u16(packet + 2).wrapping_sub(extra_bytes + 4),
    );
    platform::write_u16(
        packet + 4,
        platform::read_u16(packet + 4).wrapping_add(extra_bytes + 3),
    );

    if platform::read_u8(mcb + RF_DLC_PEER_MODE) == 2
        && platform::read_u8(out + 1) == 0xEF
        && platform::read_u8(out) != 0
        && platform::read_u8(out + 4) == 1
    {
        platform::write_u8(out + 5, platform::read_u8(next));
        next += 1;
        platform::write_u16(packet + 2, platform::read_u16(packet + 2).wrapping_sub(1));
        platform::write_u16(packet + 4, platform::read_u16(packet + 4).wrapping_add(1));
    } else {
        platform::write_u8(out + 5, 0);
    }

    if platform::read_u16(packet + 2) != length as u16 {
        if platform::read_u8(G_RFCOMM_TRACE_LEVEL) != 0 {
            platform::call4(
                LOG_3,
                0x0009_0000,
                S_RFC_BAD_LENGTH2,
                platform::read_u16(packet + 2) as u32,
                length,
            );
        }
        return 0x32;
    }

    let fcs = platform::read_u8(next + length as usize);
    let dlci_now = platform::read_u8(out);
    let dlci_ok = dlci_now == 0 || (dlci_now > 1 && dlci_now < 0x3E);
    // observed: DISC/SABME test `(x == 0 || y == 0) && (x != 0 || y != 0)`, i.e.
    // "exactly one of the two bits is zero"; UA/UI test the opposite pair,
    // `(x == 0 || y != 0) && (x != 0 || y == 0)`, i.e. "both are equal".
    let role_diff = (platform::read_u8(mcb + RF_DLC_CHANNEL_FLAG) == 0)
        != (platform::read_u8(out + 2) == 0);
    let role_same = !role_diff;

    match platform::read_u8(out + 1) {
        0x43 => {
            if role_diff
                && platform::read_u8(out + 4) != 0
                && length == 0
                && dlci_ok
                && fn_8021e484(3, start, fcs as u32) != 0
            {
                3
            } else {
                if platform::read_u8(G_RFCOMM_TRACE_LEVEL) != 0 {
                    platform::call2(LOG_1, 0x0009_0000, S_RFC_BAD_DISC);
                }
                0x32
            }
        }
        0x2F => {
            if role_diff
                && platform::read_u8(out + 4) != 0
                && length == 0
                && dlci_ok
                && fn_8021e484(3, start, fcs as u32) != 0
            {
                0
            } else {
                if platform::read_u8(G_RFCOMM_TRACE_LEVEL) != 0 {
                    platform::call2(LOG_1, 0x0009_0000, S_RFC_BAD_SABME);
                }
                0x32
            }
        }
        0x0F => {
            if role_same
                && length == 0
                && dlci_ok
                && fn_8021e484(3, start, fcs as u32) != 0
            {
                2
            } else {
                if platform::read_u8(G_RFCOMM_TRACE_LEVEL) != 0 {
                    platform::call2(LOG_1, 0x0009_0000, S_R13_5D28);
                }
                0x32
            }
        }
        0xEF => {
            if dlci_now != 0 && (dlci_now < 2 || dlci_now > 0x3D) {
                if platform::read_u8(G_RFCOMM_TRACE_LEVEL) != 0 {
                    platform::call2(LOG_1, 0x0009_0000, S_RFC_BAD_UIH_DLCI);
                }
                return 0x32;
            }
            if fn_8021e484(2, start, fcs as u32) == 0 {
                if platform::read_u8(G_RFCOMM_TRACE_LEVEL) != 0 {
                    platform::call2(LOG_1, 0x0009_0000, S_RFC_BAD_UIH_FCS);
                }
                return 0x32;
            }
            if !role_diff && platform::read_u8(G_RFCOMM_TRACE_LEVEL) != 0 {
                platform::call2(LOG_1, 0x0009_0000, S_RFC_BAD_UIH_RESPONSE);
            }
            4
        }
        0x63 => {
            if role_same
                && platform::read_u8(out + 4) != 0
                && length == 0
                && dlci_ok
                && fn_8021e484(3, start, fcs as u32) != 0
            {
                1
            } else {
                if platform::read_u8(G_RFCOMM_TRACE_LEVEL) != 0 {
                    platform::call2(LOG_1, 0x0009_0000, S_R13_5D20);
                }
                0x32
            }
        }
        _ => 0x32,
    }
}

// ===========================================================================
// Wave 101 - SDP record attribute reader, 0x8021F5C0
// ===========================================================================

/// Copies up to `0x50` bytes of one SDP attribute value into a record field.
///
/// `// observed:` the export inlines this eight-bytes-at-a-time copy three
/// times; the byte loop below is the same copy without the unrolling.
///
/// # Safety
/// `record` must come from [`fn_8021fca8`]; `out + offset` must be writable for
/// `min(attribute length, 0x50)` bytes.
unsafe fn sdp_copy_blob(record: usize, attribute: u32, out: usize, offset: usize) {
    let entry = fn_8021fd04(record, attribute, attribute);
    if entry == 0 {
        return;
    }

    let declared = platform::read_u32(entry);
    let len = if declared < 0x50 { declared } else { 0x50 };
    let src = platform::read_u32(entry + 4) as usize;

    let mut index = 0u32;
    while index < len {
        platform::write_u8(
            out + offset + index as usize,
            platform::read_u8(src + index as usize),
        );
        index += 1;
    }
}

/// Fills a 0xFA-byte SDP service record from the database attributes.
///
/// Advances the caller's cursor to the next record (starting at
/// [`SDP_RECORD_LAST`] when it is zero), clears the output record, then copies
/// six `u16` attributes (`0x200`..`0x205`) into their fixed slots and three
/// byte strings (`0x0B`, `0x101`, `0x0A`) into the three 0x50-byte blobs at
/// `+0x0B`, `+0x5B` and `+0xAB`.
///
/// # Original
/// - Ghidra: `FUN_8021F5C0` at `0x8021F5C0` (1200 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8021f5c0_FUN_8021f5c0.c`
///
/// # Arguments
/// - `out`: 0xFA-byte output record.
/// - `cursor`: `u32` cursor advanced past the record that was read.
///
/// # Returns
/// `9` when no record was found, otherwise `0`.
///
/// # Side effects
/// Writes the output record and the cursor; no other globals change.
///
/// # Safety
/// `out` must be writable for 0xFA bytes and `cursor` for four.
///
/// # Confidence
/// high - every attribute id, slot and length cap is literal; only the copy
/// unrolling is rewritten as a loop.
pub unsafe fn fn_8021f5c0(out: usize, cursor: usize) -> u32 {
    if platform::read_u32(cursor) == 0 {
        platform::write_u32(cursor, platform::read_u32(SDP_RECORD_LAST));
    }

    let record = fn_8021fca8(platform::read_u32(cursor));
    if record == 0 {
        platform::write_u32(cursor, 0);
        return 9;
    }

    platform::call3(MEMSET_WRAPPER, out as u32, 0, 0xFA);

    let entry = fn_8021fd04(record, 0x200, 0x200);
    if entry != 0 {
        let src = platform::read_u32(entry + 4) as usize;
        platform::write_u16(
            out,
            (platform::read_u8(src) as u16) << 8 | platform::read_u8(src + 1) as u16,
        );
    }

    let entry = fn_8021fd04(record, 0x201, 0x201);
    if entry != 0 {
        let src = platform::read_u32(entry + 4) as usize;
        platform::write_u16(
            out + 2,
            (platform::read_u8(src) as u16) << 8 | platform::read_u8(src + 1) as u16,
        );
    }

    let entry = fn_8021fd04(record, 0x202, 0x202);
    if entry != 0 {
        let src = platform::read_u32(entry + 4) as usize;
        platform::write_u16(
            out + 6,
            (platform::read_u8(src) as u16) << 8 | platform::read_u8(src + 1) as u16,
        );
    }

    let entry = fn_8021fd04(record, 0x203, 0x203);
    if entry != 0 {
        let src = platform::read_u32(entry + 4) as usize;
        platform::write_u16(
            out + 8,
            (platform::read_u8(src) as u16) << 8 | platform::read_u8(src + 1) as u16,
        );
    }

    let entry = fn_8021fd04(record, 0x205, 0x205);
    if entry != 0 {
        let src = platform::read_u32(entry + 4) as usize;
        platform::write_u16(
            out + 4,
            (platform::read_u8(src) as u16) << 8 | platform::read_u8(src + 1) as u16,
        );
    }

    let entry = fn_8021fd04(record, 0x204, 0x204);
    if entry != 0 {
        let src = platform::read_u32(entry + 4) as usize;
        platform::write_u8(out + 0x0A, platform::read_u8(src));
    }

    sdp_copy_blob(record, 0x0B, out, 0x0B);
    sdp_copy_blob(record, 0x101, out, 0x5B);
    sdp_copy_blob(record, 0x0A, out, 0xAB);

    0
}

// ===========================================================================
// Wave 102 - SDP server responses, the EXI no-ops, the render callbacks and
// the text formatters - 0x80220524..0x8022EED0
//
// This pass fills seven holes the earlier `0x80220000` passes left:
//
// 1. the SDP attribute deleter `0x80220524` and the recursive attribute-tree
//    builder `0x80221440`,
// 2. the two ServiceSearch/ServiceAttribute response builders `0x80222698`
//    and `0x80222AA8`,
// 3. the two four-byte EXI no-ops `0x8022863C`/`0x80228640` and the three
//    `param_2 == 9`/`10` palette callbacks `0x802293B0..0x80229990`,
// 4. the GX default-state initialiser `0x8022C9C0`, the two aspect setters
//    `0x8022D2F0`/`0x8022D3C0` and the scroll advance `0x8022D5F0`,
// 5. the four varargs text wrappers `0x8022DFB0..0x8022F010`, the palette
//    append `0x8022EAF0` and the record printer `0x8022EED0`,
// 6. the 4-byte tail-call thunks `0x802260B0`, `0x80227800`, `0x80227A40`
//    and `0x8022B3C0..0x8022B3E0`.
//
// The SDP response builders share one continuation-state protocol: the
// request carries a 1-byte length plus that many continuation bytes, the CCB
// remembers the next record/attribute index in the `u16` at `+0x476`, and the
// response echoes the state at its tail. All three response bodies build the
// PDU in a class-`2` heap block (`0x801F7150`) and hand it to `0x80212F34`.
//
// `unaff_GQR0` appears in the render callbacks and in `0x8022D5F0`. It is the
// paired-single quantisation register: the `ldexpf` fragments Ghidra prints
// are the compiler's `psq_l`/`psq_st` conversions, and the payload scale is
// zero for plain `f32` data. The bodies use ordinary `f32` arithmetic and say
// so where the export only shows the artefact.
// ===========================================================================

// --- SDP record and response constants -------------------------------------

/// `u16` continuation index inside a service record (`+0x476`).
///
/// `// observed:` compared with the continuation state of an incoming
/// ServiceSearch/ServiceAttribute request and advanced by the number of
/// records/attributes already answered.
const SDP_CCB_CONTINUATION: usize = 0x476;

/// `u16` used bytes of the value area (`record + 4`).
const SDP_RECORD_VALUE_USED: usize = 0x04;

/// First attribute descriptor inside a service record (`record + 0x0C`).
///
/// A descriptor is `{ u32 length, u32 value, u16 id, u8 type }` so the value
/// pointer sits at `+0x10` and the id at `+0x14`.
const SDP_RECORD_FIRST_ATTR: usize = 0x0C;

/// Start of the record's value area (`0x138` bytes; the used size is at `+4`).
const SDP_RECORD_VALUE_AREA: usize = 0x138;

/// `u16` maximum record/attribute index a response may cover.
const SDP_MAX_RECORDS: u32 = 0x14;

/// `0x8034C5A0`: "Deleting attr id 0x%04x for hand...".
const S_SDP_DELETING_ATTRIBUTE: u32 = 0x8034_C5A0;

/// `0x8034C6A0`: "SDP - attr nesting too deep".
const S_SDP_ATTR_NESTING: u32 = 0x8034_C6A0;

/// `0x8034C6BC`: "SDP - bad len in UUID attr - %d".
const S_SDP_BAD_LEN_UUID: u32 = 0x8034_C6BC;

/// `0x8034C6DC`: "SDP - bad len in boolean attr - %d".
const S_SDP_BAD_LEN_BOOLEAN: u32 = 0x8034_C6DC;

/// `0x8034CAAC`: "SDP - no buf for search rsp".
const S_SDP_NO_SEARCH_BUFFER: u32 = 0x8034_CAAC;

/// Largest attribute nesting depth the request decoder accepts (`4`).
const SDP_MAX_DEPTH: u32 = 4;

/// `u16` big-endian read used by the response builders.
///
/// # Safety
/// `addr` must be readable for two bytes.
unsafe fn sdp_read_be16(addr: usize) -> u16 {
    ((platform::read_u8(addr) as u16) << 8) | platform::read_u8(addr + 1) as u16
}

/// `u32` big-endian read used by the response builders.
///
/// # Safety
/// `addr` must be readable for four bytes.
unsafe fn sdp_read_be32(addr: usize) -> u32 {
    ((platform::read_u8(addr) as u32) << 24)
        | ((platform::read_u8(addr + 1) as u32) << 16)
        | ((platform::read_u8(addr + 2) as u32) << 8)
        | platform::read_u8(addr + 3) as u32
}

/// Byte copy used where the export has an unrolled loop.
///
/// # Safety
/// `dst` must be writable for `count` bytes and `src` readable for `count`.
unsafe fn sdp_copy_bytes(dst: usize, src: usize, count: u32) {
    let mut i = 0u32;
    while i < count {
        platform::write_u8(dst + i as usize, platform::read_u8(src + i as usize));
        i += 1;
    }
}

/// Stores an unsigned/signed integer payload into a node.
///
/// Mirrors the shared `caseD_2` block of [`fn_80221440`]: one byte at `+8` for
/// a length of `1`, a big-endian `u16` for `2`, a big-endian `u32` for `4`,
/// and a byte copy for `0`, `3` and every length above `4`.
///
/// # Safety
/// `node + 8` must be writable for `length` bytes and `payload` readable for
/// `length` bytes.
unsafe fn sdp_store_integer(node: usize, payload: usize, length: u32) {
    match length {
        0 => {}
        1 => platform::write_u8(node + 8, platform::read_u8(payload)),
        2 => platform::write_u16(node + 8, sdp_read_be16(payload)),
        4 => platform::write_u32(node + 8, sdp_read_be32(payload)),
        _ => sdp_copy_bytes(node + 8, payload, length),
    }
}

/// Removes one attribute from a service record and compacts its value area.
///
/// Walks the live service records (`0x803D6A64`, stride `0x298`) until the
/// record with `handle` is found, then scans its `0x0C`-byte attribute
/// descriptors. The matching descriptor is dropped, every following descriptor
/// is shifted down one slot, and every value pointer that points above the
/// removed value moves down by the removed length. The remaining bytes of the
/// value area are then copied down over the hole.
///
/// # Original
/// - Ghidra: `FUN_80220524` at `0x80220524` (572 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80220524_FUN_80220524.c`
///
/// # Arguments
/// - `handle`: service record handle (`r3`).
/// - `attribute`: `u16` attribute id to delete (`r4`).
///
/// # Returns
/// `1` when the attribute was removed, `0` when the handle or the id is absent.
///
/// # Side effects
/// Shifts descriptors, rewrites value pointers, decrements the record's
/// attribute count, moves the value area and may log at trace level `3`.
///
/// # Safety
/// The record table must hold the number of records the count at
/// `0x803D6A62` claims, and every value pointer must address the record's own
/// value area.
///
/// # Confidence
/// medium - the walk, the shift and the pointer fix-up are literal; the
/// decompiler prints the payload move as an unrolled eight-byte loop whose
/// source and destination are `value + length`/`value`, translated here as the
/// memmove it implements, and the 16-bit subtraction in the copy length is
/// reproduced with a wrapping cast. The export also reuses its `u16` attribute
/// counter as the record index after a record misses the attribute; the body
/// keeps the two counters separate, which is the only loop shape consistent
/// with the table walk.
pub unsafe fn fn_80220524(handle: u32, attribute: u32) -> u32 {
    let record_count = platform::read_u8(SDP_RECORD_COUNT) as u32;
    let mut index = 0u32;

    while index < record_count {
        let record = SDP_RECORD_TABLE + index as usize * SDP_RECORD_LEN;
        if platform::read_u32(record) != handle {
            index += 1;
            continue;
        }

        if platform::read_u8(SDP_TRACE_LEVEL) > 2 {
            platform::call4(LOG_3, 0x000A_0002, S_SDP_DELETING_ATTRIBUTE, attribute, handle);
        }

        let count = platform::read_u16(record + SDP_RECORD_ATTR_COUNT) as usize;
        let mut slot = 0usize;
        while slot < count {
            let entry = record + SDP_RECORD_FIRST_ATTR + slot * SDP_RECORD_ATTR_STRIDE;
            if platform::read_u16(entry + 8) as u32 == attribute {
                let length = platform::read_u32(entry) as usize;
                let value = platform::read_u32(entry + 4) as usize;

                // observed: every value above the removed one moves down.
                if length != 0 {
                    let mut other = 0usize;
                    while other < count {
                        let field = record
                            + SDP_RECORD_FIRST_ATTR
                            + other * SDP_RECORD_ATTR_STRIDE
                            + 4;
                        let pointer = platform::read_u32(field) as usize;
                        if value < pointer {
                            platform::write_u32(field, pointer.wrapping_sub(length) as u32);
                        }
                        other += 1;
                    }
                }

                // observed: three words per descriptor, copied forward.
                let mut move_slot = slot;
                while move_slot + 1 < count {
                    let dst = record + SDP_RECORD_FIRST_ATTR + move_slot * SDP_RECORD_ATTR_STRIDE;
                    let src = dst + SDP_RECORD_ATTR_STRIDE;
                    platform::write_u32(dst, platform::read_u32(src));
                    platform::write_u32(dst + 4, platform::read_u32(src + 4));
                    platform::write_u32(dst + 8, platform::read_u32(src + 8));
                    move_slot += 1;
                }
                platform::write_u16(record + SDP_RECORD_ATTR_COUNT, (count - 1) as u16);

                if length != 0 {
                    // observed: `(used - (src - area)) & 0xffff`, i.e. the bytes
                    // left in the value area behind the removed value.
                    let area = record + SDP_RECORD_VALUE_AREA;
                    let used = platform::read_u32(record + SDP_RECORD_VALUE_USED);
                    let tail = (value + length).wrapping_sub(area) as u32;
                    let copy_len = used.wrapping_sub(tail) as u16 as u32;
                    if copy_len != 0 {
                        platform::call3(
                            MEMCPY,
                            value as u32,
                            (value + length) as u32,
                            copy_len,
                        );
                    }
                    platform::write_u32(
                        record + SDP_RECORD_VALUE_USED,
                        used.wrapping_sub(length as u32),
                    );
                }

                return 1;
            }
            slot += 1;
        }

        index += 1;
    }

    0
}

/// Decodes one request element into the in-memory attribute tree.
///
/// `value` points at a request data element. The header byte's low three bits
/// select the payload width ([`fn_80223d90`]); the high bits are the element
/// type. A `0x0C`-byte node is taken from the database's node area at
/// `database + 0x68`, its free-space counter at `+4` is charged, and the value
/// is decoded into the node:
///
/// - `+0` next sibling, `+4` caller tag, `+6` `(type << 12) | length`;
/// - `+8` the inline value (integers/booleans) or the copied bytes
///   (`0x10` = UUID, `0x20` = text/URL);
/// - sequences of type `6`/`7` store their first child pointer at `+8` and
///   recurse until the payload is consumed.
///
/// The finished node is appended to `record[0]` when `parent` is `0`, otherwise
/// to `parent[2]` (the container's child list).
///
/// # Original
/// - Ghidra: `FUN_80221440` at `0x80221440` (1424 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80221440_FUN_80221440.c`
///
/// # Arguments
/// - `value`: first byte of the element.
/// - `database`: SDP database object; `+4` is free space and `+0x68` the node
///   cursor.
/// - `record`: service record receiving the tree (`record[0]` = root list).
/// - `tag`: value stored in the node's `+4` word; the caller passes the
///   attribute id, the recursive calls pass `4` or `0`.
/// - `parent`: container node receiving a child, or `0` for the root list.
/// - `depth`: current nesting depth; `bit 7` is a caller flag
///   (`// inferred:` "value came from the continuation buffer").
///
/// # Returns
/// The cursor after the element, or `0` when the database is full, a value is
/// malformed or the node area is exhausted.
///
/// # Side effects
/// Charges `database + 4`, advances `database + 0x68`, writes the node and links
/// it into the record, and may log at trace level `2`/`3`.
///
/// # Safety
/// `value` must be readable for its declared length; `database` and `record`
/// must be live, and the node area must have room for the node and its
/// children.
///
/// # Confidence
/// medium - every type case, width and store is literal; the tree roles
/// (`+4` tag, `parent[2]` child list) are read from the two linking paths and
/// the top-level caller `fn_802211b4`, which passes the attribute id as `tag`.
pub unsafe fn fn_80221440(
    value: usize,
    database: usize,
    record: usize,
    tag: u32,
    parent: usize,
    depth: u32,
) -> usize {
    let header = platform::read_u8(value);
    let mut payload_len = crate::platform::GuestLocal::<u32>::new( 0);
    let payload = fn_80223d90(value + 1, header as u32, (payload_len.as_mut_ptr() as *mut u32) as usize) as usize;
    *payload_len &= 0xFFF;
    let kind = (header >> 3) as u32;

    let mut node_size = 0x0Cu32;
    if *payload_len > 4 {
        node_size = *payload_len + 8;
    }
    node_size = (node_size + 3) & !3;

    if platform::read_u32(database + 4) < node_size {
        return 0;
    }

    let node = platform::read_u32(database + 0x68) as usize;
    platform::write_u32(node, 0);
    platform::write_u16(node + 4, tag as u16);
    platform::write_u16(node + 6, (*payload_len | (kind << 12)) as u16);

    let value_end = payload + *payload_len as usize;
    let mut result = 0usize;
    let mut advance = node_size;

    match kind & 0xF {
        // unsigned integer
        1 => {
            let continuation_ok = (depth & 0x80) != 0
                && *payload_len == 2
                && (platform::read_u8(payload) as u32) * 0x100
                    + platform::read_u8(payload + 1) as u32
                    == 4;
            if !continuation_ok {
                sdp_store_integer(node, payload, *payload_len);
            } else {
                // observed: the "value 4" form is a nested element: the 0x0C
                // header is charged here and the child starts two bytes in.
                advance = 0;
                platform::write_u32(
                    database + 0x68,
                    (platform::read_u32(database + 0x68)).wrapping_add(0x0C),
                );
                platform::write_u32(database + 4, platform::read_u32(database + 4) - 0x0C);
                result = payload + 4;
                if (depth & 0x7F) > SDP_MAX_DEPTH {
                    if platform::read_u8(SDP_TRACE_LEVEL) != 0 {
                        platform::call2(LOG_1, 0x000A_0000, S_SDP_ATTR_NESTING);
                    }
                    return result;
                }
                result = fn_80221440(
                    payload + 2,
                    database,
                    record,
                    4,
                    node,
                    (depth & 0x7F) + 1,
                );
            }
        }
        // signed integer
        2 => {
            sdp_store_integer(node, payload, *payload_len);
        }
        // UUID
        3 => {
            if *payload_len == 4 {
                let short = sdp_read_be32(payload);
                platform::write_u32(node + 8, short);
                if short < 0x1_0000 {
                    platform::write_u16(node + 6, (kind << 12) as u16 | 2);
                    platform::write_u16(node + 8, short as u16);
                }
            } else if *payload_len == 2 {
                platform::write_u16(node + 8, sdp_read_be16(payload));
            } else if *payload_len == 0x10 {
                if fn_80223e60(payload) == 0 {
                    sdp_copy_bytes(node + 8, payload, 0x10);
                } else if platform::read_u8(payload) == 0
                    && platform::read_u8(payload + 1) == 0
                {
                    let at = node + 6;
                    let old = platform::read_u16(at);
                    platform::write_u16(at, (old & 0xF000) | 2);
                    platform::write_u16(node + 8, sdp_read_be16(payload + 2));
                } else {
                    let at = node + 6;
                    let old = platform::read_u16(at);
                    platform::write_u16(at, (old & 0xF000) | 4);
                    platform::write_u32(node + 8, sdp_read_be32(payload));
                }
            } else {
                if platform::read_u8(SDP_TRACE_LEVEL) > 1 {
                    platform::call3(
                        LOG_2,
                        0x000A_0001,
                        S_SDP_BAD_LEN_UUID,
                        *payload_len,
                    );
                }
                return payload + *payload_len as usize;
            }
        }
        // text (0x20) and URL (0x40)
        4 | 8 => {
            sdp_copy_bytes(node + 8, payload, *payload_len);
        }
        // boolean
        5 => {
            if *payload_len != 1 {
                if platform::read_u8(SDP_TRACE_LEVEL) > 1 {
                    platform::call3(
                        LOG_2,
                        0x000A_0001,
                        S_SDP_BAD_LEN_BOOLEAN,
                        *payload_len,
                    );
                }
                return payload + *payload_len as usize;
            }
            platform::write_u8(node + 8, platform::read_u8(payload));
        }
        // sequences of type 6 and 7
        6 | 7 => {
            advance = 0;
            platform::write_u32(
                database + 0x68,
                (platform::read_u32(database + 0x68)).wrapping_add(0x0C),
            );
            platform::write_u32(database + 4, platform::read_u32(database + 4) - 0x0C);
            if (depth & 0x7F) < 5 {
                let mut flags = depth;
                if (depth & 0x80) != 0 || tag == 0xD {
                    flags |= 0x80;
                }
                let mut child = payload;
                while child < value_end {
                    let next = fn_80221440(child, database, record, 0, node, (flags + 1) & 0xFF);
                    if next == 0 {
                        break;
                    }
                    child = next;
                }
                result = child;
            } else if platform::read_u8(SDP_TRACE_LEVEL) != 0 {
                platform::call2(LOG_1, 0x000A_0000, S_SDP_ATTR_NESTING);
                return value_end;
            }
        }
        _ => {}
    }

    platform::write_u32(
        database + 0x68,
        (platform::read_u32(database + 0x68)).wrapping_add(advance),
    );
    platform::write_u32(database + 4, platform::read_u32(database + 4) - advance);

    if parent == 0 {
        let mut link = platform::read_u32(record) as usize;
        if link == 0 {
            platform::write_u32(record, node as u32);
        } else {
            loop {
                let next = platform::read_u32(link) as usize;
                if next == 0 {
                    break;
                }
                link = next;
            }
            platform::write_u32(link, node as u32);
        }
    } else {
        let mut link = platform::read_u32(parent + 8) as usize;
        if link == 0 {
            platform::write_u32(parent + 8, node as u32);
        } else {
            loop {
                let next = platform::read_u32(link) as usize;
                if next == 0 {
                    break;
                }
                link = next;
            }
            platform::write_u32(link, node as u32);
        }
    }

    result
}

/// Builds and sends a ServiceSearchResponse for the UUID pattern in a request.
///
/// The request body is a `0x36`-class UUID sequence followed by the maximum
/// service-record count (`u16`) and a continuation state (`u8` length plus that
/// many bytes). [`fn_802237f0`] fills the local 16-entry pattern table, the
/// matching records are collected through [`fn_8021fa94`], and their handles
/// are written into a class-`2` heap block:
///
/// ```text
/// +0x11 PDU id 3        +0x16 total record count (u16)
/// +0x12 transaction     +0x18 records in this PDU (u16)
/// +0x14 parameter len   +0x1A one big-endian u32 handle per record
/// ```
///
/// The packet ends with the continuation state: `0` when every record fits,
/// otherwise `2` plus the `u16` index of the next record.
///
/// # Original
/// - Ghidra: `FUN_80222698` at `0x80222698` (1040 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80222698_FUN_80222698.c`
///
/// # Arguments
/// - `ccb`: SDP connection block (the high half of the `0x802DCD40` fold).
/// - `transaction`: request transaction id (the low half).
/// - `request_size`: bytes available at `request`.
/// - `request`: first byte of the request body.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Allocates and sends one PDU, advances [`SDP_CCB_CONTINUATION`] when the
/// answer is split, and may log an error or a no-buffer line.
///
/// # Safety
/// `request..request + request_size` must be readable; `ccb` must be a live
/// CCB with its receive buffer and channel id initialised.
///
/// # Confidence
/// medium - every field and length is literal; the `0x802DCD40` prologue folds
/// `r3`/`r4` into its fake result, so `ccb` and `transaction` are recovered
/// from use (the same convention as `fn_8022d5c0`).
pub unsafe fn fn_80222698(ccb: usize, transaction: u16, request_size: u32, request: usize) {
    let mut pattern = crate::platform::GuestLocal::new( [0u16; 146]);

    let cursor = fn_802237f0(request, request_size, pattern.as_mut_ptr() as usize) as usize;
    if cursor == 0 || pattern[0] == 0 {
        fn_802236b4(ccb, transaction, 3, 0);
        return;
    }

    let mut max = sdp_read_be16(cursor) as u32;
    if max > SDP_MAX_RECORDS {
        max = SDP_MAX_RECORDS;
    }

    let mut handles = [0u32; 0x14];
    let mut found = 0u32;
    let mut record = 0usize;
    while found < max {
        record = fn_8021fa94(record, pattern.as_mut_ptr() as usize);
        if record == 0 {
            break;
        }
        handles[found as usize] = platform::read_u32(record);
        found += 1;
    }

    let mut start = 0u32;
    let mut count = found;
    if platform::read_u8(cursor + 2) != 0 {
        if platform::read_u8(cursor + 2) != 2
            || sdp_read_be16(cursor + 3) as u32
                != platform::read_u16(ccb + SDP_CCB_CONTINUATION) as u32
        {
            fn_802236b4(ccb, transaction, 5, 0);
            return;
        }
        start = sdp_read_be16(cursor + 3) as u32;
        count = found.wrapping_sub(start) & 0xFFFF;
    }

    // observed: `(MTU - 12) / 4` records fit in one PDU.
    let space = platform::read_u16(ccb + SDP_CCB_MTU) as i32 - 0x0C;
    let mut slots = space >> 2;
    if space < 0 && (space & 3) != 0 {
        slots += 1;
    }
    let slots = slots as u32 & 0xFFFF;

    let mut more = false;
    if slots < count {
        more = true;
        let at = ccb + SDP_CCB_CONTINUATION;
        let next = platform::read_u16(at).wrapping_add(slots as u16);
        platform::write_u16(at, next);
        count = slots;
    }

    let packet = platform::call1(HEAP_ALLOC, 2) as usize;
    if packet == 0 {
        if platform::read_u8(SDP_TRACE_LEVEL) != 0 {
            platform::call2(LOG_1, 0x000A_0000, S_SDP_NO_SEARCH_BUFFER);
        }
        return;
    }

    platform::write_u16(packet + 4, 9);
    platform::write_u8(packet + 0x11, 3);
    platform::write_u8(packet + 0x12, (transaction >> 8) as u8);
    platform::write_u8(packet + 0x13, transaction as u8);
    platform::write_u8(packet + 0x16, (found >> 8) as u8);
    platform::write_u8(packet + 0x17, found as u8);
    platform::write_u8(packet + 0x18, (count >> 8) as u8);
    platform::write_u8(packet + 0x19, count as u8);

    let mut out = packet + 0x1A;
    let last = start + count;
    let mut index = start;
    while index < last {
        let handle = handles[index as usize];
        platform::write_u8(out, (handle >> 24) as u8);
        platform::write_u8(out + 1, (handle >> 16) as u8);
        platform::write_u8(out + 2, (handle >> 8) as u8);
        platform::write_u8(out + 3, handle as u8);
        out += 4;
        index += 1;
    }

    if more {
        platform::write_u8(out, 2);
        let next = platform::read_u16(ccb + SDP_CCB_CONTINUATION);
        platform::write_u8(out + 1, (next >> 8) as u8);
        platform::write_u8(out + 2, next as u8);
        out += 3;
    } else {
        platform::write_u8(out, 0);
        out += 1;
    }

    // observed: `parameter length = cursor - 2 - (packet + 0x14)`.
    let body_len = out - 2 - (packet + 0x14);
    platform::write_u8(packet + 0x14, (body_len >> 8) as u8);
    platform::write_u8(packet + 0x15, body_len as u8);
    platform::write_u16(packet + 2, (out - (packet + 0x11)) as u16);
    platform::call2(
        L2CAP_DATA_WRITE,
        platform::read_u16(ccb + SDP_CCB_CID) as u32,
        packet as u32,
    );
}

/// Builds and sends a ServiceAttributeResponse from a service record.
///
/// The request body is a big-endian record handle, the maximum attribute byte
/// count (`u16`), the attribute-id sequence and a continuation state. The ids
/// are decoded by [`fn_80223b40`], the matching record is found with
/// [`fn_8021fca8`], and each requested attribute is found with
/// [`fn_8021fd04`] and appended to the CCB reassembly buffer with
/// [`fn_80223560`]. The finished sequence is copied into a class-`2` block with
/// PDU id `5` and sent.
///
/// The rebuilt sequence lives at `ccb + 0x27` (short header, `0x35`) or
/// `ccb + 0x26` (long header, `0x36`); [`SDP_CCB_CONTINUATION`] holds the
/// offset of the header inside that buffer and [`SDP_CCB_RX_LEN`] the number of
/// bytes still to send.
///
/// # Original
/// - Ghidra: `FUN_80222AA8` at `0x80222AA8` (912 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80222aa8_FUN_80222aa8.c`
///
/// # Arguments
/// - `ccb`: SDP connection block (the high half of the `0x802DCD68` fold).
/// - `transaction`: request transaction id (the low half).
/// - `request_size`: bytes available at `request`.
/// - `request`: first byte of the request body.
/// - `request_end`: one past the last request byte.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Fills `ccb + 0x26..`, allocates and sends one PDU, and may log errors.
///
/// # Safety
/// `request..request_end` must be readable; `ccb` must be a live CCB.
///
/// # Confidence
/// medium - the id loop, the sequence-header choice and every store are
/// literal; the `0x802DCD68` fold is split as in `fn_802236b4`.
pub unsafe fn fn_80222aa8(
    ccb: usize,
    transaction: u16,
    request_size: u32,
    request: usize,
    request_end: usize,
) {
    if request_end < request + 4 {
        fn_802236b4(ccb, transaction, 2, 0);
        return;
    }

    let handle = sdp_read_be32(request);
    let mut max = sdp_read_be16(request + 4) as u32;
    let space = platform::read_u16(ccb + SDP_CCB_MTU) as i32 - 10;
    if space < max as i32 {
        max = space as u32 & 0xFFFF;
    }

    let mut ids = crate::platform::GuestLocal::new( [0u16; 0x40]);
    let cursor = fn_80223b40(request + 6, request_size, ids.as_mut_ptr() as usize) as usize;
    if cursor == 0 || ids[0] == 0 || request_end < cursor {
        fn_802236b4(ccb, transaction, 3, 0);
        return;
    }

    let record = fn_8021fca8(handle);
    if record == 0 {
        fn_802236b4(ccb, transaction, 2, 0);
        return;
    }

    if platform::read_u8(cursor) != 0 {
        if platform::read_u8(cursor) != 2
            || sdp_read_be16(cursor + 1) as u32
                != platform::read_u16(ccb + SDP_CCB_CONTINUATION) as u32
        {
            fn_802236b4(ccb, transaction, 5, 0);
            return;
        }
    } else {
        // observed: build the attribute list at `ccb + 0x29`.
        let mut out = ccb + 0x29;
        platform::write_u16(ccb + SDP_CCB_CONTINUATION, 0);
        let mut slot = 0u32;
        while slot < ids[0] as u32 {
            let lo = ids[1 + slot as usize * 2];
            let hi = ids[2 + slot as usize * 2];
            let entry = fn_8021fd04(record, lo as u32, hi as u32);
            if entry != 0 {
                let used = (out - (ccb + SDP_CCB_RX_BUFFER)) as u32 & 0xFFFF;
                if 1000u32.wrapping_sub(used).wrapping_sub(6) < platform::read_u32(entry) {
                    break;
                }
                out = fn_80223560(out, entry);
                if lo != hi {
                    ids[1 + slot as usize * 2] =
                        platform::read_u16(entry + 8).wrapping_add(1);
                    continue;
                }
            }
            slot += 1;
        }

        let written = out - (ccb + SDP_CCB_RX_BUFFER);
        platform::write_u16(ccb + SDP_CCB_RX_LEN, written as u16);
        if written < 0x100 {
            platform::write_u16(ccb + SDP_CCB_CONTINUATION, 1);
            platform::write_u8(ccb + 0x27, 0x35);
            platform::write_u8(ccb + 0x28, written.wrapping_sub(3) as u8);
            platform::write_u16(ccb + SDP_CCB_RX_LEN, written.wrapping_sub(1) as u16);
        } else {
            platform::write_u8(ccb + 0x26, 0x36);
            platform::write_u8(ccb + 0x27, (written.wrapping_sub(3) >> 8) as u8);
            platform::write_u8(ccb + 0x28, written.wrapping_sub(3) as u8);
        }
    }

    let packet = platform::call1(HEAP_ALLOC, 2) as usize;
    if packet == 0 {
        if platform::read_u8(SDP_TRACE_LEVEL) != 0 {
            platform::call2(LOG_1, 0x000A_0000, S_SDP_NO_SEARCH_BUFFER);
        }
        return;
    }

    platform::write_u16(packet + 4, 9);
    platform::write_u8(packet + 0x11, 5);
    platform::write_u8(packet + 0x12, (transaction >> 8) as u8);
    platform::write_u8(packet + 0x13, transaction as u8);

    let remaining = platform::read_u16(ccb + SDP_CCB_RX_LEN) as u32;
    if remaining <= max {
        max = remaining;
    }
    platform::write_u8(packet + 0x16, (max >> 8) as u8);
    platform::write_u8(packet + 0x17, max as u8);

    let offset = platform::read_u16(ccb + SDP_CCB_CONTINUATION) as usize;
    platform::call3(
        MEMCPY,
        (packet + 0x18) as u32,
        (ccb + SDP_CCB_RX_BUFFER + offset) as u32,
        max,
    );

    let mut out = packet + 0x18 + max as usize;
    let left = remaining.wrapping_sub(max);
    platform::write_u16(ccb + SDP_CCB_RX_LEN, left as u16);
    let at = ccb + SDP_CCB_CONTINUATION;
    platform::write_u16(at, platform::read_u16(at).wrapping_add(max as u16));
    if left == 0 {
        platform::write_u8(out, 0);
        out += 1;
    } else {
        platform::write_u8(out, 2);
        let next = platform::read_u16(at);
        platform::write_u8(out + 1, (next >> 8) as u8);
        platform::write_u8(out + 2, next as u8);
        out += 3;
    }

    let body_len = out - 2 - (packet + 0x14);
    platform::write_u8(packet + 0x14, (body_len >> 8) as u8);
    platform::write_u8(packet + 0x15, body_len as u8);
    platform::write_u16(packet + 2, (out - (packet + 0x11)) as u16);
    platform::call2(
        L2CAP_DATA_WRITE,
        platform::read_u16(ccb + SDP_CCB_CID) as u32,
        packet as u32,
    );
}

