/// [`platform::call1`] only returns a `u32`, so the palette code uses this
/// typed wrapper for `0x802308D0`.
///
/// # Safety
/// `addr` must point to a function with this ABI.
unsafe fn call_f64_1(addr: usize, arg: u32) -> f64 {
    let func = crate::platform::guest_fn!(addr, fn(u32) -> f64);
    func(arg)
}

/// Calls a routine taking three `double`s, one integer and one pointer.
