/// `addr` must point to a function with this ABI.
unsafe fn call_f64x3_two(addr: usize, a: f64, b: f64, c: f64, d: u32, e: usize) {
    let func = crate::platform::guest_fn!(addr, fn(f64, f64, f64, u32, usize));
    func(a, b, c, d, e);
}

/// Advances a palette object's vertical cursor for event kinds `9` and `10`.
///
/// Kind `10` sets `+0x2C` to the caller's offset and moves `+0x30` down by
/// [`fn_8022df30`]'s step, returning `3`. Kind `9` snaps `+0x2C` up to the
/// next multiple of the line step (`+0x58` cells times the row height) and
/// returns `1`. Any other kind returns `0` without touching the object.
///
/// # Original
/// - Ghidra: `FUN_802293B0` at `0x802293B0` (300 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802293b0_FUN_802293b0.c`
///
/// # Arguments
/// - `_unused`: first argument; the export never reads it (`r3`).
/// - `kind`: event kind (`9` or `10`).
/// - `context`: two-word context; `context[0]` is the object pointer and
///   `context[2]` the integer pixel offset.
///
/// # Returns
/// `3` for kind `10`, `1` for kind `9`, `0` otherwise.
///
/// # Side effects
/// Writes the object's `+0x2C`/`+0x30` cursor fields.
///
/// # Safety
/// `context` must be readable for three words and `context[0]` must address a
/// live palette object.
///
/// # Confidence
/// medium - the two cases and the cursor arithmetic are literal; the field
/// roles are the ones [`fn_8022d440`] and [`fn_8022df30`] already established
/// for the same object, and the GQR0 fragments are the compiler's paired
/// conversions.
pub unsafe fn fn_802293b0(_unused: u32, kind: i32, context: usize) -> u32 {
    match kind {
        10 => {
            let object = platform::read_u32(context) as usize;
            let offset = platform::read_i32(context + 8) as f32;
            let y = platform::read_f32(object + 0x30);
            let step = fn_8022df30(object);
            platform::write_f32(object + 0x2C, offset);
            platform::write_f32(object + 0x30, (y as f64 + step) as f32);
            3
        }
        9 => {
            let object = platform::read_u32(context) as usize;
            let count = platform::read_u32(object + 0x58) as i32;
            if count > 0 {
                let step = if platform::read_u8(object + 0x43) == 0 {
                    fn_8022d440(object) as f32
                } else {
                    platform::read_f32(object + 0x44)
                };
                let unit = count as f32 * step;
                let offset = platform::read_i32(context + 8) as f32;
                let current = platform::read_f32(object + 0x2C);
                let steps = (current - offset) / unit;
                let next = (steps as i32 as u32).wrapping_add(1) as f32;
                platform::write_f32(object + 0x2C, offset + unit * next);
            }
            1
        }
        _ => 0,
    }
}

