/// `0x8042AB98` (`r13 - 0x4AE8`): `bta_hh` trace level, the byte stored by
/// `0x801FA908`.
///
/// `// observed:` `4 < *(byte *)(unaff_r13 + -0x4ae8)` guards every trace line
/// in the `0x801FA...` HID-host code and in `80200080_FUN_80200080.c` /
/// `80200190_FUN_80200190.c`.
const BTA_HH_LOG_LEVEL: usize = 0x8042_AB98;

/// `0x801F6FB0`: oldest-first buffer allocator used by the HID host.
///
/// `// unknown:` the export prints no argument list; the returned block is the
/// destination of the descriptor copy, so it is treated as a one-argument
/// allocator whose argument register is not recoverable.
const HID_ALLOC_801F6FB0: usize = 0x801F_6FB0;

/// `0x801FAAF0`: releases the heap block whose *word address* is passed.
const HEAP_BLOCK_RELEASE: usize = 0x801F_AAF0;

/// `0x801F8020`: monotonic millisecond stamp stored in an inquiry record.
const TIMESTAMP_801F8020: usize = 0x801F_8020;

/// `0x80348004`: "s_subclass: %0x %2x".
const S_HID_SUBCLASS: u32 = 0x8034_8004;

/// `0x80348164`: "bta_hh_trace_dev_db - Device DB l...".
const S_HID_DEV_DB: u32 = 0x8034_8164;

/// `0x803481A0`: "kdev: %d in_use %d handle %d".
const S_HID_KDEV: u32 = 0x8034_81A0;

/// `0x803481C4`: "attr_mask 0x%04x  state  %d  sub_c...".
const S_HID_ATTR_MASK: u32 = 0x8034_81C4;

/// `0x80348200`: the dashed separator printed by the device-database dump.
const S_HID_SEPARATOR: u32 = 0x8034_8200;

/// `0x8042E3F8` / `0x8042E3FC`: the general and limited inquiry access codes.
///
/// `// observed:` `8020413c_FUN_8020413c.c` copies them into the two-LAP
/// `0x0C3A` command when `mode` bit 0 is set. Named by wave 99 for the inquiry
/// builders ([`BTM_INQ_LAP_GENERAL`]); reused here.
const BTM_IAC_GENERAL: usize = 0x8042_E3F8;
const BTM_IAC_LIMITED: usize = 0x8042_E3FC;

/// Forms one inquiry record and stores the caller's descriptor copy.
///
/// The record is the `bta_hh` device entry: `+0` a `u16` copied from the
/// descriptor header, `+4` the variable-length descriptor block, `+0x0E` the
/// caller's handle, `+0x13` and `+0x15` two caller bytes, `+0x16` the caller's
/// "kind" byte and `+0x18` a constant `1`.
///
/// When a descriptor is supplied the previous block at `+4` is released first,
/// then a new block is allocated and the `{u16 length, u16 pad, u32 source}`
/// header is copied: the length goes to `+0` and `length` bytes from `+4` of
/// the header go to the new block.
///
/// # Original
/// - Ghidra: `FUN_80200080` at `0x80200080` (188 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80200080_FUN_80200080.c`
///
/// # Arguments
/// - `record`: device record (`r3`, recovered from the `0x802DCD70` fold).
/// - `kind`: byte stored at `+0x16` (`r4`, the fold's `extraout_r4`).
/// - `handle`: `u16` stored at `+0x0E` (`r5`).
/// - `descriptor`: optional `{u16 length, u16 pad, u32 source}` header (`r6`);
///   `0` leaves the existing block untouched.
/// - `log_value`: byte stored at `+0x13` and printed by the trace line (`r7`).
/// - `tail`: byte stored at `+0x15` (`r8`).
///
/// # Returns
/// Nothing; the export ends with the `0x802DCDBC` restore stub.
///
/// # Side effects
/// Writes six record fields, releases and reallocates the descriptor block and
/// may emit one trace line.
///
/// # Safety
/// `record` must be writable for `0x19` bytes; `descriptor`, when non-zero,
/// must hold a valid header and `length` readable bytes at its `+4` word.
///
/// # Confidence
/// medium - every store and the free/allocate/copy sequence are literal; the
/// descriptor header roles and the allocator's argument are `// unknown:`.
pub unsafe fn fn_80200080(
    record: usize,
    kind: u8,
    handle: u16,
    descriptor: usize,
    log_value: u32,
    tail: u8,
) {
    // observed: `if (4 < *(byte *)(unaff_r13 + -0x4ae8))`.
    if platform::read_u8(BTA_HH_LOG_LEVEL) > 4 {
        platform::call3(LOG_2, 0x0000_0504, S_HID_SUBCLASS, log_value);
    }

    platform::write_u8(record + 0x16, kind);
    platform::write_u8(record + 0x18, 1);
    platform::write_u16(record + 0x0E, handle);
    platform::write_u8(record + 0x13, log_value as u8);
    platform::write_u8(record + 0x15, tail);

    if descriptor != 0 {
        // observed: `FUN_801faaf0(psVar1 + 2)` - the word, not its value.
        platform::call1(HEAP_BLOCK_RELEASE, (record + 4) as u32);
        let length = platform::read_u16(descriptor);
        if length != 0 {
            let block = call0_u32(HID_ALLOC_801F6FB0) as usize;
            platform::write_u32(record + 4, block as u32);
            if block != 0 {
                platform::write_u16(record, length);
                platform::call3(
                    MEMCPY,
                    block as u32,
                    platform::read_u32(descriptor + 4),
                    length as u32,
                );
            }
        }
    }
}

/// Empty HID-host callback slot at `0x80204138`.
///
/// The four bytes are a bare `blr`; neighbouring HID code installs the address
/// as an optional hook, so the slot stays callable.
