// --- Mux command dispatcher, `0x8021AAF4` -----------------------------------

/// `0x8034BDB4`: `"rfc_mx_sm_state_idle: evt %d"`.
const S_RFC_MX_IDLE: u32 = 0x8034_BDB4;

/// `0x8034BE08`: `"RFCOMM_MX: ignored - evt %d in st %d"`.
const S_RFC_MX_IGNORED: u32 = 0x8034_BE08;

