// --- Mux frame parser, `0x8021DE28` -----------------------------------------

/// `0x803D5428` byte `+1`: address-field EA bit of the received frame.
const RF_CTX_EA: usize = 0x01;

/// `0x803D5428` byte `+3`: control byte with the two role bits masked off.
const RF_CTX_CONTROL: usize = 0x03;

/// `0x803D5428` bytes `+8..`: parameter-negotiation/response sub-block.
///
/// `// inferred:` the six command handlers fill this block with the fields of
/// the frame they just validated (PN/RPN/MSC); the build routines
/// [`fn_8021d270`]/[`fn_8021d630`] read it back.
const RF_CTX_PARAMS: usize = 0x08;

/// `0x8034C420`: `"Bad PN frame"`.
const S_RFC_BAD_PN: u32 = 0x8034_C420;

/// `0x8034C440`: `"Bad RPN frame"`.
const S_RFC_BAD_RPN: u32 = 0x8034_C440;

/// `0x8034C430`: `"Bad MSC frame"`.
const S_RFC_BAD_MSC: u32 = 0x8034_C430;

/// `0x8034C410`: `"Bad MX frame"`.
const S_RFC_BAD_MX: u32 = 0x8034_C410;

/// `0x8034C3F0`: `"Illegal MX Frame ea %d len %d"`.
const S_RFC_ILLEGAL_MX: u32 = 0x8034_C3F0;

/// `0x8021C6E4`: the flow-control handler (still untranslated; called by
/// address like the other skipped companions of this cluster).
const RF_8021C6E4: usize = 0x8021_C6E4;

/// Parses one multiplexer frame and dispatches its command.
///
/// The frame header is decoded first: the address byte at `+8` supplies the EA
/// bit (`+1`), the C/R bit (`+2`) and the control field with the two role bits
/// stripped (`+3`). The declared length is checked against the command's format
/// (`0x80` PN, `0x50` RPN, `0x20` test, `0x10` flow control, `0x60`/`0xA0`/
/// `0x90`/`0xE0` modem status and the remaining control commands) and the
/// matching handler is called with the decoded parameter block at
/// [`RF_CTX_PARAMS`]. Unknown or malformed frames are dropped; when the frame
/// needs an answer, a three-byte empty response is built through
/// [`fn_8021d0d8`].
///
/// # Original
/// - Ghidra: `FUN_8021DE28` at `0x8021DE28` (1572 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8021de28_FUN_8021de28.c`
///
/// # Arguments
/// - `mcb`: multiplexer channel block (`r3`).
/// - `packet`: received buffer; `+2` is the length and `+4` the read offset
///   (`r4`).
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes the receive context at [`RFCOMM_CONTEXT`], consumes or hands on
/// `packet`, allocates one response buffer and emits up to one trace line per
/// rejected frame.
///
/// # Safety
/// `packet` must be a live receive buffer of at least `8 + length` bytes; the
/// handlers expect the arguments documented in their own bodies.
///
/// # Confidence
/// medium - every mask, shift and store is transcribed from the export,
/// including the `CONCAT*n` folds, which are written as explicit byte stores
/// (the masks zero the bits the composed value does not carry, so the byte form
/// is identical). The one recovered value is the second vararg of the
/// `"Illegal MX Frame ea %d len %d"` call: Ghidra printed only the EA bit, so
/// the length is supplied and marked `// inferred:` at the call.
pub unsafe fn fn_8021de28(mcb: usize, packet: usize) {
    let ctx = RFCOMM_CONTEXT;
    let params = ctx + RF_CTX_PARAMS;

    let length = platform::read_u16(packet + 2);
    let start = packet + platform::read_u16(packet + 4) as usize;

    // observed: `DAT_803d542b = *(byte *)(iVar6 + 8) & 1;` and the two
    // neighbouring fields of the same address byte.
    let address = platform::read_u8(start + 8);
    let ea = address & 1;
    let cr = (address >> 1) & 1;
    platform::write_u8(ctx + RF_CTX_EA, ea);
    platform::write_u8(ctx + RF_CTX_CONTROL, address & 0xFC);
    platform::write_u8(ctx + RF_CTX_CR, cr);

    if ea == 0 || length == 0 {
        if platform::read_u8(G_RFCOMM_TRACE_LEVEL) != 0 {
            // inferred: the second format argument is the frame length.
            platform::call4(LOG_3, 0x0009_0000, S_RFC_ILLEGAL_MX, ea as u32, length as u32);
        }
        platform::call1(HEAP_FREE, packet as u32);
        return;
    }

    // observed: `pbVar7 = (byte *)(iVar6 + 10); uVar9 = b9 >> 1;`
    let mut data = start + 10;
    let mut declared = (platform::read_u8(start + 9) >> 1) as u32;
    let mut payload_len = length.wrapping_sub(2);
    if platform::read_u8(start + 9) & 1 == 0 {
        let high = platform::read_u8(start + 10);
        payload_len = length.wrapping_sub(3);
        data = start + 0x0B;
        declared = (declared + high as u32 * 0x80) & 0xFF;
    }

    if declared != payload_len as u32 {
        if platform::read_u8(G_RFCOMM_TRACE_LEVEL) != 0 {
            platform::call2(LOG_1, 0x0009_0000, S_RFC_BAD_MX);
        }
        platform::call1(HEAP_FREE, packet as u32);
        return;
    }

    let command = platform::read_u8(ctx + RF_CTX_CONTROL);
    let len = payload_len as u32;

    if command == 0x80 {
        if len == 8 {
            let p0 = platform::read_u8(data);
            let dlci = p0 & 0x3F;
            platform::write_u8(ctx, dlci);

            // observed: `CONCAT31(CONCAT21(CONCAT11(old0, p1), p1), p2) &
            // 0xff0ff03f` - byte 0 keeps the old value, byte 1 keeps the low
            // nibble of p1, byte 2 the high nibble, byte 3 keeps 0x3f.
            let old0 = platform::read_u8(params);
            let p1 = platform::read_u8(data + 1);
            let p2 = platform::read_u8(data + 2);
            let word = ((old0 as u32) << 24)
                | ((p1 as u32) << 16)
                | ((p1 as u32) << 8)
                | p2 as u32;
            platform::write_u32(params, word & 0xFF0F_F03F);

            // observed: `_DAT_803d5434 = CONCAT11(pbVar7[3], DAT_803d5435);`
            platform::write_u8(params + 4, platform::read_u8(data + 3));
            // observed: `DAT_803d5436 = p4 + p5 * 0x100;` (little-endian pair)
            platform::write_u16(
                params + 6,
                (platform::read_u8(data + 4) as u16)
                    | ((platform::read_u8(data + 5) as u16) << 8),
            );
            platform::write_u8(params + 8, platform::read_u8(data + 6));
            platform::write_u8(params + 9, platform::read_u8(data + 7) & 7);

            let mtu = platform::read_u16(params + 6);
            if dlci > 1 && dlci < 0x3E && mtu > 0x16 && mtu < 0x8000 {
                platform::call1(HEAP_FREE, packet as u32);
                fn_8021c0ec(mcb, cr as u32, ctx);
                return;
            }

            if platform::read_u8(G_RFCOMM_TRACE_LEVEL) != 0 {
                platform::call2(LOG_1, 0x0009_0000, S_RFC_BAD_PN);
            }
        }
    } else if command < 0x80 {
        if command == 0x50 {
            if len == 2 {
                let p0 = platform::read_u8(data);
                let dlci = (p0 >> 2) as u32;
                platform::write_u8(ctx, dlci as u8);

                // observed: `CONCAT13(old0, CONCAT12(p1, old._2_2_)) &
                // 0xfffeffff` - only byte 1 changes, with bit 0 cleared.
                platform::write_u8(params + 1, platform::read_u8(data + 1) & 0xFE);

                if p0 & 1 != 0 && p0 & 2 != 0 && dlci > 1 && dlci < 0x3E {
                    platform::call1(HEAP_FREE, packet as u32);
                    fn_8021c64c(mcb, cr as u32, ctx);
                    return;
                }

                if platform::read_u8(G_RFCOMM_TRACE_LEVEL) != 0 {
                    platform::call2(LOG_1, 0x0009_0000, S_RFC_BAD_RPN);
                }
            }
        } else if command < 0x50 {
            if command == 0x20 {
                if len != 0 {
                    // observed: `DAT_803d5430 = pbVar7;` - the payload pointer
                    // itself is stored, not the bytes it points at.
                    platform::write_u32(params, data as u32);
                    platform::write_u16(
                        params + 4,
                        payload_len,
                    );
                    platform::write_u16(
                        packet + 4,
                        platform::read_u16(packet + 4).wrapping_add(2),
                    );
                    platform::write_u16(
                        packet + 2,
                        platform::read_u16(packet + 2).wrapping_sub(2),
                    );
                    if cr != 0 {
                        fn_8021d74c(mcb as u32, 0, packet);
                        return;
                    }
                    fn_8021c6dc(mcb as u32, packet as u32);
                    return;
                }
            } else if command == 0x10 && len == 1 && cr != 0 {
                let p0 = platform::read_u8(data);
                // observed: three overlapping field writes from one byte:
                // `CONCAT13(p0, old._1_3_) & 0x01ffffff`, then byte 2 = p0 >> 2,
                // then byte 1 = (p0 & 2) >> 1.
                platform::write_u8(params, p0 & 1);
                platform::write_u8(params + 2, p0 >> 2);
                platform::write_u8(params + 1, (p0 & 2) >> 1);
                platform::call1(HEAP_FREE, packet as u32);
                fn_8021c6d8();
                return;
            }
        } else if command == 0x60 && len == 0 {
            platform::call1(HEAP_FREE, packet as u32);
            fn_8021c748(mcb, cr as u32);
            return;
        }
    } else if command == 0xA0 {
        if len == 0 {
            platform::call1(HEAP_FREE, packet as u32);
            platform::call2(RF_8021C6E4, mcb as u32, cr as u32);
            return;
        }
    } else if command < 0xA0 {
        if command == 0x90 && (len == 1 || len == 8) {
            let p0 = platform::read_u8(data);
            let dlci = (p0 >> 2) as u32;
            platform::write_u8(ctx, dlci as u8);

            if p0 & 1 != 0 && p0 & 2 != 0 && dlci > 1 && dlci < 0x3E {
                // observed: `countLeadingZeros(uVar8 - 1) >> 5` is exactly
                // "len == 1"; byte 1 of the parameter block records that bit.
                let single = payload_len == 1;
                platform::write_u8(params + 1, single as u8);

                if !single {
                    let p1 = platform::read_u8(data + 1);
                    let p2 = platform::read_u8(data + 2);
                    // observed: `CONCAT31(CONCAT21(old._0_2_, p1), p2) &
                    // 0xffffff03` -> bytes 0/1 unchanged, byte 2 = p1,
                    // byte 3 = p2 & 3.
                    platform::write_u8(params + 2, p1);
                    platform::write_u8(params + 3, p2 & 0x03);
                    // observed: `CONCAT11(p2 >> 2, p2 >> 3) & 0x101`
                    platform::write_u8(params + 4, (p2 >> 2) & 1);
                    platform::write_u8(params + 5, (p2 >> 3) & 1);
                    // observed: `CONCAT11(p2 >> 4, p3) & 0x33f`
                    platform::write_u8(params + 6, (p2 >> 4) & 0x03);
                    platform::write_u8(params + 7, platform::read_u8(data + 3) & 0x3F);
                    platform::write_u8(params + 8, platform::read_u8(data + 4));
                    platform::write_u8(params + 9, platform::read_u8(data + 5));
                    platform::write_u16(
                        params + 0x0A,
                        ((platform::read_u8(data + 6) as u16)
                            | ((platform::read_u8(data + 7) as u16) << 8))
                            & 0x3F7F,
                    );
                }

                platform::call1(HEAP_FREE, packet as u32);
                fn_8021c1d4(mcb, cr as u32, platform::read_u8(params + 1) as u32, ctx);
                return;
            }

            if platform::read_u8(G_RFCOMM_TRACE_LEVEL) != 0 {
                platform::call2(LOG_1, 0x0009_0000, S_RFC_BAD_RPN);
            }
        }
    } else if command == 0xE0 {
        let p0 = platform::read_u8(data);
        let dlci = (p0 >> 2) as u32;
        platform::write_u8(ctx, dlci as u8);

        if p0 & 1 != 0 && p0 & 2 != 0 && dlci > 1 && dlci < 0x3E {
            if len == 3 {
                let p1 = platform::read_u8(data + 1);
                let p2 = platform::read_u8(data + 2);
                // observed: `CONCAT31(CONCAT21(CONCAT11(old0, p1), p2), p2 >> 4)
                // & 0xffff02ff` - byte 1 keeps bit 1 of p1, byte 2 keeps bit 1
                // of p2, byte 3 is p2 >> 4; byte 0 is unchanged.
                platform::write_u8(params + 1, p1 & 0x02);
                platform::write_u8(params + 2, p2 & 0x02);
                platform::write_u8(params + 3, p2 >> 4);
            } else {
                // observed: `CONCAT11(old0, p1) << 16` - byte 0 keeps the old
                // value, byte 1 = p1, bytes 2/3 are zero.
                let old0 = platform::read_u8(params);
                let p1 = platform::read_u8(data + 1);
                platform::write_u32(params, ((old0 as u32) << 24) | ((p1 as u32) << 16));
            }

            platform::call1(HEAP_FREE, packet as u32);
            fn_8021c4e0(mcb, cr as u32, ctx);
            return;
        }

        if platform::read_u8(G_RFCOMM_TRACE_LEVEL) != 0 {
            platform::call2(LOG_1, 0x0009_0000, S_RFC_BAD_MSC);
        }
    }

    platform::call1(HEAP_FREE, packet as u32);

    // observed: `if ((bVar4 != 0) && (iVar6 = FUN_801f7150(2), iVar6 != 0))`
    if cr != 0 {
        let response = platform::call1(HEAP_ALLOC, HCI_ALLOC_CLASS) as usize;
        if response != 0 {
            platform::write_u16(response + 4, 0x0C);
            platform::write_u8(response + 0x14, 0x11);
            platform::write_u8(response + 0x15, 3);
            platform::write_u8(
                response + 0x16,
                platform::read_u8(ctx + RF_CTX_CONTROL)
                    | platform::read_u8(ctx + RF_CTX_EA)
                    | (platform::read_u8(ctx + RF_CTX_CR) << 1),
            );
            platform::write_u16(response + 2, 3);
            fn_8021d0d8(mcb as u32, 0, response as u32);
        }
    }
}

// ===========================================================================
// Wave 108 - the last SDP server handler and the render/text tail
//
// `0x80222E38` is the third SDP server request handler, the sibling of
// `fn_80222698` and `fn_80222aa8`. The rest of this block is the tail of the
// `0x8022D440..0x8022FA70` palette/text renderer: a texture-object setup that
// feeds the GX FIFO, the glyph layouter and the bounding-box wrapper. They are
// not Bluetooth code; they live here because the image places them in this
// lane (the same classification note as waves 47 and 102).
// ===========================================================================

/// `0x8042ABC0`: pointer to the request block whose reply the synchronous
/// submitter is waiting for (`r13 - 0x4AC0`).
///
/// `// observed:` `FUN_802243c0` compares it with the block it just retired and
/// `FUN_80225a80` stores the freshly allocated block here.
const SDA_IPC_SYNC_BLOCK: usize = 0x8042_ABC0;

/// `0x8042ABBC`: pointer to the static `0x40`-byte copy of that block
/// (`r13 - 0x4AC4`).
///
/// `// observed:` `FUN_80224620` clears the copy's status word and signals its
/// event at `+0x2C`; `FUN_80225a80` returns the copy's status word.
const SDA_IPC_SYNC_COPY: usize = 0x8042_ABBC;

/// `0x803D9F00`: the `0x40`-byte request block the synchronous path copies its
/// block into, immediately after the 16-entry completion ring.
const IPC_STATIC_BLOCK: usize = 0x803D_9F00;

/// `0x803D9F2C`: the lock object at `+0x2C` of [`IPC_STATIC_BLOCK`].
const IPC_STATIC_LOCK: usize = 0x803D_9F2C;

/// Builds and sends a ServiceSearchAttributeResponse for a request.
///
/// The request body is a UUID pattern sequence, a maximum attribute byte count
/// (`u16`), an attribute-id sequence and a continuation state. The pattern is
/// decoded by [`fn_802237f0`] into a 16-entry table and the ids by
/// [`fn_80223b40`] into `{low u16, high u16}` pairs. For every matching service
/// record, each requested attribute is resolved with [`fn_8021fd04`] and
/// encoded with [`fn_80223560`] into the CCB receive buffer.
///
/// The much smaller `fn_80222aa8` writes a single record; this handler walks
/// all matching records with [`fn_8021fa94`] and back-patches a per-record
/// `0x36` sequence header. The export writes that header at the record's first
/// data byte (`puVar18`, the cursor before the inner attribute loop), so the
/// header overwrites the record's first three attribute bytes and the store is
/// reproduced literally rather than "fixed".
///
/// The finished sequence is copied into a class-`2` block with PDU id `7`
/// (ServiceSearchAttributeResponse) and sent through [`L2CAP_DATA_WRITE`]. The
/// continuation state follows the parameter bytes: `0` when the whole buffer
/// fitted, otherwise `2` and the `u16` buffer offset of the next slice.
///
/// # Original
/// - Ghidra: `FUN_80222E38` at `0x80222E38` (1052 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80222e38_FUN_80222e38.c`
///
/// # Arguments
/// - `ccb`: SDP connection block (`r3`, folded by the `0x802DCD58` prologue).
/// - `transaction`: request transaction id (`r4`, the folded low half).
/// - `request_size`: bytes available at `request`.
/// - `request`: first byte of the request body.
/// - `request_end`: one past the last request byte; the caller
///   [`fn_80222544`] has already checked it, and this body does not read it.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `ccb + 0x24` (bytes left), `ccb + 0x26` (sequence) and
/// `ccb + 0x476` (continuation offset), allocates and sends one PDU, and may
/// log an SDP error or the no-buffer line.
///
/// # Safety
/// `request..request + request_size` must be readable; `ccb` must be a live CCB
/// with its receive buffer, MTU and channel id initialised.
///
/// # Confidence
/// medium - every offset, bound and payload byte is literal. The two 0x42-byte
/// stack copies around the record loop are the compiler's register
/// save/restore pair (the same artifact as the `GQR0` blocks): no call reads
/// either region, so they are not reproduced; `request_end` is unused because
/// the dispatcher validated it.
pub unsafe fn fn_80222e38(
    ccb: usize,
    transaction: u16,
    request_size: u32,
    request: usize,
    request_end: usize,
) {
    let _ = request_end;

    let mut pattern = crate::platform::GuestLocal::new( [0u16; 146]);
    let cursor = fn_802237f0(request, request_size, pattern.as_mut_ptr() as usize) as usize;
    if cursor == 0 || pattern[0] == 0 {
        fn_802236b4(ccb, transaction, 3, 0);
        return;
    }

    // observed: `uVar4 = *pbVar11 * 0x100 + pbVar11[1];` - max attribute bytes.
    let mut max = sdp_read_be16(cursor) as u32;
    let space = platform::read_u16(ccb + SDP_CCB_MTU) as i32 - 10;
    if space < max as i32 {
        max = space as u32 & 0xFFFF;
    }

    // observed: `FUN_80223b40(pbVar11 + 2, param_3, &local_1a4);`
    let mut ids = crate::platform::GuestLocal::new( [0u16; 0x22]);
    let attribute = fn_80223b40(cursor + 2, request_size, ids.as_mut_ptr() as usize) as usize;
    if attribute == 0 || ids[0] == 0 {
        fn_802236b4(ccb, transaction, 3, 0);
        return;
    }

    if platform::read_u8(attribute) == 0 {
        // observed: `puVar18 = (undefined1 *)(iVar10 + 0x29);` - the header
        // cursor starts three bytes before the first attribute byte.
        let mut header = ccb + SDP_CCB_RX_BUFFER + 3;
        let mut out = header;
        platform::write_u16(ccb + SDP_CCB_CONTINUATION, 0);

        let mut split = false;
        let mut record = fn_8021fa94(0, pattern.as_mut_ptr() as usize);
        while record != 0 {
            // observed: `for (iVar19 = ...; puVar17 = puVar18, iVar19 != 0; ...)`
            out = header;
            let mut slot = 0u16;
            while slot < ids[0] {
                let lo = ids[1 + slot as usize * 2];
                let hi = ids[2 + slot as usize * 2];
                let entry = fn_8021fd04(record, lo as u32, hi as u32);
                if entry != 0 {
                    let used = out.wrapping_sub(ccb + SDP_CCB_RX_BUFFER) as u32 & 0xFFFF;
                    if 1000u32.wrapping_sub(used).wrapping_sub(6)
                        < platform::read_u32(entry)
                    {
                        split = true;
                        break;
                    }
                    out = fn_80223560(out, entry);
                    if lo != hi {
                        // observed: re-visit the same slot with the next id.
                        ids[1 + slot as usize * 2] =
                            platform::read_u16(entry + 8).wrapping_add(1);
                        continue;
                    }
                }
                slot = slot.wrapping_add(1);
            }

            if split {
                break;
            }

            // observed: `uVar5 = puVar17 - 3 - puVar18; if (uVar5 != 0) {
            // *puVar18 = 0x36; ...; puVar18 = puVar17; }`
            let written = out.wrapping_sub(header).wrapping_sub(3) as u32 & 0xFFFF;
            if written != 0 {
                platform::write_u8(header, 0x36);
                platform::write_u8(header + 1, (written >> 8) as u8);
                platform::write_u8(header + 2, written as u8);
                header = out;
            }

            record = fn_8021fa94(record, pattern.as_mut_ptr() as usize);
        }

        // observed: `uVar8 = (int)puVar17 - (iVar10 + 0x26);` then the short
        // (`0x35`) or long (`0x36`) outer sequence header.
        let total = out.wrapping_sub(ccb + SDP_CCB_RX_BUFFER) as u32 & 0xFFFF;
        platform::write_u16(ccb + SDP_CCB_RX_LEN, total as u16);
        if total < 0x100 {
            platform::write_u16(ccb + SDP_CCB_CONTINUATION, 1);
            platform::write_u8(ccb + SDP_CCB_RX_BUFFER + 1, 0x35);
            platform::write_u8(ccb + SDP_CCB_RX_BUFFER + 2, total.wrapping_sub(3) as u8);
            platform::write_u16(ccb + SDP_CCB_RX_LEN, total.wrapping_sub(1) as u16);
        } else {
            platform::write_u8(ccb + SDP_CCB_RX_BUFFER, 0x36);
            platform::write_u8(ccb + SDP_CCB_RX_BUFFER + 1, (total.wrapping_sub(3) >> 8) as u8);
            platform::write_u8(ccb + SDP_CCB_RX_BUFFER + 2, total.wrapping_sub(3) as u8);
        }
    } else {
        // observed: only the two-byte continuation form is accepted.
        if platform::read_u8(attribute) != 2
            || sdp_read_be16(attribute + 1) as u32
                != platform::read_u16(ccb + SDP_CCB_CONTINUATION) as u32
        {
            fn_802236b4(ccb, transaction, 5, 0);
            return;
        }
    }

    let packet = platform::call1(HEAP_ALLOC, 2) as usize;
    if packet == 0 {
        if platform::read_u8(SDP_TRACE_LEVEL) != 0 {
            platform::call2(LOG_1, 0x000A_0000, S_SDP_NO_SEARCH_BUFFER);
        }
        return;
    }

    platform::write_u16(packet + 4, 9);
    platform::write_u8(packet + 0x11, 7);
    platform::write_u8(packet + 0x12, (transaction >> 8) as u8);
    platform::write_u8(packet + 0x13, transaction as u8);

    let stored = platform::read_u16(ccb + SDP_CCB_RX_LEN) as u32;
    if stored <= max {
        max = stored;
    }
    platform::write_u8(packet + 0x16, (max >> 8) as u8);
    platform::write_u8(packet + 0x17, max as u8);

    let offset = platform::read_u16(ccb + SDP_CCB_CONTINUATION) as usize;
    platform::call3(
        MEMCPY,
        (packet + 0x18) as u32,
        (ccb + SDP_CCB_RX_BUFFER + offset) as u32,
        max,
    );

    let mut out = packet + 0x18 + max as usize;
    let left = stored.wrapping_sub(max) & 0xFFFF;
    platform::write_u16(ccb + SDP_CCB_RX_LEN, left as u16);
    let at = ccb + SDP_CCB_CONTINUATION;
    platform::write_u16(at, platform::read_u16(at).wrapping_add(max as u16));
    if left == 0 {
        platform::write_u8(out, 0);
        out += 1;
    } else {
        platform::write_u8(out, 2);
        let next = platform::read_u16(at);
        platform::write_u8(out + 1, (next >> 8) as u8);
        platform::write_u8(out + 2, next as u8);
        out += 3;
    }

    let body_len = out.wrapping_sub(2 + (packet + 0x14)) as u32 & 0xFFFF;
    platform::write_u8(packet + 0x14, (body_len >> 8) as u8);
    platform::write_u8(packet + 0x15, body_len as u8);
    platform::write_u16(packet + 2, out.wrapping_sub(packet + 0x11) as u16);
    platform::call2(
        L2CAP_DATA_WRITE,
        platform::read_u16(ccb + SDP_CCB_CID) as u32,
        packet as u32,
    );
}

/// Submits one synchronous kind-7 request through a static shadow block.
///
/// The block is allocated from [`SDA_IPC_POOL`] exactly like [`fn_802258b0`]
/// and prepared by [`fn_80225770`]. Unlike that builder, this one is the
/// *synchronous* path used by the EXI/device wrapper at `0x801D62E0`:
///
/// 1. it refuses to re-enter while [`SDA_IPC_DONE_REQUEST`] is set (`-10`),
/// 2. it copies the finished `0x40`-byte block into [`IPC_STATIC_BLOCK`],
///    records that copy in [`SDA_IPC_SYNC_COPY`] and locks the static lock at
///    [`IPC_STATIC_LOCK`],
/// 3. under the OS critical section it pushes the heap block into the 16-entry
///    ring, updates the monotonic counters and, when a waiter is pending,
///    dequeues one entry and pulses the controller status,
/// 4. it releases the static lock, restores the critical section and returns
///    the status word at `+4` of the static copy.
///
/// The export prints only one argument for [`fn_802260c0`] on the failure path;
/// the block is the second argument, the same convention as [`fn_80224910`].
///
/// # Original
/// - Ghidra: `FUN_80225A80` at `0x80225A80` (764 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80225a80_FUN_80225a80.c`
///
/// # Arguments
/// - `id`: request identifier stored at `+8` (`r3`, the folded high half).
/// - `table`: buffer table passed to [`fn_80225770`] (`r4`, the low half).
/// - `count_a`, `count_b`: table entry counts for [`fn_80225770`].
/// - `entries`: table pointer for [`fn_80225770`].
///
/// # Returns
/// `0` or the static copy's status word, `-10` when a synchronous submit is
/// already in flight, `-22` on allocation failure, `-8` when the ring is full,
/// or the error from [`fn_80225770`].
///
/// # Side effects
/// Allocates one block, copies it to [`IPC_STATIC_BLOCK`], takes and releases
/// the static lock, pushes into the completion ring, writes the controller
/// status and may free the block.
///
/// # Safety
/// The table must be a readable array of `count_a + count_b`
/// `{u32 pointer, u32 length}` entries, as [`fn_80225770`] requires.
///
/// # Confidence
/// medium - the block layout, the ring guard, the static-copy stores and both
/// locks are literal. The export's `&stack0x00000000 == 0x28` comparison cannot
/// be tracked and is not reproduced; every reachable path continues at the
/// allocation. `fn_802260c0`'s dropped block argument is recovered from its
/// signature and from the guard that only frees a non-null block.
pub unsafe fn fn_80225a80(
    id: u32,
    table: u32,
    count_a: u32,
    count_b: u32,
    entries: u32,
) -> i32 {
    let state = call0_ret(OS_DEBUG_ENTER);
    let mut rc: i32 = 0;
    let mut block: usize = 0;

    if platform::read_u32(SDA_IPC_DONE_REQUEST) != 0 {
        // observed: the export calls `FUN_801b1180()` without the saved state.
        platform::call1(OS_DEBUG_RESTORE, state);
        rc = -10;
    } else {
        platform::write_u32(SDA_IPC_DONE_REQUEST, 1);
        platform::call1(OS_DEBUG_RESTORE, state);

        let allocated = platform::call3(
            IPC_ALLOC_80225EB0,
            platform::read_u32(SDA_IPC_POOL),
            IPC_REQUEST_SIZE,
            IPC_REQUEST_ALIGN,
        ) as usize;
        if allocated == 0 {
            rc = -0x16;
        } else {
            block = allocated;
            platform::write_u32(block + 0x20, 0);
            platform::write_u32(block + 0x24, 0);
            platform::write_u32(block + 0x28, 0);
            platform::write_u32(block, 7);
            platform::write_u32(block + 8, id);
        }

        if rc == 0 {
            platform::write_u32(SDA_IPC_SYNC_BLOCK, block as u32);
            // observed: `local_28[10] = 1;` - mark the block as synchronous.
            platform::write_u32(block + 0x28, 1);

            rc = fn_80225770(block as u32, table, count_a, count_b, entries);
            if rc == 0 {
                platform::call3(
                    MEMCPY,
                    IPC_STATIC_BLOCK as u32,
                    block as u32,
                    IPC_REQUEST_SIZE,
                );
                platform::write_u32(SDA_IPC_SYNC_COPY, IPC_STATIC_BLOCK as u32);
                platform::call1(LOCK_801B4B20, IPC_STATIC_LOCK as u32);
                platform::call2(DC_FLUSH_801AC470, block as u32, 0x20);

                let guard = call0_ret(OS_DEBUG_ENTER);

                // observed: the same ring guard as `fn_80224910`.
                let enqueued = platform::read_u32(IPC_ENQUEUED);
                let dequeued = platform::read_u32(IPC_DEQUEUED);
                let probe = if enqueued < dequeued {
                    enqueued.wrapping_sub(dequeued)
                } else {
                    let d = enqueued - dequeued;
                    ((d | 0xFFFF_FFEF).wrapping_sub(d.wrapping_sub(0x10) >> 1)) >> 31
                };

                if probe == 0 {
                    let push = platform::read_u32(IPC_RING_PUSH) as usize;
                    platform::write_u32(IPC_RING + push * 4, block as u32);
                    platform::write_u32(IPC_RING_PUSH, ((push as u32) + 1) & 0xF);
                    platform::write_u32(IPC_ENQUEUED, enqueued + 1);
                    fn_80226370(block as u32, platform::read_u32(block + 8));
                } else {
                    rc = -8;
                }

                if rc == 0 {
                    if platform::read_i32(SDA_IPC_PENDING) > 0 {
                        let diff = platform::read_u32(IPC_ENQUEUED)
                            .wrapping_sub(platform::read_u32(IPC_DEQUEUED));
                        // observed: `countLeadingZeros(diff) >> 5` - non-zero iff empty.
                        let empty = (diff == 0) as u32;
                        if empty == 0 {
                            let pop = platform::read_u32(IPC_RING_POP) as usize;
                            let queued = platform::read_u32(IPC_RING + pop * 4);
                            if queued != 0 {
                                if platform::read_u32(queued as usize + 0x28) != 0 {
                                    let v = platform::read_i32(SDA_IPC_PENDING);
                                    platform::write_i32(SDA_IPC_PENDING, v - 1);
                                }
                                fn_80224350(0, queued.wrapping_sub(0x8000_0000));
                                let now = platform::read_u32(IPC_DEQUEUED);
                                platform::write_u32(IPC_DEQUEUED, now + 1);
                                platform::write_u32(IPC_RING_POP, ((pop as u32) + 1) & 0xF);
                                let v = platform::read_i32(SDA_IPC_PENDING);
                                platform::write_i32(SDA_IPC_PENDING, v - 1);
                                let value = fn_80224340(1);
                                fn_80224350(1, (value & 0x30) | 1);
                            }
                        }
                    }

                    // observed: `FUN_801b5c90(*(int *)(r13 - 0x4ac4) + 0x2c);`
                    platform::call1(UNLOCK_801B5C90, IPC_STATIC_LOCK as u32);
                    platform::call1(OS_DEBUG_RESTORE, guard);
                    rc = platform::read_i32(IPC_STATIC_BLOCK + 4);
                } else {
                    platform::call1(OS_DEBUG_RESTORE, guard);
                }
            }
        }

        platform::write_u32(SDA_IPC_DONE_REQUEST, 0);
        platform::write_u32(SDA_IPC_SYNC_BLOCK, 0);
        if block != 0 && rc != 0 {
            fn_802260c0(platform::read_u32(SDA_IPC_POOL), block as u32);
        }
    }

    rc
}

/// `0x803DA100` / `0x803DA104`: the two cache-key words that follow
/// [`GX_STATE_KEY_A`].
///
/// `// observed:` `0x8022D720` compares all three with the texture descriptor
/// and rewrites them together with [`GX_STATE_DIRTY`] when anything changed.
const GX_STATE_KEY_B: usize = 0x803D_A100;
const GX_STATE_KEY_C: usize = 0x803D_A104;

/// `0xCC008000`: the GX write-gather FIFO.
///
/// `// observed:` every immediate-mode writer in the `0x8022xxxx` lane assigns
/// here (`_DAT_cc008000`), as `src/game/stage.rs` and
/// `src/resource/archive.rs` also document.
const GX_FIFO_WRITE: usize = 0xCC00_8000;

/// `0x801C6D90`: initialise a `0x20`-byte GX texture object.
///
/// The signature is the one [`crate::runtime::dvd`]'s `fn_801c6d90` documents:
/// `(object, image, width, height, format, tex_mode, filter, mipmap)`.
const TEX_INIT_801C6D90: usize = 0x801C_6D90;

/// `0x801C6FF0`: set the filter/bias fields of a texture object.
///
/// `(min_filter, mag_filter, bias, object, texgen_src, aniso, edge_lod,
/// zero_flag, field19)`; the roles are the ones `fn_801c6ff0` documents.
const TEX_FILTER_801C6FF0: usize = 0x801C_6FF0;

/// `0x801C74C0`: load an initialised texture object into the named slot.
const TEX_LOAD_801C74C0: usize = 0x801C_74C0;

/// `0x801C5570`: select a GX attribute-format group.
const GX_ATTR_801C5570: usize = 0x801C_5570;

/// Calls a routine taking three `f32` and six word arguments.
///
/// [`platform::call7`] cannot move floats into `f1..f3`, and the texture
/// filter setter takes exactly this shape (the export prints the three as
/// `double` because the paired-single save block widened them).
///
/// # Safety
/// `addr` must point to a function with this ABI.
unsafe fn call_f32x3_six(
    addr: usize,
    a: f32,
    b: f32,
    c: f32,
    d: u32,
    e: u32,
    f: u32,
    g: u32,
    h: u32,
    i: u32,
) {
    let func = crate::platform::guest_fn!(addr, fn(f32, f32, f32, u32, u32, u32, u32, u32, u32));
    func(a, b, c, d, e, f, g, h, i);
}

/// Draws one palette/text object with a freshly initialised texture object.
///
/// The descriptor is the `0x14`-byte texture block the palette layer keeps next
/// to the object: `+0` image address, `+7` a byte added to the `u16` at
/// `+0x12`, `+8` GX format, `+0xC` width, `+0xE` height. The object supplies
/// the texture-unit selectors at `+0x38`/`+0x3C` and the low half of the FIFO
/// word at `+0x10`.
///
/// A three-word cache key (`image`, `+0x38`, `+0x3C`) guards the texture setup:
/// only when [`GX_STATE_DIRTY`] or one key word differs does the body build a
/// stack `0x20`-byte texture object, program it with
/// [`TEX_INIT_801C6D90`]/[`TEX_FILTER_801C6FF0`], upload it with
/// [`TEX_LOAD_801C74C0`] and store the new key. It then selects attribute
/// group `0x80` and writes one packed FIFO word whose high half is
/// `(span * 0x8000) / height`.
///
/// # Original
/// - Ghidra: `FUN_8022D720` at `0x8022D720` (636 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8022d720_FUN_8022d720.c`
///
/// # Arguments
/// - `object`: palette/render object (`r3`, folded by the `0x802DCD70`
///   prologue); `+0x38`/`+0x3C` are texture selectors, `+0x10` the FIFO low
///   half.
/// - `descriptor`: texture descriptor (`r4`, the folded low half).
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Programs and uploads a GX texture object, writes the three cache keys plus
/// [`GX_STATE_DIRTY`], selects a GX attribute group and writes the FIFO.
///
/// # Safety
/// `object` must be readable at `+0x38`/`+0x3C`/`+0x10`; `descriptor` must be
/// readable for `0x14` bytes, and its image address must be a valid texture.
///
/// # Confidence
/// medium - the cache test, both texture calls, the upload, the attribute
/// select and the FIFO word are literal. The descriptor field roles are
/// inferred from the two texture-object initialisers; the opening and closing
/// `ldexpf`/`CONCAT` blocks are the compiler's paired-single save/restore of
/// `f27..f31` and are not data flow. A zero height would trap in the original
/// divide, so the body yields `0` for that impossible case.
pub unsafe fn fn_8022d720(object: usize, descriptor: usize) {
    let data = platform::read_u32(descriptor);
    let span =
        platform::read_u16(descriptor + 0x12) as u32 + platform::read_u8(descriptor + 7) as u32;
    let width = platform::read_u16(descriptor + 0x0C) as u32;
    let height = platform::read_u16(descriptor + 0x0E) as u32;
    let format = platform::read_u32(descriptor + 8);
    let key_b = platform::read_u32(object + 0x38);
    let key_c = platform::read_u32(object + 0x3C);

    if platform::read_u32(GX_STATE_DIRTY) != 0
        || data != platform::read_u32(GX_STATE_KEY_A)
        || key_b != platform::read_u32(GX_STATE_KEY_B)
        || key_c != platform::read_u32(GX_STATE_KEY_C)
    {
        let mut texture = crate::platform::GuestLocal::new( [0u32; 8]);
        let level = platform::read_f32(SDA2_F32_4C58);
        call8(
            TEX_INIT_801C6D90,
            texture.as_mut_ptr() as u32,
            data,
            width,
            height,
            format,
            0,
            0,
            0,
        );
        call_f32x3_six(
            TEX_FILTER_801C6FF0,
            level,
            level,
            level,
            texture.as_mut_ptr() as u32,
            key_b,
            key_c,
            0,
            0,
            0,
        );
        platform::call2(TEX_LOAD_801C74C0, texture.as_mut_ptr() as u32, 0);

        platform::write_u32(GX_STATE_DIRTY, 0);
        platform::write_u32(GX_STATE_KEY_A, data);
        platform::write_u32(GX_STATE_KEY_B, key_b);
        platform::write_u32(GX_STATE_KEY_C, key_c);
    }

    platform::call3(GX_ATTR_801C5570, 0x80, 0, 4);

    let scale = if height == 0 { 0 } else { span * 0x8000 / height };
    // observed: `(short)*(undefined4 *)(iVar8 + 0x10)` - the low 16 bits of
    // the word, which are bytes `+0x12`/`+0x13` of the object.
    let value = ((scale & 0xFFFF) << 16) | (platform::read_u32(object + 0x10) & 0xFFFF);
    platform::write_u32(GX_FIFO_WRITE, value);
}

/// `0x802DCBFC` - the shared pointer-to-member dispatcher behind the text
/// cursor. The receiver is the four-word record and the descriptor is
/// `record + 4`; one call decodes one character and advances `record[0]`.
///
/// `0x802DCD58` / `0x802DCDA4` are the paired `r3`/`r4` register-save and
/// restore thunks. As everywhere else in this file they are not called: the
/// body takes the folded arguments as ordinary parameters and returns the word
/// the restore is printed with.

/// Lays out one line of text into a bounding rectangle.
///
/// The object is the `0x64`-byte text state used by the whole palette family:
/// `+0x24` horizontal scale, `+0x2C`/`+0x30` cursor, `+0x43` "use `+0x44`
/// advance" flag, `+0x44` fixed advance, `+0x48` the glyph provider, `+0x4C`
/// the sentinel line limit, `+0x50` the wrap step, `+0x60` the layout helper.
/// `cursor` points at the first character and `remaining` is the byte count
/// left in the buffer.
///
/// For every control code (`< 0x20`) the layout helper's slot `+0x10` is asked
/// to draw one glyph into a four-float rectangle; the rectangle is folded into
/// the caller's `out` box and the helper's result selects the next action
/// (`4` = move to the end, `3` = stop, `1`/`2` = carry the wrap flag). For every
/// printable code the glyph provider's slot `+0x48` supplies the advance, which
/// is scaled and added to the cursor before the box is widened.
///
/// When the line limit has already been passed and a character is wider than
/// the remaining space, the body re-runs the same character as code `10`
/// (newline) from the saved start position. The `0x64`-byte state copy handed
/// to the layout helper is passed by pointer in a small stack context; the
/// export leaves three context words unwritten, so they are marked unknown.
///
/// # Original
/// - Ghidra: `FUN_8022F350` at `0x8022F350` (1468 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8022f350_FUN_8022f350.c`
///
/// # Arguments
/// - `object`: `0x64`-byte text state (`r3`, folded by the `0x802DCD58`
///   prologue).
/// - `out`: four `f32` receiving `{min_x, min_y, max_x, max_y}` (`r4`).
/// - `cursor`: one `u32` holding the current buffer offset, updated in place.
/// - `remaining`: bytes still available at the cursor.
///
/// # Returns
/// The word the export's `0x802DCDA4` restore is printed with (`1` after a
/// character was replayed as a newline, `0` otherwise); no caller reads it.
///
/// # Side effects
/// Advances `*cursor`, widens `out`, writes `object + 0x2C` and may call the
/// glyph draw/measure slots of `object + 0x60` and `object + 0x48`.
///
/// # Safety
/// `object` must be readable/writable for `0x64` bytes, `out` for four floats,
/// `cursor` for one word, and the two helper objects must have live vtables.
///
/// # Confidence
/// low - the whole loop, every field offset and every virtual slot is literal;
/// the slot roles are inferred from their argument shapes, the decode routine
/// at `0x802DCBFC` is unnamed, and the stack context's middle words are never
/// written in the export. The opening `ldexpf`/`CONCAT` block is the compiler's
/// paired-single save of `f27..f31` and is not reproduced.
#[allow(unused_assignments)]
pub unsafe fn fn_8022f350(
    object: usize,
    out: usize,
    cursor: *mut u32,
    remaining: u32,
) -> u32 {
    let sentinel = platform::read_f32(SDA2_F32_4C34);
    let limit = platform::read_f32(object + 0x4C);
    let limited = limit < platform::read_f32(SDA2_F32_4C38);

    let start = platform::read_u32(cursor as usize);
    let mut record = crate::platform::GuestLocal::new( [0u32; 4]);
    fn_8022f910(record.as_mut_ptr() as usize, platform::read_u32(object + 0x48) as usize);
    platform::write_f32(out, sentinel);
    platform::write_f32(out + 8, sentinel);

    let inner = platform::read_u32(object + 0x48) as usize;
    let top = if inner == 0 {
        0
    } else {
        platform::call1(
            platform::read_u32(platform::read_u32(inner) as usize + 0x34) as usize,
            inner as u32,
        )
    };
    let first = platform::read_f32(object + 0x54) + (top as f32) * platform::read_f32(object + 0x28);
    platform::write_f32(out + 4, sentinel.min(first));

    let bottom = if inner == 0 {
        0
    } else {
        platform::call1(
            platform::read_u32(platform::read_u32(inner) as usize + 0x34) as usize,
            inner as u32,
        )
    };
    let second =
        platform::read_f32(object + 0x54) + (bottom as f32) * platform::read_f32(object + 0x28);
    platform::write_f32(out + 0x0C, sentinel.max(second));

    let zero = 0.0f32;
    let mut retry: u32 = 0;
    let mut wrapped = 0u32;
    let mut saved = 0u32;
    let mut position = start;
    platform::write_u32(record.as_mut_ptr() as usize, position);
    let mut code = interface_call_desc(
        Descriptor::new(record.as_ptr().add(1) as usize),
        record.as_mut_ptr() as u32,
    ) as u16;
    let mut step = sentinel;

    loop {
        position = platform::read_u32(record.as_mut_ptr() as usize);
        if start.wrapping_add(remaining) < position {
            platform::write_u32(cursor as usize, position);
            return retry;
        }

        if (code as u32) < 0x20 {
            // observed: `local_104 = countLeadingZeros(iVar13) >> 5;` - 1 on
            // the first pass, 0 after a wrap.
            let first_pass = (wrapped == 0) as u32;
            let mut rect = crate::platform::GuestLocal::new( [sentinel; 4]);
            let rect_ptr = rect.as_mut_ptr() as usize;

            if limited && code != 10 && saved != 0 {
                // observed: run the glyph once into a copy of the state to
                // learn whether it still fits on this line.
                let mut state = crate::platform::GuestLocal::new( [0u32; 0x19]);
                let state_ptr = state.as_mut_ptr() as usize;
                copy_text_state(state_ptr, object);
                let mut context = crate::platform::GuestLocal::new( [0u32; 5]);
                // unknown: words 1..3 are never written by the export; they are
                // zeroed here instead of left undefined.
                context[0] = state_ptr as u32;
                context[4] = first_pass;
                let font = platform::read_u32(object + 0x60) as usize;
                platform::call4(
                    platform::read_u32(platform::read_u32(font) as usize + 0x10) as usize,
                    font as u32,
                    rect_ptr as u32,
                    code as u32,
                    context.as_mut_ptr() as u32,
                );
                let wide = platform::read_f32(rect_ptr + 8) - platform::read_f32(rect_ptr)
                    > sentinel;
                let moved = platform::read_f32(state_ptr + 0x2C) - zero;
                if !wide || moved <= limit {
                    fn_8022c980(state_ptr, 0);
                } else {
                    retry = 1;
                    code = 10;
                    platform::write_u32(record.as_mut_ptr() as usize, saved);
                    fn_8022c980(state_ptr, 0);
                    continue;
                }
            }

            rect[0] = step;
            rect[1] = sentinel;
            rect[2] = sentinel;
            rect[3] = sentinel;
            let font = platform::read_u32(object + 0x60) as usize;
            let mut context = crate::platform::GuestLocal::new( [0u32; 2]);
            context[0] = object as u32;
            context[1] = platform::read_u32(record.as_mut_ptr() as usize);
            let result = platform::call4(
                platform::read_u32(platform::read_u32(font) as usize + 0x10) as usize,
                font as u32,
                rect_ptr as u32,
                code as u32,
                context.as_mut_ptr() as u32,
            ) as i32;
            platform::write_u32(
                record.as_mut_ptr() as usize,
                platform::read_u32(context.as_ptr() as usize + 4),
            );

            let x0 = platform::read_f32(rect_ptr);
            let y0 = platform::read_f32(rect_ptr + 4);
            let x1 = platform::read_f32(rect_ptr + 8);
            let y1 = platform::read_f32(rect_ptr + 0x0C);
            platform::write_f32(out, platform::read_f32(out).min(x0));
            platform::write_f32(out + 4, platform::read_f32(out + 4).min(y0));
            platform::write_f32(out + 8, platform::read_f32(out + 8).max(x1));
            platform::write_f32(out + 0x0C, platform::read_f32(out + 0x0C).max(y1));

            step = platform::read_f32(object + 0x2C);

            if result == 4 {
                retry = 0;
                platform::write_u32(cursor as usize, start.wrapping_add(remaining));
                return retry;
            }
            if result == 1 {
                wrapped = 0;
            } else if result == 2 {
                wrapped = 1;
            } else if result == 3 {
                platform::write_u32(
                    cursor as usize,
                    platform::read_u32(record.as_mut_ptr() as usize),
                );
                return retry;
            }
        } else {
            let mut advance = sentinel as f64;
            if wrapped != 0 {
                advance += platform::read_f32(object + 0x50) as f64;
            }
            if platform::read_u8(object + 0x43) == 0 {
                let scale = platform::read_f32(object + 0x24) as f64;
                let count = platform::call2(
                    platform::read_u32(platform::read_u32(inner) as usize + 0x48) as usize,
                    inner as u32,
                    code as u32,
                );
                advance += (count as f32) as f64 * scale;
            } else {
                advance += platform::read_f32(object + 0x44) as f64;
            }

            // observed: `(float)(dVar19 + (double)(float)dVar15)`.
            if limited && saved != 0 && limit < (step as f64 + advance) as f32 {
                retry = 1;
                code = 10;
                platform::write_u32(record.as_mut_ptr() as usize, saved);
                continue;
            }

            step = (step as f64 + advance) as f32;
            platform::write_f32(out, platform::read_f32(out).min(step));
            platform::write_f32(out + 8, platform::read_f32(out + 8).max(step));
            wrapped = 1;
        }

        if limited {
            saved = platform::read_u32(record.as_mut_ptr() as usize);
        }
        code = interface_call_desc(
            Descriptor::new(record.as_ptr().add(1) as usize),
            record.as_mut_ptr() as u32,
        ) as u16;
    }
}

/// Copies the `0x64`-byte text state block.
///
/// # Safety
/// `dst` must be writable and `src` readable for `0x64` bytes; both word
/// aligned.
unsafe fn copy_text_state(dst: usize, src: usize) {
    let mut index = 0usize;
    while index < 0x19 {
        platform::write_u32(dst + index * 4, platform::read_u32(src + index * 4));
        index += 1;
    }
}

/// Draws a whole text buffer and reports the box it occupied through `out`.
///
/// The four-word rectangle at `out` starts at the [`SDA2_F32_4C34`] sentinel
/// and grows over every glyph: `[0]`/`[1]` take the minimum and `[2]`/`[3]` the
/// maximum of the layout worker's per-glyph rectangle. The object's `+0x2C` and
/// `+0x30` cursor fields are reset to the sentinel first.
///
/// [`fn_8022f350`] is called repeatedly with the buffer position and the bytes
/// still available (`start + length - cursor`); it advances the cursor one
/// glyph at a time until the buffer is consumed.
///
/// # Original
/// - Ghidra: `FUN_8022F960` at `0x8022F960` (272 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8022f960_FUN_8022f960.c`
///
/// # Arguments
/// - `object`: text state object passed through to [`fn_8022f350`].
/// - `out`: four `f32` receiving `{min_x, min_y, max_x, max_y}`.
/// - `start`: offset of the first byte of the text buffer.
/// - `length`: number of bytes in the buffer.
///
/// # Returns
/// Nothing; the box is written through `out`.
///
/// # Side effects
/// Resets `object + 0x2C`/`+0x30`, renders every glyph and writes four floats.
///
/// # Safety
/// `object` must satisfy [`fn_8022f350`]'s requirements and `out` must be
/// writable for four floats; the byte span `start..start + length` must be
/// readable by the decode routine.
///
/// # Confidence
/// medium - the box updates, the cursor reset and the loop bound are literal.
/// The export drops the layout worker's fourth argument at this call site; it
/// is the remaining byte count, proven by the loop bound and by the four-argument
/// call in `0x8022FA70`. The opening `ldexpf`/`GQR0` block is the compiler's
/// paired-single save of `f27..f31` and is not data flow.
pub unsafe fn fn_8022f960(object: usize, out: usize, start: u32, length: u32) {
    let sentinel = platform::read_f32(SDA2_F32_4C34);
    platform::write_f32(out, sentinel);
    platform::write_f32(out + 4, sentinel);
    platform::write_f32(out + 8, sentinel);
    platform::write_f32(out + 0x0C, sentinel);
    platform::write_f32(object + 0x2C, sentinel);
    platform::write_f32(object + 0x30, sentinel);

    let end = start.wrapping_add(length);
    let mut cursor = start;
    loop {
        let mut rect = crate::platform::GuestLocal::new( [sentinel; 4]);
        let base = rect.as_mut_ptr() as usize;
        let remaining = end.wrapping_sub(cursor);
        let _ = fn_8022f350(object, base, &mut cursor, remaining);

        platform::write_f32(out, platform::read_f32(out).min(platform::read_f32(base)));
        platform::write_f32(
            out + 4,
            platform::read_f32(out + 4).min(platform::read_f32(base + 4)),
        );
        platform::write_f32(
            out + 8,
            platform::read_f32(out + 8).max(platform::read_f32(base + 8)),
        );
        platform::write_f32(
            out + 0x0C,
            platform::read_f32(out + 0x0C).max(platform::read_f32(base + 0x0C)),
        );

        // observed: `while (0 < (param_3 + param_4) - local_38[0]);`
        if end.wrapping_sub(cursor) as i32 <= 0 {
            break;
        }
    }
}

