// `0x...A8` / `0x...AC` are the stripped EABI offset-to-top and type-info
// words (both zero, no RTTI in the image).

/// `r13 - 0x4A58` -> `0x8042AC28`: fourth word of the constructor-table list
/// chain. Slot 0 of the derived palette vtable returns this address; the base
/// slot 0 (`0x8022A570`) returns the third word at `0x8042AC20`.
const SDA_4A58_D283: usize = 0x8042_AC28;

/// `0x801B3080`: attach the current thread to the queue object passed in `r3`;
/// returns non-zero on success and `0` when another thread owns it.
const QUEUE_ATTACH_801B3080: usize = 0x801B_3080;

/// `0x801CF060`: start the asynchronous transfer of the descriptor at `r3`
/// with the completion callback in `r4`; returns non-zero when it started.
const STREAM_START_801CF060: usize = 0x801C_F060;

/// `0x80229F00`: completion dispatcher handed to [`STREAM_START_801CF060`].
///
/// It loads the object from `context + 0x3C`, clears the busy byte at `+0x24`
/// and tail-calls the callback stored at `+0x1C` with the context at `+0x20`.
/// `// observed:` the address sits one instruction pair into the untabled body
/// at `0x80229EA0`; the table stores it as a normal code pointer. The call site
/// materialises it with `lis r4,0x8023` / `addi r4,r4,-0x6100` -> `0x80229F00`.
const STREAM_DONE_80229F00: usize = 0x8022_9F00;

/// `0x801B1090`: convert a NUL-terminated encoded character to its code-table
/// byte; the second argument receives the looked-up byte.
const GLYPH_LOOKUP_801B1090: usize = 0x801B_1090;

/// `0x801B0F40`: metrics query for one encoded character
/// (`text`, `advance`, `x`, `y`, `index`).
const GLYPH_METRICS_801B0F40: usize = 0x801B_0F40;

/// Appends a block without reporting or advancing the cursor.
///
/// The body of [`fn_8022a380`] with the writer's result preserved: the capped
/// length is computed the same way and handed to `0x801CAB20`, whose return is
/// left in `r3` by the original. [`fn_8022a830`] returns that register value.
///
/// # Safety
/// `source` must be readable for the capped length and `object + 0x28` must
/// hold a live array.
unsafe fn d283_append_unreported(object: usize, source: u32, len: u32) -> u32 {
    let max = platform::read_u32(object + RANGE_OWNER_OFFSET);
    let cursor = platform::read_u32(object + 0x18);
    let mut want = len;
    if (max.wrapping_add(0x1F) & !0x1F) < (cursor.wrapping_add(len).wrapping_add(0x1F) & !0x1F) {
        want = max.wrapping_sub(cursor).wrapping_add(0x1F) & !0x1F;
    }
    platform::call5(
        WRITE_801CAB20,
        (object + ARRAY_OWNER_OFFSET) as u32,
        source,
        want,
        cursor,
        platform::read_u32(object + 0x68),
    )
}

/// Calls virtual method `slot_word` of `object` with one integer argument.
///
/// # Safety
/// `object` must begin with a vtable pointer whose `slot_word` word is a valid
/// function address with the `(object, argument)` ABI.
unsafe fn d283_vcall1(object: usize, slot_word: usize, argument: u32) -> u32 {
    let vtable = platform::read_u32(object) as usize;
    platform::call2(
        platform::read_u32(vtable + slot_word) as usize,
        object as u32,
        argument,
    )
}

